INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扣带回", "is_correct": true, "explanation": "正确：题干描述的是大脑中间、形状像带子的结构，正是扣带回。"}, {"text": "胃", "is_correct": false, "explanation": "语义：胃在腹部，不在大脑中间，与题干的位置描述矛盾。"}, {"text": "神经元", "is_correct": false, "explanation": "语义：神经元是单个细胞，不是像带子的结构，与“形状像带子”矛盾。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛不在大脑中间，也不是带状结构，与题干描述矛盾。"}], "explanations": {"扣带回": "正确：题干描述的是大脑中间、形状像带子的结构，正是扣带回。", "胃": "语义：胃在腹部，不在大脑中间，与题干的位置描述矛盾。", "神经元": "语义：神经元是单个细胞，不是像带子的结构，与“形状像带子”矛盾。", "眼睛": "语义：眼睛不在大脑中间，也不是带状结构，与题干描述矛盾。"}, "sentence_index": 6, "correct_answer": "扣带回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在模型上指出了一把扣带回的位置。", "explanation": "这里量词用错。“把”用于有柄或可握的物件，扣带回是脑区，应数“个”。"}, {"text": "老师在模型上指出了一粒扣带回的位置。", "explanation": "这里量词用错。“粒”用于很小的颗粒，扣带回是较大的脑区，应数“个”。"}, {"text": "他系紧了腰上的扣带回。", "explanation": "这里应该用〈皮带〉。扣带回指大脑里像带子的脑区，不是系在腰上的带子，系腰带应说皮带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在实验室里看见了一只扣带回。", "corrected_sentence": "我们在实验室里看见了一个扣带回。", "error_description": "量词错误：应为“一个扣带回”。“只”不用于脑区，扣带回应数“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在纸上画出了一片扣带回的样子。", "corrected_sentence": "他在纸上画出了一个扣带回的样子。", "error_description": "量词错误：应为“一个扣带回”。“片”用于平而薄的东西，扣带回是脑区，应数“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
