INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22956, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脑干是脑袋里的一小部分，它帮助身体做呼吸和心跳。", "primary_collocate": null, "pronunciation": "nǎo gàn", "ipa": "naʊ˨˩˦ kan˥˩", "syllable_count": 2, "sentences": [{"text": "脑干在头里面。", "target_word": "脑干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脑干帮我们呼吸。", "target_word": "脑干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脑干让心跳不停。", "target_word": "脑干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脑干很小，但是很重要。", "target_word": "脑干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们睡觉时，脑干也工作。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他头受伤了，医生检查他的脑干。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "脑干在脑袋的最下面。", "target_word": "脑干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "脑干管心跳，也管呼吸。", "target_word": "脑干", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师说脑干像大脑的小帮手。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生用机器看他的脑干好不好。", "target_word": "脑干", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "腦幹", "label": "繁体"}], "register": "中性", "sense_fingerprint": "脑袋里帮助呼吸和心跳的一小部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee052b8c-9e6c-48f8-b11a-3507e31e09ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脑干", "is_correct": true, "explanation": "脑干：位于头部的脑结构，符合句意。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏位于胸腔，不在头里面。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装东西的用具，不是人体结构。"}, {"text": "肝脏", "is_correct": false, "explanation": "搭配：肝脏位于腹部，“在头里面”不能用来描述它的位置。"}], "explanations": {"脑干": "脑干：位于头部的脑结构，符合句意。", "心脏": "语义：心脏位于胸腔，不在头里面。", "书包": "语义：书包是装东西的用具，不是人体结构。", "肝脏": "搭配：肝脏位于腹部，“在头里面”不能用来描述它的位置。"}, "sentence_index": 0, "correct_answer": "脑干"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脑干很灵活，考试总能拿高分。", "explanation": "这里应该用〈头脑〉。“脑干”是脑的一部分，说人聪明、反应快要用“头脑”。"}, {"text": "他的脑干很发达，所以特别聪明。", "explanation": "这里应该用〈大脑〉。“脑干”只指脑部的一小部分，说大脑发达、聪明要用“大脑”。"}, {"text": "他不小心把脑干撞破了，血流了一地。", "explanation": "这里应该用〈脑袋〉。“脑干”指脑内的一小部分，不是整个头部，说头部受伤要用“脑袋”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脑干", "is_correct": true, "explanation": "脑干：位于脑袋下部的结构，符合句意。"}, {"text": "帽子", "is_correct": false, "explanation": "语义：帽子戴在头顶，不在脑袋的最下面。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：眼睛位于脸部中间，不是脑袋的最下面。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：眼镜戴在眼前，“在脑袋的最下面”不能用来描述它的位置。"}], "explanations": {"脑干": "脑干：位于脑袋下部的结构，符合句意。", "帽子": "语义：帽子戴在头顶，不在脑袋的最下面。", "眼睛": "语义：眼睛位于脸部中间，不是脑袋的最下面。", "眼镜": "搭配：眼镜戴在眼前，“在脑袋的最下面”不能用来描述它的位置。"}, "sentence_index": 6, "correct_answer": "脑干"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "院子里那棵大树的脑干很粗。", "explanation": "这里应该用〈树干〉。“脑干”是脑内的一部分，树的主干要说“树干”。"}, {"text": "市场上的脑干很新鲜，我买了一些。", "explanation": "这里应该用〈猪脑〉。“脑干”是脑部结构，不能当食物卖；食用的脑子要说“猪脑”。"}, {"text": "他是我们球队的脑干，大家都很依赖他。", "explanation": "这里应该用〈骨干〉。“脑干”指脑部结构，比喻队伍中的核心成员要说“骨干”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的头里有一只脑干。", "corrected_sentence": "他的头里有一个脑干。", "error_description": "量词错误：“只”多用于动物或成对器官中的一个，脑干是单个结构，应说“一个脑干”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生把他的脑干照很清楚。", "corrected_sentence": "医生把他的脑干照得很清楚。", "error_description": "补语错误：动词“照”后带程度补语时需要“得”，应说“照得很清楚”，不能说“照很清楚”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
