INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "边缘系统是大脑的一部分，帮我们感受情绪和记住事情。", "primary_collocate": null, "pronunciation": "biān yuán xì tǒng", "ipa": "pjɛn⁵⁵ ɥɛn³⁵ ɕi⁵¹ tʰʊŋ²¹⁴", "syllable_count": 4, "sentences": [{"text": "边缘系统是大脑的一部分。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边缘系统帮我们感受情绪。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们能记住事情，也靠边缘系统。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到好朋友，边缘系统会让你高兴。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在图上指出了边缘系统。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "边缘系统受伤后，病人可能记不住事情。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书上说，边缘系统和情绪有关。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在学习边缘系统怎么影响心情。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "害怕的时候，边缘系统很活跃。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生给我们看了边缘系统的图片。", "target_word": "边缘系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "邊緣系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大脑的一部分，帮助感受情绪和记住事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee052b8c-9e6c-48f8-b11a-3507e31e09ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "边缘系统", "is_correct": true, "explanation": "正确：边缘系统是大脑的一部分，与语境相符。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏不属于大脑，不能作为其一部分。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：图书馆是建筑，不是大脑的组成部分。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“的一部分”修饰的是具体器官，“大海”是自然景观，不能这样组合。"}], "explanations": {"边缘系统": "正确：边缘系统是大脑的一部分，与语境相符。", "心脏": "语义：心脏不属于大脑，不能作为其一部分。", "图书馆": "语义：图书馆是建筑，不是大脑的组成部分。", "大海": "搭配：“的一部分”修饰的是具体器官，“大海”是自然景观，不能这样组合。"}, "sentence_index": 0, "correct_answer": "边缘系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "看到好朋友，边缘系统会变好。", "explanation": "这里应该用〈心情〉。边缘系统是脑结构，不能说“变好”，描述情绪要用心情。"}, {"text": "我住在边缘系统里。", "explanation": "这里应该用〈房子〉。边缘系统是大脑结构，人不能住在其中。"}, {"text": "他把书放在边缘系统上。", "explanation": "这里应该用〈桌子〉。边缘系统不是可以放东西的平台。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "边缘系统", "is_correct": true, "explanation": "正确：边缘系统与情绪的联系符合书中的说法。"}, {"text": "正方形", "is_correct": false, "explanation": "语义：正方形是几何图形，与情绪没有联系。"}, {"text": "大米", "is_correct": false, "explanation": "语义：大米是食物，与情绪没有神经联系。"}, {"text": "钢铁", "is_correct": false, "explanation": "搭配：“和…有关”接的是事件或概念，“钢铁”作为材料不能与“情绪”这样组合。"}], "explanations": {"边缘系统": "正确：边缘系统与情绪的联系符合书中的说法。", "正方形": "语义：正方形是几何图形，与情绪没有联系。", "大米": "语义：大米是食物，与情绪没有神经联系。", "钢铁": "搭配：“和…有关”接的是事件或概念，“钢铁”作为材料不能与“情绪”这样组合。"}, "sentence_index": 6, "correct_answer": "边缘系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他背着边缘系统去学校。", "explanation": "这里应该用〈书包〉。边缘系统在大脑里，不能被背着携带。"}, {"text": "我的边缘系统每天都在院子里跑。", "explanation": "这里应该用〈小狗〉。边缘系统是脑结构，不会跑动。"}, {"text": "妈妈烤了一盘边缘系统。", "explanation": "这里应该用〈饼干〉。边缘系统是脑结构，不能作为食物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生给我们讲解了一条边缘系统的结构。", "corrected_sentence": "医生给我们讲解了一套边缘系统的结构。", "error_description": "量词错误：“边缘系统”应配〈套〉，“条”用于细长的事物，不用来计量系统。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "医生以前了检查过边缘系统。", "corrected_sentence": "医生以前检查过边缘系统。", "error_description": "语序错误：完成体“了”不能放在动词前，“以前了检查过”应删去多余的“了”，写作“以前检查过边缘系统”，保留经历体“过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '084f3689-d866-4b50-a040-33b42f394f48') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
