INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种机器，能拍出身体里面的照片，帮医生找到生病的地方。", "primary_collocate": null, "pronunciation": "cí gòng zhèn", "ipa": "tsʰɨ˧˥ kʊŋ˥˩ ʈʂən˥˩", "syllable_count": 3, "sentences": [{"text": "医生让我去拍磁共振，看看膝盖有没有问题。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁共振是一台很大的机器。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "躺进磁共振里，机器会发出很大的声音。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁共振能拍出身体里面的照片。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的头一直疼，医生让她做磁共振。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次做磁共振，心里有点紧张。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家医院有两台磁共振，病人不用排很久的队。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做磁共振以前，要把身上的金属东西拿下来。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "磁共振拍出来的照片，医生看得很清楚。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他腿受伤了，医院给他安排了磁共振。", "target_word": "磁共振", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "核磁共振", "label": "复合"}, {"form": "磁共振成像", "label": "复合"}], "register": "中性", "sense_fingerprint": "医院里拍身体内部照片的大型检查机器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "磁共振", "is_correct": true, "explanation": "正确。磁共振是医学检查设备，“拍磁共振”指做这项检查，用来查看膝盖的问题，与语境相符。"}, {"text": "空调", "is_correct": false, "explanation": "语义：空调是家用电器，不是医学检查设备，与看膝盖问题的语境不符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人体检查的对象，与膝盖检查的语境不符。"}, {"text": "体温", "is_correct": false, "explanation": "配价：“拍”要求可以拍摄的对象，“体温”是数值，不能被“拍”。"}], "explanations": {"磁共振": "正确。磁共振是医学检查设备，“拍磁共振”指做这项检查，用来查看膝盖的问题，与语境相符。", "空调": "语义：空调是家用电器，不是医学检查设备，与看膝盖问题的语境不符。", "天气": "语义：天气不是人体检查的对象，与膝盖检查的语境不符。", "体温": "配价：“拍”要求可以拍摄的对象，“体温”是数值，不能被“拍”。"}, "sentence_index": 0, "correct_answer": "磁共振"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "医生给我量了磁共振，看看有没有发烧。", "explanation": "这里应该用〈体温计〉。量的是体温、血压这类能读出数值的东西；磁共振是拍身体内部照片的检查，不能说量磁共振。"}, {"text": "医生用磁共振听心跳，看看心脏正不正常。", "explanation": "这里应该用〈听诊器〉。听心跳要用听诊器；磁共振靠强磁场和无线电波拍照，不能用来听。"}, {"text": "医生给我测了磁共振，看看血压正不正常。", "explanation": "这里应该用〈血压计〉。测血压要用血压计；磁共振拍的是体内结构的照片，不能说测磁共振。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "磁共振", "is_correct": true, "explanation": "正确。“磁共振”是医院的大型检查设备，“两台”与“病人不用排很久的队”指医院可提供检查的机器，符合语境。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：钢琴是乐器，与医院的检查设备语境不符，句意不通。"}, {"text": "坦克", "is_correct": false, "explanation": "语域：“坦克”属于军事用语，与医院设备的语域不符。"}, {"text": "发动机", "is_correct": false, "explanation": "语义：发动机是机械动力部件，不是医院里的检查设备，句意不通。"}], "explanations": {"磁共振": "正确。“磁共振”是医院的大型检查设备，“两台”与“病人不用排很久的队”指医院可提供检查的机器，符合语境。", "钢琴": "语义：钢琴是乐器，与医院的检查设备语境不符，句意不通。", "坦克": "语域：“坦克”属于军事用语，与医院设备的语域不符。", "发动机": "语义：发动机是机械动力部件，不是医院里的检查设备，句意不通。"}, "sentence_index": 6, "correct_answer": "磁共振"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生用磁共振量了他的体重，看看胖不胖。", "explanation": "这里应该用〈体重秤〉。量体重要用体重秤；磁共振拍的是身体内部的照片，不能用来量体重。"}, {"text": "医生用磁共振化验血糖，结果很快就出来了。", "explanation": "这里应该用〈化验〉。血糖要抽血后在化验室检测；磁共振只能拍身体内部的照片，不能化验血糖。"}, {"text": "医生用磁共振测了他的身高。", "explanation": "这里应该用〈身高计〉。测身高要用身高计；磁共振拍的是身体内部的照片，不能用来测身高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家医院买了一把磁共振。", "corrected_sentence": "这家医院买了一台磁共振。", "error_description": "量词错误：磁共振是大型机器，应用“台”，不能用“把”；“把”用于有柄或可握的物件。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台磁共振运行的很稳定。", "corrected_sentence": "这台磁共振运行得很稳定。", "error_description": "补语标记错误：“运行”后引出补语应用“得”，写成“的”不对；正确形式为“运行得很稳定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
