INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22962, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "难闻的气味，比如东西坏了。", "primary_collocate": null, "pronunciation": "chòu wèi", "ipa": "ʈʂʰou˥˩ wei˥˩", "syllable_count": 2, "sentences": [{"text": "厕所里有臭味，请开窗。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剩菜坏了，发出了臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里的臭味让我很难受。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿鞋放太久会有臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河有臭味，没人去游泳。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾车走过，留下一阵臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用香皂洗手，去掉了臭味。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蛋坏了，臭味很大。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨房里一点臭味也没有。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天，垃圾的臭味特别重。", "target_word": "臭味", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一股臭味", "label": "量词"}], "register": "中性", "sense_fingerprint": "臭味：东西坏了后难闻的气味", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c5c45db-5c3c-48d5-93a0-704ede77efae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22962, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "臭味", "is_correct": true, "explanation": "正确：厕所里有难闻的气味，需要开窗通风，符合语境。"}, {"text": "钱", "is_correct": false, "explanation": "语义：厕所里有钱不需要开窗，“有钱，请开窗”不通。"}, {"text": "熊", "is_correct": false, "explanation": "语义：厕所里有熊需要的是离开，与“请开窗”的语境不符。"}, {"text": "胡子", "is_correct": false, "explanation": "体貌：“胡子”是人体部位，不能作为房间里需要通风的东西。"}], "explanations": {"臭味": "正确：厕所里有难闻的气味，需要开窗通风，符合语境。", "钱": "语义：厕所里有钱不需要开窗，“有钱，请开窗”不通。", "熊": "语义：厕所里有熊需要的是离开，与“请开窗”的语境不符。", "胡子": "体貌：“胡子”是人体部位，不能作为房间里需要通风的东西。"}, "sentence_index": 0, "correct_answer": "臭味"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支蜡烛的臭味很好闻。", "explanation": "这里应该用〈气味〉。臭味专指难闻的气味，不能用来形容好闻的蜡烛香气。"}, {"text": "清晨的森林弥漫着清新的臭味。", "explanation": "这里应该用〈气息〉。臭味只指难闻的气味，不能与“清新”搭配。"}, {"text": "屋里有一把臭味，很难受。", "explanation": "量词错误：臭味应用量词“股”，“把”用于有柄的东西，不能用来数气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22962, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "臭味", "is_correct": true, "explanation": "正确：香皂能去除手上的难闻气味，符合语境。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音不能被香皂去掉，“去掉了声音”句子不通。"}, {"text": "知识", "is_correct": false, "explanation": "搭配：“去掉”用于可清除的东西，“知识”不能被香皂去掉。"}, {"text": "脚", "is_correct": false, "explanation": "体貌：“脚”是人体部位，用香皂洗手不会去掉脚。"}], "explanations": {"臭味": "正确：香皂能去除手上的难闻气味，符合语境。", "声音": "语义：声音不能被香皂去掉，“去掉了声音”句子不通。", "知识": "搭配：“去掉”用于可清除的东西，“知识”不能被香皂去掉。", "脚": "体貌：“脚”是人体部位，用香皂洗手不会去掉脚。"}, "sentence_index": 6, "correct_answer": "臭味"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间屋子里有一根臭味。", "explanation": "量词错误：臭味应用量词“股”，“根”用于细长的东西，不能用来数气味。"}, {"text": "这锅汤的臭味很鲜美。", "explanation": "这里应该用〈味道〉。臭味只指难闻的气味，不能用来形容鲜美的汤。"}, {"text": "厨房里飘着一束臭味。", "explanation": "量词错误：臭味应用量词“股”，“束”用于成束的东西，不能用来数气味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22962, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "卫生间里有一个臭味，要通风。", "corrected_sentence": "卫生间里有一股臭味，要通风。", "error_description": "量词错误：“臭味”应用量词“股”，说“一股臭味”；“个”不能用来数气味。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22962, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房里有很大臭味，快开窗。", "corrected_sentence": "厨房里有很大的臭味，快开窗。", "error_description": "漏用“的”：“很大”修饰“臭味”时中间要加“的”，应为“很大的臭味”，不能说“很大臭味”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8df80060-e335-49eb-bdcd-ad2ec8bd1e8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
