INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22966, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "肉类是可以吃的动物身上的肉的总称，如鸡肉、猪肉、牛肉等。", "primary_collocate": null, "pronunciation": "ròu lèi", "ipa": "ʐoʊ˥˩ leɪ˥˩", "syllable_count": 2, "sentences": [{"text": "妈妈在市场的肉类摊位买了很多肉。", "target_word": "肉类", "complexity_tier": "T3", "furigana": "mā ma zài shì chǎng de ròu lèi tān wèi mǎi le hěn duō ròu.", "sentence_source": "generated"}, {"text": "鸡肉、猪肉都是肉类。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗最爱的食物是肉类。", "target_word": "肉类", "complexity_tier": "T3", "furigana": "xiǎo gǒu zuì ài de shí wù shì ròu lèi.", "sentence_source": "generated"}, {"text": "他对肉类没兴趣，只吃青菜和水果。", "target_word": "肉类", "complexity_tier": "T3", "furigana": "tā duì ròu lèi méi xìngqù, zhǐ chī qīng cài hé shuǐ guǒ.", "sentence_source": "generated"}, {"text": "这个商店只卖肉类，不卖水果。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肉类要煮熟了才能吃。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牛肉是我最喜欢的肉类。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冰箱的上面放水果，下面放肉类。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老虎和狮子都吃肉类，不吃草。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭前，请先把肉类洗干净。", "target_word": "肉类", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "肉類", "label": "繁体"}], "register": "中性", "sense_fingerprint": "肉类：我们可以吃的动物身上的部分，如鸡肉、猪肉、牛肉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c5b8b77-dd74-4ebf-9b21-c87de876915c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22966, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肉类", "is_correct": true, "explanation": "正确。“肉类摊位”是卖肉的地方，与后句“买了很多肉”的语境一致。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜摊位不卖肉，与“买了很多肉”的语境不符。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果摊位同样不卖肉，这里的语境无法成立。"}, {"text": "文具", "is_correct": false, "explanation": "搭配：“文具”与“在摊位买很多肉”的语境不搭配，市场里的摊位不会卖文具与肉的组合。"}], "explanations": {"肉类": "正确。“肉类摊位”是卖肉的地方，与后句“买了很多肉”的语境一致。", "蔬菜": "语义：蔬菜摊位不卖肉，与“买了很多肉”的语境不符。", "水果": "语义：水果摊位同样不卖肉，这里的语境无法成立。", "文具": "搭配：“文具”与“在摊位买很多肉”的语境不搭配，市场里的摊位不会卖文具与肉的组合。"}, "sentence_index": 0, "correct_answer": "肉类"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在超市买了一块肉类。", "explanation": "这里不能用〈块〉。〈块〉用于一块具体的肉，“肉类”是一类食物，应说“一种肉类”。"}, {"text": "他经常锻炼，肉类很发达。", "explanation": "这里应该用〈肌肉〉。“肌肉”是人体组织，可以说“发达”；“肉类”是食物，不能用来形容身体。"}, {"text": "他穿了一件肉类的上衣。", "explanation": "这里应该用〈肉色〉。“肉色”表示颜色，“肉类”是食品类别，不能用来形容衣服的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22966, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肉类", "is_correct": true, "explanation": "正确。“牛肉”属于“肉类”，这是“最喜欢的肉类”的正确所属关系。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：牛肉是食物，不是饮料，“最喜欢的饮料”不能指牛肉。"}, {"text": "调料", "is_correct": false, "explanation": "语义：牛肉是主要食材，不是调料，与“最喜欢的调料”的所属类别矛盾。"}, {"text": "茶叶", "is_correct": false, "explanation": "搭配：“最喜欢的茶叶”本身可以说，但牛肉不能归入茶叶一类，两者不能构成同类成员的搭配。"}], "explanations": {"肉类": "正确。“牛肉”属于“肉类”，这是“最喜欢的肉类”的正确所属关系。", "饮料": "语义：牛肉是食物，不是饮料，“最喜欢的饮料”不能指牛肉。", "调料": "语义：牛肉是主要食材，不是调料，与“最喜欢的调料”的所属类别矛盾。", "茶叶": "搭配：“最喜欢的茶叶”本身可以说，但牛肉不能归入茶叶一类，两者不能构成同类成员的搭配。"}, "sentence_index": 6, "correct_answer": "肉类"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我今天买了一把肉类。", "explanation": "这里不能用〈把〉。“肉类”是一类食物，不能用“一把”计量，应说“一些肉”或“一种肉类”。"}, {"text": "狮子是一种肉类动物。", "explanation": "这里应该用〈肉食〉。“肉食动物”指以肉为食的动物，“肉类”不能用来修饰“动物”。"}, {"text": "我们学校门口有一家肉类。", "explanation": "这里应该用〈肉铺〉。“肉铺”是卖肉的店，可以说“一家肉铺”；“肉类”是食物类别，不能指店铺。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22966, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市场里有好几块肉类可以挑。", "corrected_sentence": "市场里有好几种肉类可以挑。", "error_description": "量词错误：“肉类”指多种食物，应用〈种〉；〈块〉只用于一块具体的肉，不能用于类别。正确说法是“好几种肉类”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22966, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我家冰箱里有一个肉类。", "corrected_sentence": "我家冰箱里有一些肉类。", "error_description": "量词错误：“肉类”是一类食物，不能用〈个〉计量。应说“一些肉类”或“一种肉类”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
