INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22968, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "油是做饭用的东西，能让菜更好吃。", "primary_collocate": null, "pronunciation": "yóu", "ipa": "jou˧˥", "syllable_count": 1, "sentences": [{"text": "炒菜以前，先在锅里倒一点油。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "家里的油用完了，我去超市买一瓶。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做饭的时候，油不要放得太多。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸把油倒进锅里，开始炒鸡蛋。", "target_word": "油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "油热了以后，再把青菜放进去。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她买了一桶油，打算放在厨房里。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这道菜放了很多油，所以有点腻。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "煎鱼的时候，锅里要先放油，不然会粘锅。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她用一点油把鸡蛋煎得黄黄的。", "target_word": "油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这瓶油是我昨天刚买的，还没打开。", "target_word": "油", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "桶", "label": "量词"}, {"form": "滴", "label": "量词"}, {"form": "食用油", "label": "复合词"}, {"form": "花生油", "label": "复合词"}], "register": "中性", "sense_fingerprint": "做饭炒菜用的食用油", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22968, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "油", "is_correct": true, "explanation": "正确。油 yóu（第二声），指做饭用的食用油。"}, {"text": "又", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是又、再。"}, {"text": "右", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是右边。"}, {"text": "优", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是优秀。"}, {"text": "忧", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是担心。"}], "explanations": {"油": "正确。油 yóu（第二声），指做饭用的食用油。", "又": "yòu（第四声）与 yóu（第二声）声调不同，意思是又、再。", "右": "yòu（第四声）与 yóu（第二声）声调不同，意思是右边。", "优": "yōu（第一声）与 yóu（第二声）声调不同，意思是优秀。", "忧": "yōu（第一声）与 yóu（第二声）声调不同，意思是担心。"}, "sentence_index": null, "correct_answer": "油"}, "level_3": {"options": [{"text": "油", "is_correct": true, "explanation": "正确。炒菜前在锅里倒一点，指食用油。"}, {"text": "沙子", "is_correct": false, "explanation": "语义：沙子不是食材，不能用来炒菜，与“炒菜”的语境不符。"}, {"text": "洗衣粉", "is_correct": false, "explanation": "语义：洗衣粉是清洁用品，不能倒进锅里做菜。"}, {"text": "冰块", "is_correct": false, "explanation": "搭配：“倒”的对象通常是液体或粉末，冰块是固体，应说“放”而不说“倒”。"}], "explanations": {"油": "正确。炒菜前在锅里倒一点，指食用油。", "沙子": "语义：沙子不是食材，不能用来炒菜，与“炒菜”的语境不符。", "洗衣粉": "语义：洗衣粉是清洁用品，不能倒进锅里做菜。", "冰块": "搭配：“倒”的对象通常是液体或粉末，冰块是固体，应说“放”而不说“倒”。"}, "sentence_index": 0, "correct_answer": "油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一根油放在厨房里。", "explanation": "这里应该用〈瓶〉。油是液体，用“根”不对，“根”用于细长的东西。"}, {"text": "做蛋糕时，他多放了一点油，结果蛋糕很甜。", "explanation": "这里应该用〈糖〉。油不能使蛋糕变甜，甜味要用〈糖〉。"}, {"text": "我买了一块油放进了柜子里。", "explanation": "这里应该用〈瓶〉。“块”用于固体，油是液体，不能用“块”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22968, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "油", "is_correct": true, "explanation": "正确。油 yóu（第二声），指做饭用的食用油。"}, {"text": "有", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有。"}, {"text": "友", "is_correct": false, "explanation": "yǒu（第三声）与 yóu（第二声）声调不同，意思是朋友。"}, {"text": "幼", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是年幼。"}, {"text": "柚", "is_correct": false, "explanation": "yòu（第四声）与 yóu（第二声）声调不同，意思是柚子。"}, {"text": "悠", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是悠闲。"}], "explanations": {"油": "正确。油 yóu（第二声），指做饭用的食用油。", "有": "yǒu（第三声）与 yóu（第二声）声调不同，意思是有。", "友": "yǒu（第三声）与 yóu（第二声）声调不同，意思是朋友。", "幼": "yòu（第四声）与 yóu（第二声）声调不同，意思是年幼。", "柚": "yòu（第四声）与 yóu（第二声）声调不同，意思是柚子。", "悠": "yōu（第一声）与 yóu（第二声）声调不同，意思是悠闲。"}, "sentence_index": null, "correct_answer": "油"}, "level_3": {"options": [{"text": "油", "is_correct": true, "explanation": "正确。油是造成菜“腻”的原因，指食用油。"}, {"text": "辣椒", "is_correct": false, "explanation": "语义：辣椒会使菜变辣，不会使菜腻，与“有点腻”不符。"}, {"text": "冰", "is_correct": false, "explanation": "语义：冰放进菜里不会使菜腻，与“有点腻”不符。"}, {"text": "木头", "is_correct": false, "explanation": "搭配：“放了很多”后面接的是调料或食材，木头不是食材，不能放进菜里。"}], "explanations": {"油": "正确。油是造成菜“腻”的原因，指食用油。", "辣椒": "语义：辣椒会使菜变辣，不会使菜腻，与“有点腻”不符。", "冰": "语义：冰放进菜里不会使菜腻，与“有点腻”不符。", "木头": "搭配：“放了很多”后面接的是调料或食材，木头不是食材，不能放进菜里。"}, "sentence_index": 6, "correct_answer": "油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在超市买了一条油。", "explanation": "这里应该用〈瓶〉。“条”用于细长的东西，油是液体，不能用“条”。"}, {"text": "厨房的柜子里放着一把油。", "explanation": "这里应该用〈瓶〉。“把”用于有柄的器具，油不用“把”。"}, {"text": "做汤时多加了一勺油，汤就变咸了。", "explanation": "这里应该用〈盐〉。油不能让汤变咸，咸味要用〈盐〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈昨天买了一只油，放在厨房里。", "corrected_sentence": "妈妈昨天买了一瓶油，放在厨房里。", "error_description": "量词错误：油是液体，应用“瓶”计量，不能用“只”，应说“一瓶油”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "炒菜前，他先油把倒进锅里。", "corrected_sentence": "炒菜前，他先把油倒进锅里。", "error_description": "“把”字句语序错误：“把”应放在宾语“油”之前，应说“把油倒进锅里”，不说“油把倒进锅里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
