INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22972, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西翻转过来，使正反面或上下颠倒。", "primary_collocate": null, "pronunciation": "fān", "ipa": "fan˥", "syllable_count": 1, "sentences": [{"text": "请把这张纸翻过来，背面有名字。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯子翻过来，放在架子上晾干。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡片翻过来，你就能看到答案。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "衣服穿反了，快把它翻过来。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手翻过来，手心向上。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把桌子翻过来，我们检查一下桌腿。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个袋子里面脏了，把它翻过来洗。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把照片翻过来，后面有日期。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把盘子翻过来，底下有店名。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把外套翻过来穿，里面的颜色更好看。", "target_word": "翻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻了", "label": "体标"}, {"form": "翻过", "label": "体标"}, {"form": "翻翻", "label": "重叠"}, {"form": "翻动", "label": "复合"}], "register": "中性", "sense_fingerprint": "把纸、杯子、衣服等翻转过来，正反面或上下颠倒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "翻", "is_correct": true, "explanation": "正确。fān（第一声）是翻，意思是把东西翻转过来。"}, {"text": "饭", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是米饭。"}, {"text": "方", "is_correct": false, "explanation": "fāng 与 fān 韵母不同（ang 与 an），意思是方形。"}, {"text": "分", "is_correct": false, "explanation": "fēn 与 fān 韵母不同（en 与 an），意思是分开。"}, {"text": "凡", "is_correct": false, "explanation": "fán（第二声）与 fān（第一声）声调不同，意思是凡是、所有。"}], "explanations": {"翻": "正确。fān（第一声）是翻，意思是把东西翻转过来。", "饭": "fàn（第四声）与 fān（第一声）声调不同，意思是米饭。", "方": "fāng 与 fān 韵母不同（ang 与 an），意思是方形。", "分": "fēn 与 fān 韵母不同（en 与 an），意思是分开。", "凡": "fán（第二声）与 fān（第一声）声调不同，意思是凡是、所有。"}, "sentence_index": null, "correct_answer": "翻"}, "level_3": {"options": [{"text": "翻", "is_correct": true, "explanation": "正确：“翻过来”表示把纸的正反面颠倒，与“背面有名字”相符。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”指把纸扯破，与使纸正反面颠倒无关。"}, {"text": "烧", "is_correct": false, "explanation": "搭配：“烧”不能与“过来”组合，表示纸张正反面颠倒。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”不能与“过来”组合，表示把纸转到正面或背面。"}], "explanations": {"翻": "正确：“翻过来”表示把纸的正反面颠倒，与“背面有名字”相符。", "撕": "语义：“撕”指把纸扯破，与使纸正反面颠倒无关。", "烧": "搭配：“烧”不能与“过来”组合，表示纸张正反面颠倒。", "写": "搭配：“写”不能与“过来”组合，表示把纸转到正面或背面。"}, "sentence_index": 0, "correct_answer": "翻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他翻上了新衣服。", "explanation": "这里应该用〈穿〉。翻是使物体翻转，不指把衣服套在身上。"}, {"text": "他用毛巾翻干了脸。", "explanation": "这里应该用〈擦〉。翻只能使物体翻转，不能表示擦去脸上的水。"}, {"text": "他翻好了扣子。", "explanation": "这里应该用〈扣〉。翻不用于系扣子，只表示使物体翻转。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "翻", "is_correct": true, "explanation": "正确。fān（第一声）是翻，意思是把东西翻转过来。"}, {"text": "烦", "is_correct": false, "explanation": "fán（第二声）与 fān（第一声）声调不同，意思是烦恼。"}, {"text": "犯", "is_correct": false, "explanation": "fàn（第四声）与 fān（第一声）声调不同，意思是犯错、违反。"}, {"text": "返", "is_correct": false, "explanation": "fǎn（第三声）与 fān（第一声）声调不同，意思是返回。"}, {"text": "方", "is_correct": false, "explanation": "fāng 与 fān 韵母不同（ang 与 an），意思是方形。"}], "explanations": {"翻": "正确。fān（第一声）是翻，意思是把东西翻转过来。", "烦": "fán（第二声）与 fān（第一声）声调不同，意思是烦恼。", "犯": "fàn（第四声）与 fān（第一声）声调不同，意思是犯错、违反。", "返": "fǎn（第三声）与 fān（第一声）声调不同，意思是返回。", "方": "fāng 与 fān 韵母不同（ang 与 an），意思是方形。"}, "sentence_index": null, "correct_answer": "翻"}, "level_3": {"options": [{"text": "翻", "is_correct": true, "explanation": "正确：“翻过来洗”表示把袋子内外颠倒后清洗，与语境相符。"}, {"text": "踩", "is_correct": false, "explanation": "语义：“踩”指用脚压，与使袋子内外翻转无关。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”不能与“袋子”搭配，表示使袋子翻面。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指抹去污物，与把袋子翻过来清洗的意思不符。"}], "explanations": {"翻": "正确：“翻过来洗”表示把袋子内外颠倒后清洗，与语境相符。", "踩": "语义：“踩”指用脚压，与使袋子内外翻转无关。", "咬": "搭配：“咬”不能与“袋子”搭配，表示使袋子翻面。", "擦": "语义：“擦”指抹去污物，与把袋子翻过来清洗的意思不符。"}, "sentence_index": 6, "correct_answer": "翻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她翻短了头发。", "explanation": "这里应该用〈剪〉。翻是使物体翻转，不表示用剪刀剪断。"}, {"text": "她翻着孩子睡觉。", "explanation": "这里应该用〈抱〉。翻不表示用手臂环抱。"}, {"text": "他翻住了开关。", "explanation": "这里应该用〈按〉。翻不表示用手压下。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "把这封信翻，背面有地址。", "corrected_sentence": "把这封信翻过来，背面有地址。", "error_description": "错误：“把这封信翻”；正确：“把这封信翻过来”。“把”字句的动词后必须带结果补语，这里应补“过来”，表示翻转后的结果。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你把名片翻来过，背面有电话。", "corrected_sentence": "你把名片翻过来，背面有电话。", "error_description": "错误：“翻来过”；正确：“翻过来”。趋向补语“过来”的语序是“过”在前、“来”在后，不能颠倒。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
