INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22976, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "身体里像网一样的东西，帮助大脑告诉身体怎么做。", "primary_collocate": null, "pronunciation": "shén jīng xì tǒng", "ipa": "ʂən˧˥ tɕiŋ˥ ɕi˥˩ tʰʊŋ˨˩˦", "syllable_count": 4, "sentences": [{"text": "神经系统像一张网，在身体里面。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大脑通过神经系统告诉手怎么动。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经系统帮助大脑指挥身体。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的手碰到火，神经系统让你马上缩回来。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体里的神经系统很像一张大网。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有神经系统，身体就不知道怎么做。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师画了人的神经系统，像很多线。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经系统把大脑的话传给身体。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗也有神经系统，所以它会跑会跳。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "神经系统让我们能感到热和冷。", "target_word": "神经系统", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "中枢神经系统", "label": "复合"}, {"form": "神經系統", "label": "繁体"}], "register": "中性", "sense_fingerprint": "身体里像网一样、帮助大脑指挥身体的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3dced0e1-ca52-4764-bae4-ec3acb1be799') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22976, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神经系统", "is_correct": true, "explanation": "正确。神经系统在身体内部纵横分布、形成网络，与“像一张网，在身体里面”的描述相符。"}, {"text": "脊柱", "is_correct": false, "explanation": "语义：脊柱是一排竖直的骨块，不是网状结构，与“像一张网”不符。"}, {"text": "心脏", "is_correct": false, "explanation": "语义：心脏是泵血的器官，形状和功能都不是网状，句中的比喻不成立。"}, {"text": "面貌", "is_correct": false, "explanation": "体貌：“面貌”指外观样子，不指体内结构，与“在身体里面”矛盾。"}], "explanations": {"神经系统": "正确。神经系统在身体内部纵横分布、形成网络，与“像一张网，在身体里面”的描述相符。", "脊柱": "语义：脊柱是一排竖直的骨块，不是网状结构，与“像一张网”不符。", "心脏": "语义：心脏是泵血的器官，形状和功能都不是网状，句中的比喻不成立。", "面貌": "体貌：“面貌”指外观样子，不指体内结构，与“在身体里面”矛盾。"}, "sentence_index": 0, "correct_answer": "神经系统"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "神经系统负责思考和记忆。", "explanation": "这里应该用〈大脑〉。思考和记忆由大脑负责；神经系统传递信息、控制身体，不负责思考和记忆。"}, {"text": "神经系统是一个细胞，很小。", "explanation": "这里应该用〈神经元〉。神经系统是全身的整个系统，由许多神经元组成，不是单个细胞。"}, {"text": "他的手指被刀割伤了神经系统。", "explanation": "这里应该用〈神经〉。手指被割伤的只是其中几根神经，神经系统指全身的整个系统，不能说割伤了神经系统。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22976, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神经系统", "is_correct": true, "explanation": "正确。“神经系统”像很多线，指人体内纵横交错的传递网络，与“老师画了”的描绘相符。"}, {"text": "地球", "is_correct": false, "explanation": "搭配：“人的地球”不成立，地球不属于人的身体，没有领属关系。"}, {"text": "护照", "is_correct": false, "explanation": "语义：护照是证件，不是人体内部结构，不能画成像很多线的样子。"}, {"text": "体重", "is_correct": false, "explanation": "配价：“画”要求可以描绘的形象，“体重”是数值，画不出“像很多线”的样子。"}], "explanations": {"神经系统": "正确。“神经系统”像很多线，指人体内纵横交错的传递网络，与“老师画了”的描绘相符。", "地球": "搭配：“人的地球”不成立，地球不属于人的身体，没有领属关系。", "护照": "语义：护照是证件，不是人体内部结构，不能画成像很多线的样子。", "体重": "配价：“画”要求可以描绘的形象，“体重”是数值，画不出“像很多线”的样子。"}, "sentence_index": 6, "correct_answer": "神经系统"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "身体里有一只神经系统，像一张网。", "explanation": "这里应该用〈套〉。“只”用于动物，神经系统是整体，应说“一套神经系统”。"}, {"text": "身体里有一根神经系统，像一张网。", "explanation": "这里应该用〈套〉。“根”用于细长之物，不能用于整个系统，应说“一套神经系统”。"}, {"text": "身体里有一颗神经系统，像一张网。", "explanation": "这里应该用〈套〉。“颗”用于小而圆的东西，神经系统是整体，应说“一套神经系统”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22976, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "神经系统把动作指挥地很准确。", "corrected_sentence": "神经系统把动作指挥得很准确。", "error_description": "补语错误：“指挥”后的程度补语应用“得”，不能用“地”，应说“指挥得很准确”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22976, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "神经系统的一直指挥着身体的动作。", "corrected_sentence": "神经系统一直指挥着身体的动作。", "error_description": "结构错误：“神经系统”作主语时后面不能加“的”，应说“神经系统一直指挥着身体的动作”；加“的”后主语结构不完整，句子不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a49a86c0-0524-4da3-81cd-5fb83a331079') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22978, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出去", "is_correct": true, "explanation": "与“进去”构成反义，表示从里面到外面。"}, {"text": "起来", "is_correct": false, "explanation": "语义：“起来”表示向上或开始，与“进去”不构成反义。"}, {"text": "过来", "is_correct": false, "explanation": "语义：“过来”表示朝说话人一侧移动，不是“进去”的反义词。"}, {"text": "下来", "is_correct": false, "explanation": "语义：“下来”表示从高处向低处，与“进去”不构成反义。"}], "correct_answer": "出去", "explanations": {"出去": "与“进去”构成反义，表示从里面到外面。", "起来": "语义：“起来”表示向上或开始，与“进去”不构成反义。", "过来": "语义：“过来”表示朝说话人一侧移动，不是“进去”的反义词。", "下来": "语义：“下来”表示从高处向低处，与“进去”不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22978, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "出来", "is_correct": true, "explanation": "与“进去”构成反义，指从里面到外面。"}, {"text": "上来", "is_correct": false, "explanation": "语义：“上来”表示向上或朝说话人一侧移动，不是“进去”的反义词。"}, {"text": "回来", "is_correct": false, "explanation": "语义：“回来”表示返回原处，不是“进去”的反义词。"}, {"text": "走开", "is_correct": false, "explanation": "语义：“走开”表示离去，与“进去”不构成反义。"}], "correct_answer": "出来", "explanations": {"出来": "与“进去”构成反义，指从里面到外面。", "上来": "语义：“上来”表示向上或朝说话人一侧移动，不是“进去”的反义词。", "回来": "语义：“回来”表示返回原处，不是“进去”的反义词。", "走开": "语义：“走开”表示离去，与“进去”不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22978, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从外面到里面。", "primary_collocate": null, "pronunciation": "jìn qù", "ipa": "tɕin˥˩ tɕʰy˥˩", "syllable_count": 2, "sentences": [{"text": "教室门开了，学生们一个一个进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车门打开后，他先让孩子进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里很黑，他不敢进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我到了门口，可是没有人让我进去。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，大家都跑进去躲雨。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说你们可以进去了。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店刚开门，很多人就走进去了。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着票，高兴地进去了。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫从窗户跳进去，找到了吃的。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里不能进去，请走那边。", "target_word": "进去", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "进去了", "label": "体标"}, {"form": "进去过", "label": "体标"}], "register": "中性", "sense_fingerprint": "人从外面走到房间、教室、商店等里面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '646a9811-93f6-4f9b-bfec-56a7c7ff221c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22978, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：进去（jìn qù）表示从外面到房间等里面。"}, {"text": "进取", "is_correct": false, "explanation": "qǔ（第三声）与 qù（第四声）声调不同，进取意思是努力向上。"}, {"text": "禁区", "is_correct": false, "explanation": "qū（第一声）与 qù（第四声）声调不同，禁区意思是禁止进入的区域。"}, {"text": "进气", "is_correct": false, "explanation": "qì 与 qù 的韵母不同（i 与 ü），进气意思是空气等进入发动机或身体。"}, {"text": "金曲", "is_correct": false, "explanation": "jīn qǔ 两个音节的声调都与 jìn qù 不同，金曲意思是流行歌曲。"}], "explanations": {"进去": "正确：进去（jìn qù）表示从外面到房间等里面。", "进取": "qǔ（第三声）与 qù（第四声）声调不同，进取意思是努力向上。", "禁区": "qū（第一声）与 qù（第四声）声调不同，禁区意思是禁止进入的区域。", "进气": "qì 与 qù 的韵母不同（i 与 ü），进气意思是空气等进入发动机或身体。", "金曲": "jīn qǔ 两个音节的声调都与 jìn qù 不同，金曲意思是流行歌曲。"}, "sentence_index": null, "correct_answer": "进去"}, "level_3": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：学生从门口走进教室，应用“进去”。"}, {"text": "进行", "is_correct": false, "explanation": "搭配：“进行”后要接动作宾语，不能说学生们进行。"}, {"text": "进化", "is_correct": false, "explanation": "语义：“进化”指生物或事物逐步发展，不指走进教室。"}, {"text": "进货", "is_correct": false, "explanation": "语义：“进货”指店铺购入商品，与学生走进教室无关。"}], "explanations": {"进去": "正确：学生从门口走进教室，应用“进去”。", "进行": "搭配：“进行”后要接动作宾语，不能说学生们进行。", "进化": "语义：“进化”指生物或事物逐步发展，不指走进教室。", "进货": "语义：“进货”指店铺购入商品，与学生走进教室无关。"}, "sentence_index": 0, "correct_answer": "进去"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在屋里喊他：你快进去吧。", "explanation": "这里应该用〈进来〉。说话人在屋里，叫对方从外面进入时要用“进来”，不用“进去”。"}, {"text": "她终于进去了决赛。", "explanation": "这里应该用〈进入〉。“进去”多用于具体空间的移动，决赛是抽象的阶段，应说“进入决赛”。"}, {"text": "一年进去了，他还是没有进展。", "explanation": "这里应该用〈过去〉。说时间流逝要用“过去”，“进去”只表示从外面到里面的移动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22978, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "进去", "is_correct": true, "explanation": "正确：人群走进商店，应用“进去”。"}, {"text": "出去", "is_correct": false, "explanation": "语义：“出去”指从里往外，与商店刚开门时人们走进去的句意相反。"}, {"text": "下去", "is_correct": false, "explanation": "语义：“下去”表示向下移动，与人群走进商店的动作不符。"}, {"text": "回去", "is_correct": false, "explanation": "语义：“回去”表示返回原处，与人群走进商店的动作不符。"}], "explanations": {"进去": "正确：人群走进商店，应用“进去”。", "出去": "语义：“出去”指从里往外，与商店刚开门时人们走进去的句意相反。", "下去": "语义：“下去”表示向下移动，与人群走进商店的动作不符。", "回去": "语义：“回去”表示返回原处，与人群走进商店的动作不符。"}, "sentence_index": 6, "correct_answer": "进去"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从屋里进去了外面。", "explanation": "这里应该用〈出去〉。从屋里到屋外要用“出去”，“进去”表示从外面到里面，方向相反。"}, {"text": "他爬进去了楼顶。", "explanation": "这里应该用〈上去〉。到楼顶是向上移动，要用“上去”；“进去”表示进入某个空间，楼顶不是可以进入的空间。"}, {"text": "他决定坚持进去。", "explanation": "这里应该用〈下去〉。“坚持下去”表示持续做下去，“进去”表示从外面到里面，不能与“坚持”搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "天气冷，大家快去进去暖和一下。", "corrected_sentence": "天气冷，大家快进去暖和一下。", "error_description": "错误形式：“去进去”。正确形式：“进去”。“去”多余，补语“进去”前不能再加“去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车门开了，你们先进去着坐好。", "corrected_sentence": "车门开了，你们先进去坐好。", "error_description": "错误形式：“进去着”。正确形式：“进去”。“着”不能加在趋向补语“进去”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22982, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
