INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "深褐色是一种颜色，像巧克力的颜色。", "primary_collocate": null, "pronunciation": "shēn hè sè", "ipa": "ʂən˥ xɤ˥˩ sɤ˥˩", "syllable_count": 3, "sentences": [{"text": "我喜欢深褐色的鞋。", "target_word": "深褐色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这张桌子是深褐色的。", "target_word": "深褐色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的眼睛是深褐色的。", "target_word": "深褐色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "深褐色的头发很好看。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "巧克力是深褐色的。", "target_word": "深褐色", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈买了一件深褐色的外套。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "秋天的树叶变成了深褐色。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只狗的毛是深褐色的。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咖啡倒进杯子里，是深褐色的。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想用深褐色画那棵树。", "target_word": "深褐色", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "深褐色：像巧克力一样的深棕色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20eaa319-c57d-469c-b2b7-b9adb94399fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "深褐色", "is_correct": true, "explanation": "深褐色：像巧克力一样的深棕色，用来描述鞋的颜色，句意通顺。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”不是颜色，不能用来描述鞋的颜色，句子不通。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：“鸡蛋”不是颜色，不能用来描述鞋的颜色，句子不通。"}, {"text": "脚", "is_correct": false, "explanation": "搭配：“脚”是身体部位，不能用来修饰鞋的颜色或属性，“脚的鞋”不成立。"}], "explanations": {"深褐色": "深褐色：像巧克力一样的深棕色，用来描述鞋的颜色，句意通顺。", "钢琴": "语义：“钢琴”不是颜色，不能用来描述鞋的颜色，句子不通。", "鸡蛋": "语义：“鸡蛋”不是颜色，不能用来描述鞋的颜色，句子不通。", "脚": "搭配：“脚”是身体部位，不能用来修饰鞋的颜色或属性，“脚的鞋”不成立。"}, "sentence_index": 0, "correct_answer": "深褐色"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的成绩是深褐色的。", "explanation": "这里应该用〈好〉。深褐色只表示颜色，形容成绩要用好、差这类评价词。"}, {"text": "这首歌的速度是深褐色的。", "explanation": "这里应该用〈快〉。深褐色只表示颜色，不能形容速度，形容速度要用快、慢这类词。"}, {"text": "这次旅行的价格是深褐色的。", "explanation": "这里应该用〈便宜〉。深褐色只表示颜色，不能形容价格，形容价格要用便宜、贵这类词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "深褐色", "is_correct": true, "explanation": "深褐色：作“变成了”的宾语，指树叶变成的颜色，句意通顺。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：树叶不能变成黑板，“变成了”后的名词要与树叶的变化相合。"}, {"text": "电话", "is_correct": false, "explanation": "语义：树叶不能变成电话，句意不通。"}, {"text": "高个子", "is_correct": false, "explanation": "体貌：“高个子”指人的身材，不能用来说树叶的变化。"}], "explanations": {"深褐色": "深褐色：作“变成了”的宾语，指树叶变成的颜色，句意通顺。", "黑板": "语义：树叶不能变成黑板，“变成了”后的名词要与树叶的变化相合。", "电话": "语义：树叶不能变成电话，句意不通。", "高个子": "体貌：“高个子”指人的身材，不能用来说树叶的变化。"}, "sentence_index": 6, "correct_answer": "深褐色"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她想用一个深褐色画那棵树。", "explanation": "颜色词作名词时应用量词“种”，不用“个”，这里的“一个深褐色”不成立。"}, {"text": "她想用深褐色的早晨画那棵树。", "explanation": "这里应该用〈颜料〉。深褐色是颜色，不能修饰“早晨”这样的时间。"}, {"text": "深褐色想用她画那棵树。", "explanation": "这里应该用〈颜料〉。深褐色是颜色，不能作“想”的主语，它只能描述所用颜料的颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张纸慢慢变了成深褐色。", "corrected_sentence": "这张纸慢慢变成了深褐色。", "error_description": "错误：“变成了”中“成”和“了”的顺序颠倒，写成“变了成”不通。正确为“这张纸慢慢变成了深褐色”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块布的颜色是一个深褐色。", "corrected_sentence": "这块布的颜色是一种深褐色。", "error_description": "错误：颜色词“深褐色”应该用量词“种”，不能用“个”。正确为“一种深褐色”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7465aff9-30bb-41b6-b4c7-ea4ded5614a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22986, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3e480613-ce31-44fe-8887-e49b4c0ab4f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
