INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22994, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "泥土是地上的土，可以种花。", "primary_collocate": null, "pronunciation": "ní tǔ", "ipa": "ni˧˥ tʰu˨˩˦", "syllable_count": 2, "sentences": [{"text": "院子里的泥土很软，适合种花。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用小铲子把泥土翻了一遍。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在花盆里加一点泥土。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他蹲在地上，用泥土堆了一座小山。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干燥的泥土一遇水就变黑了。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的泥土又黑又肥。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把泥土刨出了一个坑。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶用手摸了摸泥土，说该浇水了。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，泥土飞到了我脸上。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，泥土变得松软起来。", "target_word": "泥土", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一块泥土", "label": "量词"}, {"form": "一层泥土", "label": "量词"}], "register": "中性", "sense_fingerprint": "泥土：地上的土，可以用来种花", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'acd4d851-86a9-4cfd-a310-ec607390ed11') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22994, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "体貌：石头坚硬，与句中“很软”相反。"}, {"text": "泥土", "is_correct": true, "explanation": "这里指地上可以种花的土壤，与“很软，适合种花”相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "体貌：玻璃坚硬易碎，不可能“很软”。"}, {"text": "棉花", "is_correct": false, "explanation": "语义：棉花不是可以种花的土，“适合种花”不成立。"}], "explanations": {"石头": "体貌：石头坚硬，与句中“很软”相反。", "泥土": "这里指地上可以种花的土壤，与“很软，适合种花”相符。", "玻璃": "体貌：玻璃坚硬易碎，不可能“很软”。", "棉花": "语义：棉花不是可以种花的土，“适合种花”不成立。"}, "sentence_index": 0, "correct_answer": "泥土"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把这块泥土租给了邻居。", "explanation": "这里应该用〈土地〉。土地可以出租，是一块可以耕种或建设的地；泥土是地表的土质，不能出租。"}, {"text": "今年这片泥土的收成特别好。", "explanation": "这里应该用〈田地〉。收成指田地里种出的庄稼，泥土本身没有收成。"}, {"text": "这块泥土地段很好，离地铁站很近。", "explanation": "这里应该用〈地段〉。“地段”说的是地块的位置与价值，泥土只是土质，不能说地段好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22994, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气", "is_correct": false, "explanation": "语义：空气看不见、摸不着，不能被小狗刨出坑。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：“刨”一般用于土、雪等，不说“刨面包”。"}, {"text": "泥土", "is_correct": true, "explanation": "这里指被刨开的土壤，与“刨出了一个坑”相符。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮在天上，小狗不可能把它刨出一个坑。"}], "explanations": {"空气": "语义：空气看不见、摸不着，不能被小狗刨出坑。", "面包": "搭配：“刨”一般用于土、雪等，不说“刨面包”。", "泥土": "这里指被刨开的土壤，与“刨出了一个坑”相符。", "月亮": "语义：月亮在天上，小狗不可能把它刨出一个坑。"}, "sentence_index": 6, "correct_answer": "泥土"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在院子里挖出了一棵泥土。", "explanation": "这里应该用〈一块〉或〈一堆〉。“棵”用于植物，不能用来计量泥土。"}, {"text": "他在书架上找到了一本泥土。", "explanation": "这里应该用〈一块〉或〈一堆〉。“本”用于书册，不能用来计量泥土。"}, {"text": "工人在工地上搬走了一间泥土。", "explanation": "这里应该用〈一车〉或〈一堆〉。“间”用于房屋，不能用来计量泥土。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的裤脚上还沾着泥土着。", "corrected_sentence": "他的裤脚上还沾着泥土。", "error_description": "“着”重复：状态标记“着”只说一次，应紧跟动词，应说“沾着泥土”，不能在宾语后再加“着”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们抬来了一台泥土。", "corrected_sentence": "孩子们抬来了一筐泥土。", "error_description": "量词错误：泥土装在筐里应用“筐”计量，“台”用于机器，不能说“一台泥土”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '97137d70-c8c5-4684-b97d-32d1743ca14d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
