INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "偷偷地走进来，不让人发现。", "primary_collocate": null, "pronunciation": "hùn jìn", "ipa": "xuən˥˩ tɕin˥˩", "syllable_count": 2, "sentences": [{"text": "他趁着天黑混进了院子里。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人趁门开着的时候混进屋里，没有人发现。", "target_word": "混进", "complexity_tier": "T3", "furigana": "yǒu rén chèn mén kāi zhe de shí hou hùn jìn wū lǐ, méi yǒu rén fā xiàn.", "sentence_source": "generated"}, {"text": "那个男人没有票，混进了球场。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的人没看见，有个孩子混进来了。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想混进教室看看考试题。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷混进了商店，没有人发现。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她穿着工作服混进了工厂。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们怎么才能混进他们的会议室呢？", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有人混进火车站，没有买票。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们混进老师的办公室，拿了考卷。", "target_word": "混进", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "混进了", "label": "体标"}, {"form": "混进去", "label": "方向补语"}], "register": "中性", "sense_fingerprint": "偷偷走进某处而不被人发现", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c5b8b77-dd74-4ebf-9b21-c87de876915c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "混进", "is_correct": true, "explanation": "正确：“混进”表示偷偷进入、不被发现，与“趁着天黑”相合。"}, {"text": "照进", "is_correct": false, "explanation": "配价：“照进”的主语须是光线，不能说人“照进”院子。"}, {"text": "洒进", "is_correct": false, "explanation": "搭配：“洒”的对象多是液体或细碎之物，不能用来指人进入院子。"}, {"text": "冲进", "is_correct": false, "explanation": "语义：“冲进”指猛然闯入，与“趁着天黑”的偷偷进入相矛盾。"}], "explanations": {"混进": "正确：“混进”表示偷偷进入、不被发现，与“趁着天黑”相合。", "照进": "配价：“照进”的主语须是光线，不能说人“照进”院子。", "洒进": "搭配：“洒”的对象多是液体或细碎之物，不能用来指人进入院子。", "冲进": "语义：“冲进”指猛然闯入，与“趁着天黑”的偷偷进入相矛盾。"}, "sentence_index": 0, "correct_answer": "混进"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他大大方方地混进了教室。", "explanation": "这里应该用〈走进〉。混进表示偷偷进入、不被发现，与“大大方方”矛盾。"}, {"text": "他报了名，正式混进了考试。", "explanation": "这里应该用〈参加〉。报了名的考生是合法入场的，应说“参加”；“混进”指偷偷进入。"}, {"text": "她作为主持人混进了会议，大家都向她问好。", "explanation": "这里应该用〈出席〉。主持人是正式受邀的，应说“出席”；“混进”指偷偷进入、不被察觉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "混进", "is_correct": true, "explanation": "正确：“混进”表示偷偷进入，与“穿着工作服”的伪装情境相合。"}, {"text": "扛进", "is_correct": false, "explanation": "配价：“扛”要带被扛的物品作宾语，“她穿着工作服扛进了工厂”缺少宾语，不成立。"}, {"text": "吐进", "is_correct": false, "explanation": "语义：“吐进”指吐出的东西落入某处，不能用来指人偷偷进入工厂。"}, {"text": "吹进", "is_correct": false, "explanation": "配价：“吹”的施事通常是风，不能用人作主语。"}], "explanations": {"混进": "正确：“混进”表示偷偷进入，与“穿着工作服”的伪装情境相合。", "扛进": "配价：“扛”要带被扛的物品作宾语，“她穿着工作服扛进了工厂”缺少宾语，不成立。", "吐进": "语义：“吐进”指吐出的东西落入某处，不能用来指人偷偷进入工厂。", "吹进": "配价：“吹”的施事通常是风，不能用人作主语。"}, "sentence_index": 6, "correct_answer": "混进"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一路大声唱着歌，混进了办公室。", "explanation": "这里应该用〈走进〉。混进表示偷偷进入，“一路大声唱着歌”是公开进入，应说“走进”。"}, {"text": "老板亲自带路，他混进了会议室。", "explanation": "这里应该用〈进入〉。老板亲自带路是光明正大地进入，“混进”表示偷偷进入，与此矛盾。"}, {"text": "服务员端着托盘，混进了包厢。", "explanation": "这里应该用〈走进〉。服务员端着托盘是正常进入，“混进”表示偷偷进入，与此矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她趁保安不注意，悄悄混进在了仓库。", "corrected_sentence": "她趁保安不注意，悄悄混进了仓库。", "error_description": "位置错误：“混进”与“了”之间不能插入“在”，应说“混进了仓库”，不能说“混进在了仓库”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (22996, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个人穿着制服，悄悄混进着大楼。", "corrected_sentence": "那个人穿着制服，悄悄混进了大楼。", "error_description": "体标错误：“混进”表示已完成的动作，应用“了”，不能用“着”（“着”表示持续的状态）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cc33d32a-f0d9-4918-9f14-69e0d89a6ba6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
