INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土里就是泥土的里面。", "primary_collocate": null, "pronunciation": "tǔ lǐ", "ipa": "tʰu˨˩˦ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "小虫子躲在土里，我们看不见。", "target_word": "土里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民把种子放进土里。", "target_word": "土里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些花的根都长在土里。", "target_word": "土里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗在土里找到了一块骨头。", "target_word": "土里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，土里的水很多。", "target_word": "土里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把一个小盒子埋在土里。", "target_word": "土里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蚯蚓喜欢住在湿湿的土里。", "target_word": "土里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "土里有很多小石头，种花不容易。", "target_word": "土里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，有些小动物睡在土里。", "target_word": "土里", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷从土里挖出了一个大土豆。", "target_word": "土里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "泥土的里面，地下的土壤之中", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7e949e43-2da5-404e-9e85-f72be655bc2c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "土里", "is_correct": true, "explanation": "正确答案。“土里”指泥土的里面。"}, {"text": "图例", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同；lì（第四声）与 lǐ（第三声）声调也不同，意思是地图上的符号说明。"}, {"text": "头里", "is_correct": false, "explanation": "tóu（第二声）与 tǔ（第三声）声调不同，意思是先前、以前。"}, {"text": "土粒", "is_correct": false, "explanation": "lì（第四声）与 lǐ（第三声）声调不同，意思是土的小颗粒。"}], "explanations": {"土里": "正确答案。“土里”指泥土的里面。", "图例": "tú（第二声）与 tǔ（第三声）声调不同；lì（第四声）与 lǐ（第三声）声调也不同，意思是地图上的符号说明。", "头里": "tóu（第二声）与 tǔ（第三声）声调不同，意思是先前、以前。", "土粒": "lì（第四声）与 lǐ（第三声）声调不同，意思是土的小颗粒。"}, "sentence_index": null, "correct_answer": "土里"}, "level_3": {"options": [{"text": "土里", "is_correct": true, "explanation": "符合语境：小虫子藏在泥土之中，所以我们看不见。"}, {"text": "桌子上", "is_correct": false, "explanation": "语义：桌面没有遮挡，小虫子躲在那里不会看不见。"}, {"text": "灯光下", "is_correct": false, "explanation": "语义：灯光下一切都很明亮，小虫子不可能躲在那里而让我们看不见。"}, {"text": "空中", "is_correct": false, "explanation": "搭配：“躲在”后要接能藏身的处所，“空中”不是能藏身的地方。"}], "explanations": {"土里": "符合语境：小虫子藏在泥土之中，所以我们看不见。", "桌子上": "语义：桌面没有遮挡，小虫子躲在那里不会看不见。", "灯光下": "语义：灯光下一切都很明亮，小虫子不可能躲在那里而让我们看不见。", "空中": "搭配：“躲在”后要接能藏身的处所，“空中”不是能藏身的地方。"}, "sentence_index": 0, "correct_answer": "土里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们小区的土里有一个大停车场。", "explanation": "这里应该用〈地下〉。“土里”只指泥土之中，人工建造的停车场要用“地下”。"}, {"text": "我们在土里喝了一杯咖啡。", "explanation": "这里应该用〈咖啡馆〉。“土里”只指泥土之中，喝咖啡要去咖啡馆。"}, {"text": "今天的天气很好，我在土里散步。", "explanation": "这里应该用〈外面〉。“土里”只指泥土之中，在户外到处走动要用“外面”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23002, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "土里", "is_correct": true, "explanation": "符合语境：蚯蚓喜欢生活在湿润的泥土之中。"}, {"text": "天上", "is_correct": false, "explanation": "搭配：“湿湿的”不能修饰“天上”，天空不是蚯蚓的住处。"}, {"text": "书包里", "is_correct": false, "explanation": "语义：书包不是蚯蚓的生活环境，蚯蚓不会住在书包里。"}, {"text": "石头上", "is_correct": false, "explanation": "语义：石头表面没有土壤，蚯蚓不能住在石头上。"}], "explanations": {"土里": "符合语境：蚯蚓喜欢生活在湿润的泥土之中。", "天上": "搭配：“湿湿的”不能修饰“天上”，天空不是蚯蚓的住处。", "书包里": "语义：书包不是蚯蚓的生活环境，蚯蚓不会住在书包里。", "石头上": "语义：石头表面没有土壤，蚯蚓不能住在石头上。"}, "sentence_index": 6, "correct_answer": "土里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书包的土里放着一本字典。", "explanation": "这里应该用〈里面〉。“土里”只指泥土之中，书包里面的东西不能说“土里”。"}, {"text": "他的土里装满了新想法。", "explanation": "这里应该用〈脑子里〉。“土里”只指泥土之中，形容人的想法要用“脑子里”。"}, {"text": "鱼在土里游来游去。", "explanation": "这里应该用〈水里〉。鱼生活在水中，说鱼在游动时不能用“土里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈往土里拔出了一棵萝卜。", "corrected_sentence": "妈妈从土里拔出了一棵萝卜。", "error_description": "错误形式是“往土里拔出”，正确形式是“从土里拔出”。“拔出”表示从里面取出，要用“从”引出处所；“往”表示朝某个方向，与“拔出”的意思矛盾。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这棵大树的根扎土里很深。", "corrected_sentence": "这棵大树的根扎在土里很深。", "error_description": "错误：“扎”后漏掉了介词“在”。“扎”表示进入某处，要用“扎在……里”引出处所，正确说法是“这棵大树的根扎在土里很深”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fdab4312-7e5e-47ce-9bc8-36c7c2d6f927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
