INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23006, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "会长就是管一个团体的人。", "primary_collocate": null, "pronunciation": "huì zhǎng", "ipa": "xueɪ˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们读书会的会长是李老师。", "target_word": "会长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会长今天要给大家讲话。", "target_word": "会长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他去年当上了足球协会的会长。", "target_word": "会长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开会以前，会长先请大家安静。", "target_word": "会长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会长对我说：“欢迎你加入我们的俱乐部。”", "target_word": "会长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位会长很年轻，大家都喜欢他。", "target_word": "会长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁是你们学生会的会长？", "target_word": "会长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "会长一直忙着准备明天的会议。", "target_word": "会长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想问会长，下个月我们去哪儿旅行？", "target_word": "会长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "会长把大家的意见都写在了本子上。", "target_word": "会长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "副会长", "label": "复合"}, {"form": "会長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "团体、协会的最高负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '411da9e4-51a0-498e-b4c5-a2af973994ca') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23006, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "会长", "is_correct": true, "explanation": "会长（huì zhǎng）指团体的负责人，是本题的目标词。"}, {"text": "会场", "is_correct": false, "explanation": "会场（huì chǎng）：zhǎng 与 chǎng 声母不同（zh 与 ch），意思是开会的场所。"}, {"text": "会展", "is_correct": false, "explanation": "会展（huì zhǎn）：zhǎng 与 zhǎn 韵母不同（-ng 与 -n），意思是展览会。"}, {"text": "挥掌", "is_correct": false, "explanation": "挥掌（huī zhǎng）：第一个音节 huì 与 huī 声调不同，意思是挥动手掌。"}], "explanations": {"会长": "会长（huì zhǎng）指团体的负责人，是本题的目标词。", "会场": "会场（huì chǎng）：zhǎng 与 chǎng 声母不同（zh 与 ch），意思是开会的场所。", "会展": "会展（huì zhǎn）：zhǎng 与 zhǎn 韵母不同（-ng 与 -n），意思是展览会。", "挥掌": "挥掌（huī zhǎng）：第一个音节 huì 与 huī 声调不同，意思是挥动手掌。"}, "sentence_index": null, "correct_answer": "会长"}, "level_3": {"options": [{"text": "会议", "is_correct": false, "explanation": "语义：“会议”指聚会，不是人，不能作“是李老师”的身份说明。"}, {"text": "校长", "is_correct": false, "explanation": "搭配：“读书会”的负责人不叫“校长”，“校长”属于学校。"}, {"text": "会长", "is_correct": true, "explanation": "“会长”指团体的负责人，与“读书会”搭配，并且指人，与“是李老师”相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：“学生”是求学的人，与“李老师”的身份矛盾，不能担任读书会的负责人。"}], "explanations": {"会议": "语义：“会议”指聚会，不是人，不能作“是李老师”的身份说明。", "校长": "搭配：“读书会”的负责人不叫“校长”，“校长”属于学校。", "会长": "“会长”指团体的负责人，与“读书会”搭配，并且指人，与“是李老师”相符。", "学生": "语义：“学生”是求学的人，与“李老师”的身份矛盾，不能担任读书会的负责人。"}, "sentence_index": 0, "correct_answer": "会长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们医院的会长很和蔼。", "explanation": "这里应该用〈院长〉。会长用于协会、俱乐部等团体，医院的负责人叫院长。"}, {"text": "我们杂志社的会长很和蔼。", "explanation": "这里应该用〈社长〉。会长多用于协会、俱乐部等团体，杂志社的负责人叫社长。"}, {"text": "我们工厂的会长很和蔼。", "explanation": "这里应该用〈厂长〉。会长用于协会、俱乐部等团体，工厂的负责人叫厂长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "班长", "is_correct": false, "explanation": "搭配：“班长”属于班级，学生会里一般不设班长。"}, {"text": "宿舍", "is_correct": false, "explanation": "语义：“宿舍”是住处，不能担任职务，无法回答“谁是……的会长”。"}, {"text": "会长", "is_correct": true, "explanation": "“会长”指学生会的负责人，正是“谁是……的会长”所问的身份。"}, {"text": "钢琴", "is_correct": false, "explanation": "语义：“钢琴”是乐器，不能担任学生会的职务。"}], "explanations": {"班长": "搭配：“班长”属于班级，学生会里一般不设班长。", "宿舍": "语义：“宿舍”是住处，不能担任职务，无法回答“谁是……的会长”。", "会长": "“会长”指学生会的负责人，正是“谁是……的会长”所问的身份。", "钢琴": "语义：“钢琴”是乐器，不能担任学生会的职务。"}, "sentence_index": 6, "correct_answer": "会长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的会长很和蔼。", "explanation": "这里应该用〈校长〉。会长用于协会等团体，学校的负责人叫校长。"}, {"text": "我们公司的会长很忙。", "explanation": "这里应该用〈董事长〉。会长用于协会等团体，公司的负责人叫董事长。"}, {"text": "我们班的会长很认真。", "explanation": "这里应该用〈班长〉。会长用于协会等团体，班级的负责人叫班长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23006, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们选了一位会长们。", "corrected_sentence": "他们选了一位会长。", "error_description": "错误在“们”：“一位”已表示确定的人数，“会长”后面不能再加“们”。正确说法是“一位会长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23006, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是一条很热心的会长。", "corrected_sentence": "他是一位很热心的会长。", "error_description": "错误在量词：“会长”指人，应用“位”，“条”用于细长的东西。正确说法是“一位很热心的会长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8cfad29-f526-4989-a5f1-bff446e93f77') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
