INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "做某件事。", "primary_collocate": null, "pronunciation": "xíng dòng", "ipa": "ɕiŋ˧˥ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我们明天早上八点行动。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家要马上行动起来。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想成功，就要行动，不能只是想。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说到做到，马上开始行动。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察昨晚在城里行动了。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别再等了，今天就行动吧。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "行动之前，我们先开个会。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让同学们分组行动。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先想好计划，再行动。", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说：“少说话，多行动。”", "target_word": "行动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行动起来", "label": "补语"}, {"form": "行动计划", "label": "复合"}, {"form": "行动力", "label": "复合"}], "register": "中性", "sense_fingerprint": "动手去做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b67ea2c-4f99-4305-8a7b-096353e3f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行动", "is_correct": true, "explanation": "行动：做某件事，此处指明天早上八点开始做事。"}, {"text": "迷路", "is_correct": false, "explanation": "语义：迷路指找不到方向，不是可以按计划安排在某个时间的事。"}, {"text": "完成", "is_correct": false, "explanation": "配价：“完成”要带宾语，如“完成任务”，这里缺宾语，句子不完整。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：失眠指睡不着，不是为明天早上的安排而做的事。"}], "explanations": {"行动": "行动：做某件事，此处指明天早上八点开始做事。", "迷路": "语义：迷路指找不到方向，不是可以按计划安排在某个时间的事。", "完成": "配价：“完成”要带宾语，如“完成任务”，这里缺宾语，句子不完整。", "失眠": "语义：失眠指睡不着，不是为明天早上的安排而做的事。"}, "sentence_index": 0, "correct_answer": "行动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上都去公园做行动。", "explanation": "这里应该用〈运动〉。行动指去做某件事，锻炼身体要用运动。"}, {"text": "比赛行动了两个小时。", "explanation": "这里应该用〈进行〉。行动指人有意做事，比赛持续的过程要用进行。"}, {"text": "这个程序行动得很快。", "explanation": "这里应该用〈运行〉。行动指人有意做事，程序工作要用运行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行动", "is_correct": true, "explanation": "行动：做事，此处指在开会之前要做的事。"}, {"text": "出生", "is_correct": false, "explanation": "语义：出生不是可以安排在“开会”之前的事，与语境不合。"}, {"text": "失业", "is_correct": false, "explanation": "语义：失业是失去工作，不能作为开会之前的安排。"}, {"text": "迟到", "is_correct": false, "explanation": "搭配：“迟到”指没有按时到达，不能用“迟到之前”表示行动前的时间。"}], "explanations": {"行动": "行动：做事，此处指在开会之前要做的事。", "出生": "语义：出生不是可以安排在“开会”之前的事，与语境不合。", "失业": "语义：失业是失去工作，不能作为开会之前的安排。", "迟到": "搭配：“迟到”指没有按时到达，不能用“迟到之前”表示行动前的时间。"}, "sentence_index": 6, "correct_answer": "行动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在电话里行动了很久。", "explanation": "这里应该用〈说〉。行动指有目的地做事，打电话时说话要用说。"}, {"text": "我每天晚上都在家里行动。", "explanation": "这里应该用〈睡觉〉。行动指有目的地做事，夜里在家休息要用睡觉。"}, {"text": "这批货物用火车行动。", "explanation": "这里应该用〈运输〉。货物运送要用运输，行动不能这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家都行动下来了。", "corrected_sentence": "大家都行动起来了。", "error_description": "“行动起来”表示开始行动，补语应用“起来”，不用“下来”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察分头行动的，抓住了小偷。", "corrected_sentence": "警察分头行动，抓住了小偷。", "error_description": "“分头行动”是完整的动作结构，后面不能直接加“的”，应删去“的”，说“警察分头行动，抓住了小偷”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把一个人或东西看成另一种东西。", "primary_collocate": null, "pronunciation": "dàng zuò", "ipa": "tɑŋ˥˩ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "他把我当作最好的朋友。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把这件事当作玩笑。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人把手机当作电脑用。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这次失败当作一次学习的机会。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王把旧桌子当作书架用。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都把她当作家里人。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从不把别人的帮助当作应该的事。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个国家，人们把狗当作家人。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要把我说的话当作命令。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子把纸箱当作小房子玩了一下午。", "target_word": "当作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "当作了", "label": "体标"}, {"form": "当作过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：把A看成B，常用“把A当作B”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca85f957-df35-4d8f-af57-1db695739dd7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "当作", "is_correct": true, "explanation": "正确：“当作”表示把某人看成另一种东西，与“把…当作…”结构相合。"}, {"text": "喜欢", "is_correct": false, "explanation": "搭配：“喜欢”不能同时带“我”和“最好的朋友”两个宾语，“把我喜欢最好的朋友”不成立。"}, {"text": "讨厌", "is_correct": false, "explanation": "配价：“讨厌”是心理动词，不能同时带“我”和“最好的朋友”两个宾语，“把我讨厌最好的朋友”不成立。"}, {"text": "称呼", "is_correct": false, "explanation": "配价：“称呼”后要用“为”引出称谓，“把我称呼最好的朋友”不成立。"}], "explanations": {"当作": "正确：“当作”表示把某人看成另一种东西，与“把…当作…”结构相合。", "喜欢": "搭配：“喜欢”不能同时带“我”和“最好的朋友”两个宾语，“把我喜欢最好的朋友”不成立。", "讨厌": "配价：“讨厌”是心理动词，不能同时带“我”和“最好的朋友”两个宾语，“把我讨厌最好的朋友”不成立。", "称呼": "配价：“称呼”后要用“为”引出称谓，“把我称呼最好的朋友”不成立。"}, "sentence_index": 0, "correct_answer": "当作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈当作我已经吃过了，就没做饭。", "explanation": "这里应该用〈以为〉。“当作”后接的是被看成的具体事物，不能接“我已经吃过了”这样的小句；表示误认时要用“以为”。"}, {"text": "他把我当作很高兴，所以什么也没说。", "explanation": "这里应该用〈觉得〉。“当作”的宾语应是名词性的对象，不能接“很高兴”这样的形容词短语；表达感受时要用“觉得”。"}, {"text": "他把这份计划当作了三年，才终于完成。", "explanation": "这里应该用〈花〉。“当作”要把对象看成另一种事物，表示耗费时间时应说“花了三年”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拿", "is_correct": false, "explanation": "搭配：“拿”不能用来表示把帮助看作某种事情，“拿应该的事”不成立。"}, {"text": "回答", "is_correct": false, "explanation": "语义：“回答”指应对问题，与“别人的帮助”和“应该的事”的关系无关。"}, {"text": "当作", "is_correct": true, "explanation": "正确：“当作”表示把别人的帮助看成应该的事，与“从不”的否定相合。"}, {"text": "感到", "is_correct": false, "explanation": "配价：“感到”后不能直接接“把…”宾语和“应该的事”这样的名词短语，句子不成立。"}], "explanations": {"拿": "搭配：“拿”不能用来表示把帮助看作某种事情，“拿应该的事”不成立。", "回答": "语义：“回答”指应对问题，与“别人的帮助”和“应该的事”的关系无关。", "当作": "正确：“当作”表示把别人的帮助看成应该的事，与“从不”的否定相合。", "感到": "配价：“感到”后不能直接接“把…”宾语和“应该的事”这样的名词短语，句子不成立。"}, "sentence_index": 6, "correct_answer": "当作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我当作这次比赛会很难，所以提前准备。", "explanation": "这里应该用〈认为〉。“当作”后接的是具体对象，表示把它看成另一种事物；对“比赛会很难”这样的判断，要用“认为”。"}, {"text": "他把这次考试当作已经通过了，一点也不紧张。", "explanation": "这里应该用〈以为〉。“当作”后接的是被看成的事物，不能接“已经通过了”这样的小句；表示误认时要用“以为”。"}, {"text": "他把这篇文章当作读完了，就去睡觉了。", "explanation": "这里“当作”后接的是动作，不是被看成的事物；应去掉“当作”，说“他读完了这篇文章，就去睡觉了。”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把我很当作亲人。", "corrected_sentence": "他把我当作亲人。", "error_description": "错误：“把”字结构中，“很”不能插在宾语“我”和动词“当作”之间，句中多加了“很”。应说“他把我当作亲人。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23010, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们都把她当作着自己人。", "corrected_sentence": "我们都把她当作自己人。", "error_description": "错误：“当作”后不能直接加“着”，应说“我们都把她当作自己人。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c290b81d-0dcb-45a5-b379-91fe24a99a2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23012, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '39c147ad-02dc-40a2-9f0d-2cea2ca5d7c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
