INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23020, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能承载、传递人、物或信息的事物。", "primary_collocate": null, "pronunciation": "zài tǐ", "ipa": "tsai⁵¹ tʰi²¹⁴", "syllable_count": 2, "sentences": [{"text": "书是知识的载体。", "target_word": "载体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "语言是文化传承的载体。", "target_word": "载体", "complexity_tier": "T3", "furigana": "yǔ yán shì wén huà chuán chéng de zài tǐ", "sentence_source": "generated"}, {"text": "基因是遗传信息的载体。", "target_word": "载体", "complexity_tier": "T3", "furigana": "jī yīn shì yí chuán xìn xī de zài tǐ", "sentence_source": "generated"}, {"text": "手机是信息的载体。", "target_word": "载体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "文字是文化的载体。", "target_word": "载体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "光盘是音乐的载体。", "target_word": "载体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "声音也是信息的载体。", "target_word": "载体", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "纸是文字最早的载体之一。", "target_word": "载体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "网络成了传播新闻的新载体。", "target_word": "载体", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "照片是记忆的载体。", "target_word": "载体", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "用来承载人、物或信息的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e0e621cd-3813-46e8-abfa-9d13f45d7637') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23020, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "载体", "is_correct": true, "explanation": "载体：能承载知识、信息的东西，与“知识的……”搭配自然。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是视觉属性，不能作为知识的承载物。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”指大气状况，与知识无关，不能作为承载物。"}, {"text": "手套", "is_correct": false, "explanation": "搭配：“手套”是穿戴用品，不会说“知识的手套”。"}], "explanations": {"载体": "载体：能承载知识、信息的东西，与“知识的……”搭配自然。", "颜色": "语义：“颜色”是视觉属性，不能作为知识的承载物。", "天气": "语义：“天气”指大气状况，与知识无关，不能作为承载物。", "手套": "搭配：“手套”是穿戴用品，不会说“知识的手套”。"}, "sentence_index": 0, "correct_answer": "载体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里有一只很好的载体。", "explanation": "这里应该用〈种〉或〈个〉。“只”多用于动物、船只等，不用于抽象的载体。"}, {"text": "这把锤子是钉钉子的载体。", "explanation": "这里应该用〈工具〉。载体指承载人、物或信息的东西，锤子是工具，并不承载什么。"}, {"text": "这块木头是制作家具的载体。", "explanation": "这里应该用〈原料〉。木头作为原料被加工，并不承载人、物或信息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23020, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "载体", "is_correct": true, "explanation": "载体：能承载信息的东西，与“信息的……”搭配自然。"}, {"text": "布料", "is_correct": false, "explanation": "语义：“布料”是纺织材料，不能承载信息。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：“树叶”是植物的器官，与信息无关，不能作承载物。"}, {"text": "筷子", "is_correct": false, "explanation": "搭配：“筷子”用来夹取食物，不能说“信息的筷子”。"}], "explanations": {"载体": "载体：能承载信息的东西，与“信息的……”搭配自然。", "布料": "语义：“布料”是纺织材料，不能承载信息。", "树叶": "语义：“树叶”是植物的器官，与信息无关，不能作承载物。", "筷子": "搭配：“筷子”用来夹取食物，不能说“信息的筷子”。"}, "sentence_index": 6, "correct_answer": "载体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试是我的载体。", "explanation": "这里应该用〈考验〉。载体指承载人、物或信息的实体，考试不承载东西，不能用“载体”来指它。"}, {"text": "这块石头是房子的载体。", "explanation": "这里应该用〈地基〉。石头作为地基起支撑作用，并不承载信息或物品。"}, {"text": "这些油漆是墙壁的载体。", "explanation": "这里应该用〈涂层〉。油漆形成覆盖层，不能说成墙壁的载体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这套教材是学习的一只好载体。", "corrected_sentence": "这套教材是学习的一种好载体。", "error_description": "错误形式：“一只好载体”。正确形式：“一种好载体”。“载体”是抽象的承载物，不用量词“只”，应用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座博物馆是历史的重要载体们。", "corrected_sentence": "这座博物馆是历史的重要载体。", "error_description": "错误形式：“载体们”。正确形式：“载体”。“载体”指物或信息的承载者，不是人，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '17b07f93-993b-4a70-ab75-5a37f3853925') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
