INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23022, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让看不见的东西变得能看见。", "primary_collocate": null, "pronunciation": "jù xiàng huà", "ipa": "tɕy˥˩ ɕjɑŋ˥˩ xwa˥˩", "syllable_count": 3, "sentences": [{"text": "这张图把看不见的空气污染具象化了。", "target_word": "具象化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "数据图表让看不见的变化具象化。", "target_word": "具象化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "实验中，烟把风的方向具象化了。", "target_word": "具象化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热成像仪能把温度具象化，用不同颜色表示。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用片子把身体里的问题具象化，病人一看就懂。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天呼出的白气，把冷空气具象化了。", "target_word": "具象化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "阳光照进房间，灰尘把光的路线具象化了。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画用线条把音乐的节奏具象化了。", "target_word": "具象化", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "化学老师往水里加了颜料，让水流具象化。", "target_word": "具象化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "声波图把看不见的声音具象化。", "target_word": "具象化", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "具象化了", "label": "体标"}, {"form": "具象化过", "label": "体标"}], "register": "书面", "sense_fingerprint": "借助图像、颜色等手段让看不见的事物变得看得见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa07a53c-a9cf-4bf8-a96d-3c0a8dd8e503') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23022, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "具象化", "is_correct": true, "explanation": "正确。“把看不见的空气污染具象化了”即让看不见的污染变得看得见。"}, {"text": "清除", "is_correct": false, "explanation": "语义：图片只能显示污染，不能把污染“清除”掉。"}, {"text": "搞定", "is_correct": false, "explanation": "语域：“搞定”是口语词，与本句的书面语体不符，且图片无法“搞定”污染。"}, {"text": "推迟", "is_correct": false, "explanation": "搭配：“推迟”的对象是时间或事项，不能说“推迟空气污染”。"}], "explanations": {"具象化": "正确。“把看不见的空气污染具象化了”即让看不见的污染变得看得见。", "清除": "语义：图片只能显示污染，不能把污染“清除”掉。", "搞定": "语域：“搞定”是口语词，与本句的书面语体不符，且图片无法“搞定”污染。", "推迟": "搭配：“推迟”的对象是时间或事项，不能说“推迟空气污染”。"}, "sentence_index": 0, "correct_answer": "具象化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布把桌子下面的东西具象化了。", "explanation": "这里应该用〈隐藏〉。“具象化”是让看不见的东西看得见，而句意是遮住东西，方向相反。"}, {"text": "这场雨把空气里的灰尘具象化了。", "explanation": "这里应该用〈清除〉。“具象化”是让看不见的东西看得见，雨是把灰尘洗掉，方向相反。"}, {"text": "厚雾把远处的山具象化了。", "explanation": "这里应该用〈模糊〉。“具象化”是让东西变得清楚可见，雾使山变得看不清，方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23022, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "具象化", "is_correct": true, "explanation": "正确。“灰尘把光的路线具象化了”即让看不见的光路变得可见，与句意一致。"}, {"text": "吃掉", "is_correct": false, "explanation": "搭配：“吃掉”的对象多为食物，不能说“吃掉光的路线”。"}, {"text": "抛弃", "is_correct": false, "explanation": "搭配：“抛弃”只用于人或物的主动放弃，光路不能被抛弃。"}, {"text": "煮熟", "is_correct": false, "explanation": "语义：“煮熟”指加热使食物成熟，与灰尘让光路变得可见的意思无关。"}], "explanations": {"具象化": "正确。“灰尘把光的路线具象化了”即让看不见的光路变得可见，与句意一致。", "吃掉": "搭配：“吃掉”的对象多为食物，不能说“吃掉光的路线”。", "抛弃": "搭配：“抛弃”只用于人或物的主动放弃，光路不能被抛弃。", "煮熟": "语义：“煮熟”指加热使食物成熟，与灰尘让光路变得可见的意思无关。"}, "sentence_index": 6, "correct_answer": "具象化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人把看得见的钢筋具象化了。", "explanation": "这里应该用〈展示〉。“具象化”是让看不见的东西变得能看见，钢筋本来就看得见，不需要“具象化”，要说“展示”。"}, {"text": "工人把看得见的桌子具象化了。", "explanation": "这里应该用〈摆放〉。“具象化”是让看不见的东西变得能看见，桌子本来就看得见，要说“摆放”。"}, {"text": "工人把看得见的玻璃具象化了。", "explanation": "这里应该用〈擦拭〉。“具象化”是让看不见的东西变得能看见，玻璃本来就看得见，这里说的是清洁，要说“擦拭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张图把看不见的风具象化了很清楚。", "corrected_sentence": "这张图把看不见的风具象化得很清楚。", "error_description": "错误形式：“具象化了很清楚”；正确形式：“具象化得很清楚”。这里需要程度补语“得”，不能用“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盏台灯把看不见的光束具象化了了。", "corrected_sentence": "这盏台灯把看不见的光束具象化了。", "error_description": "错误形式：“具象化了了”；正确形式：“具象化了”。“了”只需出现一次，放在动词之后；重复的“了”是多余的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '82aee9de-6980-411a-b172-e5954f23fa9f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
