INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让垃圾变少。", "primary_collocate": null, "pronunciation": "jiǎn fèi", "ipa": "tɕjɛn²¹⁴ fei⁵¹", "syllable_count": 2, "sentences": [{"text": "想减废，就要少买不用的东西。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每天带饭盒上班，为了减废。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班想一起减废。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减废不难，先从垃圾分类开始。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥开始减废以后，家里的垃圾少了很多。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用布袋买菜是简单的减废方法。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了减废，我们不用一次性筷子。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教大家怎么减废。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷一直在减废，旧东西都舍不得扔。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个月我们家减废成功了。", "target_word": "减废", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减废了", "label": "体标"}, {"form": "减废过", "label": "体标"}], "register": "中性", "sense_fingerprint": "让垃圾变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23024, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减废", "is_correct": true, "explanation": "正确。“想减废，就要少买不用的东西”中的“减废”指减少垃圾，前后语义呼应。"}, {"text": "排队", "is_correct": false, "explanation": "语义：“排队”指按次序等候，与少买不用的东西减少垃圾无关，句意不通。"}, {"text": "发胖", "is_correct": false, "explanation": "体貌：“发胖”指人的体型变化，不能与“少买东西”形成目的关系。"}, {"text": "认识", "is_correct": false, "explanation": "配价：“认识”需要带认识的对象，句中没有宾语，也与少买东西的语境无关。"}], "explanations": {"减废": "正确。“想减废，就要少买不用的东西”中的“减废”指减少垃圾，前后语义呼应。", "排队": "语义：“排队”指按次序等候，与少买不用的东西减少垃圾无关，句意不通。", "发胖": "体貌：“发胖”指人的体型变化，不能与“少买东西”形成目的关系。", "认识": "配价：“认识”需要带认识的对象，句中没有宾语，也与少买东西的语境无关。"}, "sentence_index": 0, "correct_answer": "减废"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想减废，每天都去跑步。", "explanation": "这里应该用〈减肥〉。减废指减少垃圾，不能表示减轻体重，想减轻体重要说减肥。"}, {"text": "汽车过路口时要减废速度。", "explanation": "这里应该用〈减速〉。减废指减少垃圾，不能用来表示放慢车速。"}, {"text": "这个书架要自己减废。", "explanation": "这里应该用〈组装〉。减废指减少垃圾，不能表示把零件拼装成书架。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23024, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减废", "is_correct": true, "explanation": "正确。“为了减废，我们不用一次性筷子”中，“减废”是目的，与不用一次性用品相符。"}, {"text": "加班", "is_correct": false, "explanation": "语义：“加班”指延长工作时间，与不用一次性筷子这一行为没有目的关系。"}, {"text": "发愁", "is_correct": false, "explanation": "搭配：“为了”后接的应是有目的的行为，“发愁”是心理状态，不能作为目的。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”指睡不着觉，与不用一次性筷子的行为无关，句意不通。"}], "explanations": {"减废": "正确。“为了减废，我们不用一次性筷子”中，“减废”是目的，与不用一次性用品相符。", "加班": "语义：“加班”指延长工作时间，与不用一次性筷子这一行为没有目的关系。", "发愁": "搭配：“为了”后接的应是有目的的行为，“发愁”是心理状态，不能作为目的。", "失眠": "语义：“失眠”指睡不着觉，与不用一次性筷子的行为无关，句意不通。"}, "sentence_index": 6, "correct_answer": "减废"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人正在减废墙壁。", "explanation": "这里应该用〈粉刷〉。减废指减少垃圾，不能表示给墙壁涂颜色。"}, {"text": "妈妈减废卫生很仔细。", "explanation": "这里应该用〈打扫〉。减废是针对垃圾的动作，不能用来表示清扫屋子的行为。"}, {"text": "爸爸减废漏水的水管。", "explanation": "这里应该用〈修补〉。减废不能用来表示修理有问题的器物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们家减废的很快。", "corrected_sentence": "他们家减废得很快。", "error_description": "助词错误：表示程度补语要用“得”，“的”用于定语，不能接在动词后作补语。应改为“他们家减废得很快。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班从来不减废过。", "corrected_sentence": "我们班从来没减废过。", "error_description": "否定词错误：表示从未经历过某事要用“没”，“不”用于习惯或意愿，不能与表示经历的“过”搭配。应改为“我们班从来没减废过。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
