INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个东西和另一个东西连在一起的地方。", "primary_collocate": null, "pronunciation": "jié diǎn", "ipa": "tɕjɛ˧˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张网上有很多节点，每个节点都连着线。", "target_word": "节点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网络里的每个节点都能收发信息。", "target_word": "节点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个交通节点每天有很多人换车。", "target_word": "节点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个物流网络设有许多节点，货物在节点之间转运。", "target_word": "节点", "complexity_tier": "T3", "furigana": "zhè ge wù liú wǎng luò shè yǒu xǔ duō jié diǎn, huò wù zài jié diǎn zhī jiān zhuǎn yùn.", "sentence_source": "generated"}, {"text": "这座城市是南北铁路的重要节点。", "target_word": "节点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个节点坏了，信息就传不出去。", "target_word": "节点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在关键节点上增加了一台机器。", "target_word": "节点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师在图上用红点标出每个节点，再用线把它们连起来。", "target_word": "节点", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个供电网络有很多节点，每个节点都要定期检修。", "target_word": "节点", "complexity_tier": "T3", "furigana": "zhè ge gōng diàn wǎng luò yǒu hěn duō jié diǎn, měi ge jié diǎn dōu yào dìng qī jiǎn xiū.", "sentence_source": "generated"}, {"text": "机场是城市交通网的一个节点。", "target_word": "节点", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个节点", "label": "量词"}, {"form": "网络节点", "label": "复合"}, {"form": "关键节点", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，网络、线路、管道等中几条线连接或交汇的点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "心情", "is_correct": false, "explanation": "语义：心情不是可以放在网上的东西，与“网”的语境不符。"}, {"text": "节点", "is_correct": true, "explanation": "节点：网络、线路中几条线连接或交汇的点。这里指网上的连接点，正确。"}, {"text": "空气", "is_correct": false, "explanation": "语义：句中“每个……都连着线”说的是网上的连接点，空气不是可以连线的东西，与“网”的语境不符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：句中“每个……都连着线”说的是线路中的连接点，歌曲不是连接点，句意不通。"}], "explanations": {"心情": "语义：心情不是可以放在网上的东西，与“网”的语境不符。", "节点": "节点：网络、线路中几条线连接或交汇的点。这里指网上的连接点，正确。", "空气": "语义：句中“每个……都连着线”说的是网上的连接点，空气不是可以连线的东西，与“网”的语境不符。", "歌曲": "语义：句中“每个……都连着线”说的是线路中的连接点，歌曲不是连接点，句意不通。"}, "sentence_index": 0, "correct_answer": "节点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首诗有三个节点，每段都押韵。", "explanation": "这里应该用〈段落〉。“节点”指网络、线路中相连的点，不指诗的段落。"}, {"text": "这座公园里有很多节点，游客可以拍照留念。", "explanation": "这里应该用〈景点〉。供游客参观的地方要说景点，「节点」不指景区。"}, {"text": "这句话的节点用得不对，应该用逗号。", "explanation": "这里应该用〈标点〉。句中的逗号、句号要说标点，「节点」指相连的地方，不能用来指标点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脸色", "is_correct": false, "explanation": "语义：脸色不是可以增加机器的地方，与句意不符。"}, {"text": "节点", "is_correct": true, "explanation": "节点：网络中几条线连接或交汇的点。机器增加在关键节点上，正确。"}, {"text": "乐章", "is_correct": false, "explanation": "语义：乐章是音乐的段落，不能在其上增加机器。"}, {"text": "呼吸", "is_correct": false, "explanation": "搭配：「呼吸」是动作，不能作为“在……上增加机器”的处所。"}], "explanations": {"脸色": "语义：脸色不是可以增加机器的地方，与句意不符。", "节点": "节点：网络中几条线连接或交汇的点。机器增加在关键节点上，正确。", "乐章": "语义：乐章是音乐的段落，不能在其上增加机器。", "呼吸": "搭配：「呼吸」是动作，不能作为“在……上增加机器”的处所。"}, "sentence_index": 6, "correct_answer": "节点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他爬山后膝盖很痛，节点还有点肿。", "explanation": "这里应该用〈关节〉。身体的关节不能说节点，「节点」指网络中相连的点。"}, {"text": "孩子额头上起了一个节点，我们带他去看医生。", "explanation": "这里应该用〈疙瘩〉。皮肤上凸起的小包要说疙瘩，不能说节点。"}, {"text": "这首歌的节点很快，大家跟着跳舞。", "explanation": "这里应该用〈节拍〉。音乐的节奏要说节拍，「节点」指连接的点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个计算机网络里有一条关键节点，负责转发数据。", "corrected_sentence": "这个计算机网络里有一个关键节点，负责转发数据。", "error_description": "量词错误：「节点」应用「个」，「条」用于线状的东西，不能用于节点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台服务器是网络中的一把关键节点。", "corrected_sentence": "这台服务器是网络中的一个关键节点。", "error_description": "量词错误：「节点」应用「个」，「把」用于有柄可握的东西，不能用于节点。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
