INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "脚踩过留下的印子。", "primary_collocate": null, "pronunciation": "zú jì", "ipa": "tsu˧˥ tɕi˥˩", "syllable_count": 2, "sentences": [{"text": "雪地上留下了一行小小的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海水把沙滩上的足迹冲走了。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，地上有一串动物的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们沿着足迹找到了走丢的小羊。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨后，泥路上全是人的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位旅行家在沙滩上留下了一串足迹。", "target_word": "足迹", "complexity_tier": "T3", "furigana": "zú jì", "sentence_source": "generated"}, {"text": "月球上还留着宇航员的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在院子里踩出了许多小足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察在窗下发现了陌生人的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雪停了，我们回头看自己的足迹。", "target_word": "足迹", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一行足迹", "label": "量词"}, {"form": "一串足迹", "label": "量词"}], "register": "中性", "sense_fingerprint": "脚踩过地面后留下的印子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20be542-fd2b-4af9-92a3-e1943594c231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "足迹", "is_correct": true, "explanation": "足迹：脚踩过地面后留下的印子。这是正确答案。"}, {"text": "阻击", "is_correct": false, "explanation": "zǔjī（第三、第一声）与 zújì（第二、第四声）声调不同，意思是阻挡打击。"}, {"text": "祖籍", "is_correct": false, "explanation": "zǔjí（第三、第二声）与 zújì（第二、第四声）声调不同，意思是祖先的籍贯。"}, {"text": "族籍", "is_correct": false, "explanation": "zújí（第二声）与 zújì（第四声）第二个音节声调不同，意思是民族的籍属，不常用。"}], "explanations": {"足迹": "足迹：脚踩过地面后留下的印子。这是正确答案。", "阻击": "zǔjī（第三、第一声）与 zújì（第二、第四声）声调不同，意思是阻挡打击。", "祖籍": "zǔjí（第三、第二声）与 zújì（第二、第四声）声调不同，意思是祖先的籍贯。", "族籍": "zújí（第二声）与 zújì（第四声）第二个音节声调不同，意思是民族的籍属，不常用。"}, "sentence_index": null, "correct_answer": "足迹"}, "level_3": {"options": [{"text": "足迹", "is_correct": true, "explanation": "正确：足迹指脚踩过留下的印子，符合“雪地上留下了一行小小的”。"}, {"text": "指纹", "is_correct": false, "explanation": "语义：指纹是手指按过留下的印记，雪地上的印子不可能是手指留下的。"}, {"text": "泪痕", "is_correct": false, "explanation": "语义：泪痕是眼泪流过脸颊留下的痕迹，不会留在雪地上。"}, {"text": "印章", "is_correct": false, "explanation": "语义：印章是盖章用的工具，不会在雪地上留下一行印子。"}], "explanations": {"足迹": "正确：足迹指脚踩过留下的印子，符合“雪地上留下了一行小小的”。", "指纹": "语义：指纹是手指按过留下的印记，雪地上的印子不可能是手指留下的。", "泪痕": "语义：泪痕是眼泪流过脸颊留下的痕迹，不会留在雪地上。", "印章": "语义：印章是盖章用的工具，不会在雪地上留下一行印子。"}, "sentence_index": 0, "correct_answer": "足迹"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌上留着一圈咖啡的足迹。", "explanation": "这里应该用〈痕迹〉。足迹专指脚踩过留下的印子，咖啡渍只能说痕迹。"}, {"text": "这双鞋的足迹是四十码。", "explanation": "这里表示鞋的尺寸，应该用〈尺码〉。足迹指脚踩过留下的印子，不指鞋的大小。"}, {"text": "他听见身后传来急促的足迹。", "explanation": "这里应该用〈脚步〉。足迹是看得见的印子，听见的声音要说脚步。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足迹", "is_correct": true, "explanation": "正确：足迹指脚踩过留下的印子，符合“月球上还留着宇航员的”。"}, {"text": "呼吸", "is_correct": false, "explanation": "语义：呼吸是人的生理活动，不会留在月球上。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是人体的温度，会随时间散失，不能像印子一样留在月球上。"}, {"text": "尾气", "is_correct": false, "explanation": "搭配：尾气是交通工具排出的废气，不能说宇航员的尾气留在月球上。"}], "explanations": {"足迹": "正确：足迹指脚踩过留下的印子，符合“月球上还留着宇航员的”。", "呼吸": "语义：呼吸是人的生理活动，不会留在月球上。", "体温": "语义：体温是人体的温度，会随时间散失，不能像印子一样留在月球上。", "尾气": "搭配：尾气是交通工具排出的废气，不能说宇航员的尾气留在月球上。"}, "sentence_index": 6, "correct_answer": "足迹"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的足迹很香。", "explanation": "这里表示气味，应该用〈香气〉。足迹是脚踩留下的印子，没有气味，不能用来形容香味。"}, {"text": "这片雪地的足迹很甜。", "explanation": "这里误用了〈味道〉的意思。足迹是脚踩留下的印子，没有味道，甜只能用来形容食物。"}, {"text": "这辆车在雪地上留下了一串足迹。", "explanation": "足迹指人或动物脚踩出的印子，车轮压出的痕迹应该用〈车辙〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小狗在雪地上留下了一根足迹。", "corrected_sentence": "小狗在雪地上留下了一串足迹。", "error_description": "错误：量词“一根”。“根”用于细长条状的东西，不能用于足迹。正确：“一串足迹”，足迹应用〈串〉或〈行〉计量。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23034, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雪化以后，院子里还留着许多足迹们。", "corrected_sentence": "雪化以后，院子里还留着许多足迹。", "error_description": "错误：“足迹们”，在足迹后面加了“们”。“们”只用于指人的名词，足迹不能加“们”。正确：“许多足迹”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
