INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "把没用的东西扔掉或变成有用的东西。", "primary_collocate": null, "pronunciation": "lā jī chǔ lǐ", "ipa": "la˥ tɕi˥ ʈʂʰu˨˩˦ li˨˩˦", "syllable_count": 4, "sentences": [{"text": "我家每天都要做垃圾处理。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理的第一步是分类。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校教我们怎样做垃圾处理。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理做得好，城市就干净。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公司负责垃圾处理的工作。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些旧东西经过垃圾处理，会变成有用的东西。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的垃圾处理让河水不再变脏。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们小区的垃圾处理很方便。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾处理不好，夏天会有难闻的味道。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在课上学习垃圾处理的办法。", "target_word": "垃圾处理", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "垃圾处理厂", "label": "复合"}, {"form": "垃圾处理站", "label": "复合"}, {"form": "垃圾處理", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把没用的东西扔掉或变成有用东西的做法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "垃圾处理", "is_correct": true, "explanation": "正确：作“做”的宾语，指家庭把没用的东西扔掉或变废为宝的日常做法。"}, {"text": "手术", "is_correct": false, "explanation": "语义：家庭日常不做手术，“我家每天都要做手术”不成立。"}, {"text": "体检", "is_correct": false, "explanation": "语义：体检不是每天都要做的家务，与“每天都要”的语境冲突。"}, {"text": "演讲", "is_correct": false, "explanation": "语义：家庭每天不会做演讲，“每天都要做演讲”与家庭日常的语境冲突。"}], "explanations": {"垃圾处理": "正确：作“做”的宾语，指家庭把没用的东西扔掉或变废为宝的日常做法。", "手术": "语义：家庭日常不做手术，“我家每天都要做手术”不成立。", "体检": "语义：体检不是每天都要做的家务，与“每天都要”的语境冲突。", "演讲": "语义：家庭每天不会做演讲，“每天都要做演讲”与家庭日常的语境冲突。"}, "sentence_index": 0, "correct_answer": "垃圾处理"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们家今天做了三只垃圾处理。", "explanation": "这里应该用〈次〉。垃圾处理指一次次的处理动作，计量用“次”；“只”用于动物或成对的器物，不能用于此。"}, {"text": "他今天只做了一张垃圾处理。", "explanation": "这里应该用〈次〉。“张”用于纸、桌子等平面的东西，不用于计数动作。"}, {"text": "这些旧罐头我放进了垃圾处理里。", "explanation": "这里是把过程误当成容器。垃圾处理指处理的过程，不是盛放废物的地方；放东西应说〈垃圾桶〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "垃圾处理", "is_correct": true, "explanation": "正确：作主语，指把废弃物扔掉或变废为宝的做法，能让河水变干净。"}, {"text": "老师", "is_correct": false, "explanation": "语义：“老师”不是能让河水变干净的做法，“好的老师让河水不再变脏”句意不通。"}, {"text": "发型", "is_correct": false, "explanation": "语义：“发型”与河水无关，无法使河水变干净。"}, {"text": "鞋子", "is_correct": false, "explanation": "搭配：“让……不再变脏”的主语应是处理、措施一类的行为，“鞋子”不能与之搭配。"}], "explanations": {"垃圾处理": "正确：作主语，指把废弃物扔掉或变废为宝的做法，能让河水变干净。", "老师": "语义：“老师”不是能让河水变干净的做法，“好的老师让河水不再变脏”句意不通。", "发型": "语义：“发型”与河水无关，无法使河水变干净。", "鞋子": "搭配：“让……不再变脏”的主语应是处理、措施一类的行为，“鞋子”不能与之搭配。"}, "sentence_index": 6, "correct_answer": "垃圾处理"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都做一块垃圾处理。", "explanation": "这里应该用〈次〉。“块”用于成块的东西，不计数动作，垃圾处理是动作。"}, {"text": "他们班去年做了两把垃圾处理。", "explanation": "这里应该用〈次〉。“把”用于带柄的器具，不用于计数动作。"}, {"text": "我弟弟是我们家的垃圾处理。", "explanation": "这里是把过程误当成人。垃圾处理指处理的过程，不指做这件事的人；指人应说〈垃圾处理员〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每天都很做垃圾处理，把瓶子和纸分开。", "corrected_sentence": "我们每天都做垃圾处理，把瓶子和纸分开。", "error_description": "“很”是程度副词，不能直接修饰动词“做”；应去掉“很”，写作“每天都做垃圾处理”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23038, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈常常垃圾处理，把旧瓶子变成花盆。", "corrected_sentence": "妈妈常常做垃圾处理，把旧瓶子变成花盆。", "error_description": "“垃圾处理”是名词，作宾语时需要动词“做”引出动作，句中缺少动词。错误形式：妈妈常常垃圾处理；正确形式：妈妈常常做垃圾处理。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "暴露", "is_correct": true, "explanation": "反义：“潜藏着”指东西躲在某处别人看不见，“暴露”指藏着的东西被人看见，二者相对。"}, {"text": "修理", "is_correct": false, "explanation": "无反义关系：“修理”指把坏了的东西修好，与藏与显无关。"}, {"text": "搬运", "is_correct": false, "explanation": "无反义关系：“搬运”指把物品从一处运到另一处，不涉及是否被看见。"}, {"text": "讨论", "is_correct": false, "explanation": "无反义关系：“讨论”指多人交流意见，与隐藏、显现无关。"}], "correct_answer": "暴露", "explanations": {"暴露": "反义：“潜藏着”指东西躲在某处别人看不见，“暴露”指藏着的东西被人看见，二者相对。", "修理": "无反义关系：“修理”指把坏了的东西修好，与藏与显无关。", "搬运": "无反义关系：“搬运”指把物品从一处运到另一处，不涉及是否被看见。", "讨论": "无反义关系：“讨论”指多人交流意见，与隐藏、显现无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "显露", "is_correct": true, "explanation": "反义：“潜藏着”指东西躲在某处别人看不见，“显露”指表现出来让人看见，二者相对。"}, {"text": "翻译", "is_correct": false, "explanation": "无反义关系：“翻译”指把一种语言转成另一种语言，与藏与显无关。"}, {"text": "旅行", "is_correct": false, "explanation": "无反义关系：“旅行”指到外地游览，与是否被看见无关。"}, {"text": "播种", "is_correct": false, "explanation": "无反义关系：“播种”指把种子撒进土里，与藏与显无关。"}], "correct_answer": "显露", "explanations": {"显露": "反义：“潜藏着”指东西躲在某处别人看不见，“显露”指表现出来让人看见，二者相对。", "翻译": "无反义关系：“翻译”指把一种语言转成另一种语言，与藏与显无关。", "旅行": "无反义关系：“旅行”指到外地游览，与是否被看见无关。", "播种": "无反义关系：“播种”指把种子撒进土里，与藏与显无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西躲在一个地方，别人看不见它。", "primary_collocate": null, "pronunciation": "qián cáng zhe", "ipa": "tɕʰjɛn˧˥ tsʰɑŋ˧˥ ʈʂɤ", "syllable_count": 3, "sentences": [{"text": "洞里潜藏着一只小老鼠。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草丛里潜藏着几条蛇，我们要小心。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子后面潜藏着一只小猫，没人看见它。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水底潜藏着一块大石头，船过不去。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑暗中潜藏着一个人，我们都没发现。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子下面潜藏着许多小螃蟹。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶后面潜藏着一只鸟，孩子们找不到它。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里潜藏着一只受伤的狐狸，外面的人不知道。", "target_word": "潜藏着", "complexity_tier": "T3", "furigana": "qiáncángzhe", "sentence_source": "generated"}, {"text": "床底下潜藏着一个旧盒子，我找了很久。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟潜藏着，等猎人走远了才飞出来。", "target_word": "潜藏着", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "潜藏", "label": "体标"}, {"form": "潜藏了", "label": "体标"}, {"form": "潜藏过", "label": "体标"}, {"form": "潛藏著", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人或东西躲在某处，别人看不见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "潜藏着", "is_correct": true, "explanation": "正确。“潜藏着”表示老鼠躲在洞里、别人看不见，与句意相合。"}, {"text": "陈列着", "is_correct": false, "explanation": "语义：“陈列”是摆出来给人看，与“别人看不见”相矛盾。"}, {"text": "挂着", "is_correct": false, "explanation": "搭配：“挂着”多接物件，不说洞里挂着一只老鼠。"}, {"text": "堆着", "is_correct": false, "explanation": "搭配：“堆着”指许多实物堆在一起，不用于单只老鼠。"}], "explanations": {"潜藏着": "正确。“潜藏着”表示老鼠躲在洞里、别人看不见，与句意相合。", "陈列着": "语义：“陈列”是摆出来给人看，与“别人看不见”相矛盾。", "挂着": "搭配：“挂着”多接物件，不说洞里挂着一只老鼠。", "堆着": "搭配：“堆着”指许多实物堆在一起，不用于单只老鼠。"}, "sentence_index": 0, "correct_answer": "潜藏着"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上潜藏着一瓶花，客人一进门就看见了。", "explanation": "这里应该用〈摆着〉。潜藏着指东西躲着、别人看不见，而花瓶摆在桌上是醒目可见的，应说“桌子上摆着一瓶花”。"}, {"text": "湖面上潜藏着一片落叶，很显眼。", "explanation": "这里应该用〈漂浮〉。潜藏着表示看不见，落叶漂在湖面上很显眼，应说“湖面上漂浮着一片落叶”。"}, {"text": "墙上潜藏着一幅画，很多人都在看。", "explanation": "这里应该用〈挂着〉。潜藏着指不被看见，墙上的画人人可见，应说“墙上挂着一幅画”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "潜藏着", "is_correct": true, "explanation": "正确。“潜藏着”表示小鸟躲在树叶后面，孩子们找不到，与句意相合。"}, {"text": "停放着", "is_correct": false, "explanation": "语义：“停放”用于车辆、物品，不说树叶后停放着一只鸟。"}, {"text": "悬挂着", "is_correct": false, "explanation": "搭配：“悬挂”多接物件，不用于活的鸟。"}, {"text": "摆放着", "is_correct": false, "explanation": "语义：“摆放”指有意摆出来，与“孩子们找不到它”的情境相矛盾。"}], "explanations": {"潜藏着": "正确。“潜藏着”表示小鸟躲在树叶后面，孩子们找不到，与句意相合。", "停放着": "语义：“停放”用于车辆、物品，不说树叶后停放着一只鸟。", "悬挂着": "搭配：“悬挂”多接物件，不用于活的鸟。", "摆放着": "语义：“摆放”指有意摆出来，与“孩子们找不到它”的情境相矛盾。"}, "sentence_index": 6, "correct_answer": "潜藏着"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份计划在全体会议上潜藏着，经理当场就对大家讲清楚了。", "explanation": "这里应该用〈宣布〉。潜藏着指东西躲着、别人看不见，而计划在会议上当场讲清楚，人人都知道，应说“这份计划在会议上宣布了”。"}, {"text": "操场中央潜藏着一座大钟楼，远远地就能望见它的钟面。", "explanation": "这里应该用〈矗立〉。潜藏着指东西躲着、别人看不见，而钟楼高大醒目、远远可望，应说“操场中央矗立着一座大钟楼”。"}, {"text": "教室里潜藏着一块大黑板，全班同学都能看清上面的字。", "explanation": "这里应该用〈立着〉。潜藏着指东西躲着、别人看不见，而大黑板醒目，人人都能看清，应说“教室里立着一块大黑板”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "草堆里潜藏起来一只兔子。", "corrected_sentence": "草堆里潜藏着一只兔子。", "error_description": "错误在于“潜藏”后的“起来”。应为“潜藏着”；“潜藏起来”是不及物的，后面不能直接接宾语“一只兔子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23042, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "书架后面潜藏了着一本旧书。", "corrected_sentence": "书架后面潜藏着一本旧书。", "error_description": "“潜藏着”已含体标“着”，又加“了”构成“了着”，属双重体标，不合语法；应只保留“着”。错误形式：潜藏了着；正确形式：潜藏着。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
