INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23052, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23052, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "就是，用在两个成分之间，表示后一成分就是前一成分，或是对前一成分的解释。", "primary_collocate": null, "pronunciation": "jí", "ipa": "tɕi˧˥", "syllable_count": 1, "sentences": [{"text": "他的生日是十月一日，即国庆节。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天是星期六，即周末的第一天。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校在北京，即中国的首都。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天，即五月一日，是休息日。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最爱的水果，即苹果，今天特别便宜。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年有四个季节，即春、夏、秋、冬。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的家人，即爸爸妈妈和姐姐，都来了。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是我们的目标，即学好汉语。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王明，即我的老同学，下个月结婚。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的老家，即南方的小城，冬天不冷。", "target_word": "即", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "放在两个成分之间，表示后者就是前者，相当于就是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '884de977-ec2d-4491-87db-758e8e0f7dc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23052, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即", "is_correct": true, "explanation": "即（jí）表示就是，是本题的目标词。"}, {"text": "机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是机器。"}, {"text": "几", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个、若干。"}, {"text": "寄", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}], "explanations": {"即": "即（jí）表示就是，是本题的目标词。", "机": "jī（第一声）与 jí（第二声）声调不同，意思是机器。", "几": "jǐ（第三声）与 jí（第二声）声调不同，意思是几个、若干。", "寄": "jì（第四声）与 jí（第二声）声调不同，意思是寄送。"}, "sentence_index": null, "correct_answer": "即"}, "level_3": {"options": [{"text": "即", "is_correct": true, "explanation": "即：表示“十月一日”就是“国庆节”，符合句意。"}, {"text": "然而", "is_correct": false, "explanation": "语义：“然而”表示转折，前后没有转折关系，与句意不合。"}, {"text": "因此", "is_correct": false, "explanation": "搭配：“因此”表示因果，不能用来连接同一事物的两个名称。"}, {"text": "况且", "is_correct": false, "explanation": "语义：“况且”表示递进补充理由，这里没有递进关系。"}], "explanations": {"即": "即：表示“十月一日”就是“国庆节”，符合句意。", "然而": "语义：“然而”表示转折，前后没有转折关系，与句意不合。", "因此": "搭配：“因此”表示因果，不能用来连接同一事物的两个名称。", "况且": "语义：“况且”表示递进补充理由，这里没有递进关系。"}, "sentence_index": 0, "correct_answer": "即"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很聪明，即很努力。", "explanation": "这里应该用〈也〉。即连接同指的同位成分，“聪明”和“很努力”是两件事，不能用“即”连接。"}, {"text": "今天很冷，即明天很暖和。", "explanation": "这里应该用〈而〉。而连接转折或对比；“即”只用于前后同指的同位关系，不能表示对比。"}, {"text": "他不是老师，即医生。", "explanation": "这里应该用〈而是〉。即表示同位同指，不用于否定后的对比；“不是老师”和“医生”是对立关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23052, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "即", "is_correct": true, "explanation": "即（jí）表示就是，是本题的目标词。"}, {"text": "基", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是基础。"}, {"text": "挤", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压。"}, {"text": "季", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}], "explanations": {"即": "即（jí）表示就是，是本题的目标词。", "基": "jī（第一声）与 jí（第二声）声调不同，意思是基础。", "挤": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤压。", "季": "jì（第四声）与 jí（第二声）声调不同，意思是季节。"}, "sentence_index": null, "correct_answer": "即"}, "level_3": {"options": [{"text": "即", "is_correct": true, "explanation": "即：表示“爸爸妈妈和姐姐”是“我的家人”的具体所指，符合句意。"}, {"text": "但", "is_correct": false, "explanation": "语义：“但”表示转折，前后没有转折关系，与句意不合。"}, {"text": "从而", "is_correct": false, "explanation": "搭配：“从而”表示结果，不能用来连接同位的成分。"}, {"text": "于是", "is_correct": false, "explanation": "语义：“于是”表示顺承或结果，不能说明“我的家人”与“爸爸妈妈和姐姐”是同一关系。"}], "explanations": {"即": "即：表示“爸爸妈妈和姐姐”是“我的家人”的具体所指，符合句意。", "但": "语义：“但”表示转折，前后没有转折关系，与句意不合。", "从而": "搭配：“从而”表示结果，不能用来连接同位的成分。", "于是": "语义：“于是”表示顺承或结果，不能说明“我的家人”与“爸爸妈妈和姐姐”是同一关系。"}, "sentence_index": 6, "correct_answer": "即"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去北京即上海出差。", "explanation": "这里应该用〈或〉。或表示二选一；“即”表示同位，不能用于两个不同的地点之间。"}, {"text": "我们班有三十个学生，即四十个人。", "explanation": "这里应该去掉“即”。即表示同位同指，“三十个学生”和“四十个人”数量不同，不能是同一事物，不能用“即”连接。"}, {"text": "我喜欢喝茶，即咖啡。", "explanation": "这里应该用〈和〉。“和”连接并列的事物；“即”表示同位同指，“茶”和“咖啡”是两种饮料，不能说成同一事物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23052, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我最喜欢的季节，就即秋天，天气最舒服。", "corrected_sentence": "我最喜欢的季节，即秋天，天气最舒服。", "error_description": "重复：“就”与“即”都表示“就是”，不能同时用，应删去“就”，说“即秋天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23052, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "王明，即即我们班的同学，表现很好。", "corrected_sentence": "王明，即我们班的同学，表现很好。", "error_description": "重复：“即”只用一次，应说“即我们班的同学”，不能说“即即我们班的同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5aef806e-c1a6-4ffd-a6b5-5550b603aa25') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
