INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23054, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "地面上可以种花、种菜的泥土。", "primary_collocate": null, "pronunciation": "tǔ dì", "ipa": "tʰu˨˩˦ ti˥˩", "syllable_count": 2, "sentences": [{"text": "这块土地可以种菜。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在土地上种了很多花。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天到了，土地变软了。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土地很肥，菜长得好。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，土地湿湿的。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民每天都在土地上工作。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家后面有一块小土地，妈妈种了青菜。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的土地太干，花不容易活。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用手摸了摸湿湿的土地。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的土地里，种什么都长得好。", "target_word": "土地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "块", "label": "量词"}, {"form": "片", "label": "量词"}], "register": "中性", "sense_fingerprint": "可种花种菜的泥土、田地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c0895758-7575-4f3f-b486-94a8a11fbda5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23054, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "土地", "is_correct": true, "explanation": "正确答案。土地 tǔ dì 指地上可以种花种菜的泥土。"}, {"text": "徒弟", "is_correct": false, "explanation": "tú（第二声）与 tǔ（第三声）声调不同，意思是徒弟，与土地不同。"}, {"text": "土堤", "is_correct": false, "explanation": "dī（第一声）与 dì（第四声）声调不同，意思是泥土筑成的堤坝。"}, {"text": "土质", "is_correct": false, "explanation": "zhì 与 dì 声母不同（zh 与 d），意思是土壤的性质。"}], "explanations": {"土地": "正确答案。土地 tǔ dì 指地上可以种花种菜的泥土。", "徒弟": "tú（第二声）与 tǔ（第三声）声调不同，意思是徒弟，与土地不同。", "土堤": "dī（第一声）与 dì（第四声）声调不同，意思是泥土筑成的堤坝。", "土质": "zhì 与 dì 声母不同（zh 与 d），意思是土壤的性质。"}, "sentence_index": null, "correct_answer": "土地"}, "level_3": {"options": [{"text": "土地", "is_correct": true, "explanation": "正确答案。“这块土地可以种菜”成立，土地指可以种菜的泥土。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能种菜，句子不成立。"}, {"text": "蛋糕", "is_correct": false, "explanation": "搭配：“种”的对象是植物，蛋糕不能说种菜。"}, {"text": "玻璃", "is_correct": false, "explanation": "体貌：玻璃透明而坚硬，不具备种菜所需的泥土性质。"}], "explanations": {"土地": "正确答案。“这块土地可以种菜”成立，土地指可以种菜的泥土。", "石头": "语义：石头不能种菜，句子不成立。", "蛋糕": "搭配：“种”的对象是植物，蛋糕不能说种菜。", "玻璃": "体貌：玻璃透明而坚硬，不具备种菜所需的泥土性质。"}, "sentence_index": 0, "correct_answer": "土地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这头土地很肥，菜长得好。", "explanation": "这里应该用〈片〉。“头”用于牛、猪等大牲畜，不用于计量土地，土地常用“块”或“片”。"}, {"text": "我家后面有一棵土地，妈妈种了青菜。", "explanation": "这里应该用〈块〉。“棵”用于树木、植物，不用于计量土地。"}, {"text": "爷爷在一朵土地上种了很多花。", "explanation": "这里应该用〈片〉。“朵”用于花朵、云朵等，不用于计量土地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23054, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "土地", "is_correct": true, "explanation": "正确答案。土地 tǔ dì 指地上可以种花种菜的泥土。"}, {"text": "土笛", "is_correct": false, "explanation": "dí（第二声）与 dì（第四声）声调不同，意思是陶制的笛子。"}, {"text": "土气", "is_correct": false, "explanation": "qì 与 dì 声母不同（q 与 d），意思是样式不时髦。"}, {"text": "吐气", "is_correct": false, "explanation": "首字 tǔ 相同，但 qì 与 dì 声母不同，意思是呼出气息。"}], "explanations": {"土地": "正确答案。土地 tǔ dì 指地上可以种花种菜的泥土。", "土笛": "dí（第二声）与 dì（第四声）声调不同，意思是陶制的笛子。", "土气": "qì 与 dì 声母不同（q 与 d），意思是样式不时髦。", "吐气": "首字 tǔ 相同，但 qì 与 dì 声母不同，意思是呼出气息。"}, "sentence_index": null, "correct_answer": "土地"}, "level_3": {"options": [{"text": "土地", "is_correct": true, "explanation": "正确答案。“我家后面有一块小土地，妈妈种了青菜”成立。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不能种青菜，句子不成立。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不是可以种植青菜的地方。"}, {"text": "地毯", "is_correct": false, "explanation": "配价：“种”要求有可以种植的场所，地毯不能作种植的地方。"}], "explanations": {"土地": "正确答案。“我家后面有一块小土地，妈妈种了青菜”成立。", "黑板": "语义：黑板不能种青菜，句子不成立。", "饼干": "语义：饼干是食品，不是可以种植青菜的地方。", "地毯": "配价：“种”要求有可以种植的场所，地毯不能作种植的地方。"}, "sentence_index": 6, "correct_answer": "土地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们在土地上滑冰，玩得很开心。", "explanation": "这里应该用〈冰面〉。土地指地上可以种花、种菜的泥土，不能用来滑冰，在冰上运动要用“冰面”。"}, {"text": "爷爷的院子里有一只土地，种了几棵树。", "explanation": "这里应该用〈块〉。“只”多用于动物，不用于计量土地。"}, {"text": "我昨天在菜园里看到了一辆土地。", "explanation": "这里应该用〈块〉。“辆”用于车辆，不能用来计量土地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23054, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爷爷在这头土地上种了很多青菜。", "corrected_sentence": "爷爷在这块土地上种了很多青菜。", "error_description": "量词错误：“头”用于牛、猪等大牲畜，不能用于计量土地，应说“这块土地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23054, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "奶奶把这只土地翻了一遍。", "corrected_sentence": "奶奶把这片土地翻了一遍。", "error_description": "量词错误：“只”多用于动物，土地应该用“片”或“块”计量，应说“这片土地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'df627236-815d-426d-a4a4-4a9817316a62') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
