INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把堆在一起的东西翻一翻。", "primary_collocate": null, "pronunciation": "fān duī", "ipa": "fan˥ tweɪ˥", "syllable_count": 2, "sentences": [{"text": "仓库里的粮食堆得很高，工人正在翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤堆里面太热，必须马上翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅说，晒过的稻谷晚上要翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木头堆湿了，请明天翻堆晾一晾。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果放久了容易坏，所以要经常翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用大铲子翻堆，花了两个小时。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人翻堆后，发现下面的土豆都发芽了。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天下班前都要去院子里给柴火翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "垃圾站的工人正在翻堆，找能回收的东西。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "麦子刚收回来，得先摊开再翻堆。", "target_word": "翻堆", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻堆机", "label": "复合"}], "register": "中性", "sense_fingerprint": "把堆放的东西翻动一遍", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026057aa-5864-49c0-96de-f25d5ea2ff13') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翻堆", "is_correct": true, "explanation": "正确：粮食堆得很高，工人需要翻动堆放的粮食，符合语境。"}, {"text": "刷漆", "is_correct": false, "explanation": "语义：刷漆是涂饰物体表面，与堆放的粮食无关。"}, {"text": "装订", "is_correct": false, "explanation": "搭配：「装订」多指书册，不用于粮食堆。"}, {"text": "焊接", "is_correct": false, "explanation": "语义：焊接是连接金属的作业，与粮食堆的情况不符。"}], "explanations": {"翻堆": "正确：粮食堆得很高，工人需要翻动堆放的粮食，符合语境。", "刷漆": "语义：刷漆是涂饰物体表面，与堆放的粮食无关。", "装订": "搭配：「装订」多指书册，不用于粮食堆。", "焊接": "语义：焊接是连接金属的作业，与粮食堆的情况不符。"}, "sentence_index": 0, "correct_answer": "翻堆"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "炒饭的时候要不断翻堆米饭。", "explanation": "这里应该用〈翻炒〉。在锅中翻动食材要说翻炒，翻堆指翻动堆放的东西。"}, {"text": "他翻堆了一份旧报纸，发现了一则新闻。", "explanation": "这里应该用〈翻阅〉。翻看报纸要说翻阅，翻堆不用于翻看纸张。"}, {"text": "这台旧冰箱翻堆以后很好用。", "explanation": "这里应该用〈翻新〉。把旧物修整一新要说翻新，翻堆指翻动堆放的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻堆", "is_correct": true, "explanation": "正确：工人翻动堆放的土豆后，才会发现下面的土豆发芽了。"}, {"text": "冷冻", "is_correct": false, "explanation": "语义：冷冻会使土豆停止生长，与「发芽」的结果矛盾。"}, {"text": "烧烤", "is_correct": false, "explanation": "语义：烤熟的土豆无法发芽，与「发芽」的结果矛盾。"}, {"text": "粉碎", "is_correct": false, "explanation": "搭配：「粉碎」一般用于坚硬物体，与整堆土豆的处理不搭配。"}], "explanations": {"翻堆": "正确：工人翻动堆放的土豆后，才会发现下面的土豆发芽了。", "冷冻": "语义：冷冻会使土豆停止生长，与「发芽」的结果矛盾。", "烧烤": "语义：烤熟的土豆无法发芽，与「发芽」的结果矛盾。", "粉碎": "搭配：「粉碎」一般用于坚硬物体，与整堆土豆的处理不搭配。"}, "sentence_index": 6, "correct_answer": "翻堆"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这篇古文要翻堆成白话文。", "explanation": "这里应该用〈翻译〉。翻译指把一种语言转换成另一种语言，翻堆指翻动堆放的东西。"}, {"text": "河水翻堆起来，溅起白色的浪花。", "explanation": "这里应该用〈翻腾〉。液体上下翻涌要说翻腾，翻堆指翻动堆放的东西。"}, {"text": "小猫在草地上翻堆，玩得很开心。", "explanation": "这里应该用〈翻滚〉。小猫在地上打滚要说翻滚，翻堆指翻动堆放的物料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里的柴火堆得太久了，应该翻堆了了。", "corrected_sentence": "院子里的柴火堆得太久了，应该翻堆了。", "error_description": "错误：「翻堆了」后又多加了一个「了」，写成「了了」连用。正确形式：应该翻堆了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23056, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人翻堆翻的很快。", "corrected_sentence": "工人翻堆翻得很快。", "error_description": "错误：重复动词后的补语要用「得」，不能用「的」。正确形式：翻堆翻得很快。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e87727d-c657-433b-85fc-ed850eeffff2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指新出现的、大家还不知道的事情。", "primary_collocate": null, "pronunciation": "xīn liào", "ipa": "ɕin˥ liɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他说他有一个新料，是关于老板的，大家都不知道。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天报纸上有一个关于学校的新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们都想听听班里的新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新料太特别了，我还没听过。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王又带来了新料，是关于老板的。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁有新料？下课后告诉我。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者找到了一个大新料，马上写成了报道。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把新料发到了网上。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天又带来一个新料，大家都围过来听。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办公室里每天都有人说新料。", "target_word": "新料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "新料：刚出现、大家还不知道的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "新料", "is_correct": true, "explanation": "xīn liào，指新出现、大家还不知道的事情或材料，即本义。"}, {"text": "金料", "is_correct": false, "explanation": "jīn 与 xīn 声母不同，金料指金的原料，意思不同。"}, {"text": "心量", "is_correct": false, "explanation": "liàng 与 liào 韵母不同，心量指度量、器量，意思不同。"}, {"text": "新粮", "is_correct": false, "explanation": "liáng 与 liào 的声调和韵母都不同，新粮指刚收获的粮食。"}, {"text": "辛劳", "is_correct": false, "explanation": "láo 与 liào 的声调和韵母不同，辛劳指辛苦劳累。"}], "explanations": {"新料": "xīn liào，指新出现、大家还不知道的事情或材料，即本义。", "金料": "jīn 与 xīn 声母不同，金料指金的原料，意思不同。", "心量": "liàng 与 liào 韵母不同，心量指度量、器量，意思不同。", "新粮": "liáng 与 liào 的声调和韵母都不同，新粮指刚收获的粮食。", "辛劳": "láo 与 liào 的声调和韵母不同，辛劳指辛苦劳累。"}, "sentence_index": null, "correct_answer": "新料"}, "level_3": {"options": [{"text": "颜料", "is_correct": false, "explanation": "语义：“颜料”是用来着色的物品，不是“大家都不知道”的事情，句意不通。"}, {"text": "饲料", "is_correct": false, "explanation": "搭配：“饲料”一般用“袋”计，不说“一个”，与句中的量词搭配不当。"}, {"text": "木料", "is_correct": false, "explanation": "语义：“木料”是木材实物，不能说成“大家都不知道”的情况，与句意不符。"}, {"text": "新料", "is_correct": true, "explanation": "正确选项“新料”与“他说他有一个……，大家都不知道”的语境相合。"}], "explanations": {"颜料": "语义：“颜料”是用来着色的物品，不是“大家都不知道”的事情，句意不通。", "饲料": "搭配：“饲料”一般用“袋”计，不说“一个”，与句中的量词搭配不当。", "木料": "语义：“木料”是木材实物，不能说成“大家都不知道”的情况，与句意不符。", "新料": "正确选项“新料”与“他说他有一个……，大家都不知道”的语境相合。"}, "sentence_index": 0, "correct_answer": "新料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这是几年前的新料，早就过时了。", "explanation": "这里应该用〈旧闻〉。“新料”指刚出现的消息，不能指几年前的事。"}, {"text": "这杯新料太烫了，他喝得直咧嘴。", "explanation": "这里的〈新料〉被误当作饮料。“新料”指新出现的、大家还不知道的消息或事情，不能当作可以喝的东西。"}, {"text": "他每天都给新料浇水。", "explanation": "这里的〈新料〉被误当作植物。“新料”指新出现的消息或事情，不能当作需要浇水的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "玩具", "is_correct": false, "explanation": "语义：“玩具”是供玩耍的物品，记者“找到一个大玩具”不能构成有价值的新闻，句意不通。"}, {"text": "墨水", "is_correct": false, "explanation": "搭配：“墨水”一般用“瓶”“支”计，不说“一个大墨水”，与句中搭配不当。"}, {"text": "鞋垫", "is_correct": false, "explanation": "搭配：“鞋垫”以“双”或“片”计，与“一个大”不搭，也不指可报道的事情。"}, {"text": "新料", "is_correct": true, "explanation": "正确选项“新料”与“记者找到了一个大……”的新闻语境相合。"}], "explanations": {"玩具": "语义：“玩具”是供玩耍的物品，记者“找到一个大玩具”不能构成有价值的新闻，句意不通。", "墨水": "搭配：“墨水”一般用“瓶”“支”计，不说“一个大墨水”，与句中搭配不当。", "鞋垫": "搭配：“鞋垫”以“双”或“片”计，与“一个大”不搭，也不指可报道的事情。", "新料": "正确选项“新料”与“记者找到了一个大……”的新闻语境相合。"}, "sentence_index": 6, "correct_answer": "新料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把新料穿在身上，走出了教室。", "explanation": "这里的〈新料〉被误当作衣物。“新料”指新出现的消息或事情，不能穿在身上。"}, {"text": "他的新料很高，比我还高。", "explanation": "这里的〈新料〉被误当作指人的身材。“新料”指新出现的消息或事情，不用来形容人的身高。"}, {"text": "妈妈把新料吃进了肚子里。", "explanation": "这里的〈新料〉被误当作食物。“新料”指新出现的消息或事情，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里昨天有一只新料，大家都很吃惊。", "corrected_sentence": "班里昨天有一个新料，大家都很吃惊。", "error_description": "量词错误：“新料”前应用量词“个”，不能用“只”（“只”多用于动物或成对的东西）。错误为“一只新料”，正确为“一个新料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23058, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天找到了一个的新料。", "corrected_sentence": "他昨天找到了一个新料。", "error_description": "助词错误：“一个”与名词之间不能加“的”，应说“一个新料”，不能说“一个的新料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
