INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23062, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23062, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "水慢慢流进小洞。", "primary_collocate": null, "pronunciation": "shèn tòu", "ipa": "ʂən˥˩ tʰoʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "雨停了，水慢慢渗透进土里。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙子很松，水慢慢渗透下去了。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树根旁的小洞里，雨水慢慢渗透进去了。", "target_word": "渗透", "complexity_tier": "T3", "furigana": "shù gēn páng de xiǎo dòng lǐ , yǔ shuǐ màn màn shèn tòu jìn qù le", "sentence_source": "generated"}, {"text": "墙上有小洞，雨水一点一点渗透进来。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "木板上的小孔里，水慢慢渗透进去。", "target_word": "渗透", "complexity_tier": "T3", "furigana": "mù bǎn shàng de xiǎo kǒng lǐ , shuǐ màn màn shèn tòu jìn qù", "sentence_source": "generated"}, {"text": "瓶底的小孔里，水慢慢渗透进来。", "target_word": "渗透", "complexity_tier": "T3", "furigana": "píng dǐ de xiǎo kǒng lǐ , shuǐ màn màn shèn tòu jìn lái", "sentence_source": "generated"}, {"text": "石缝里的小洞，水一点一点渗透进去。", "target_word": "渗透", "complexity_tier": "T3", "furigana": "shí fèng lǐ de xiǎo dòng , shuǐ yì diǎn yì diǎn shèn tòu jìn qù", "sentence_source": "generated"}, {"text": "地面是石头，水很难渗透。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了一夜，水渗透到了地下室。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海绵很软，水一倒上去就渗透了。", "target_word": "渗透", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "渗透了", "label": "体标"}, {"form": "渗透着", "label": "体标"}, {"form": "渗透过", "label": "体标"}, {"form": "滲透", "label": "繁体"}, {"form": "渗透力", "label": "复合"}], "register": "中性", "sense_fingerprint": "渗透：水慢慢地流进物体的小洞或缝隙", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e21b19a8-b860-4241-bf4a-a935fa36fc43') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23062, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "咀嚼", "is_correct": false, "explanation": "搭配：“咀嚼”的对象是食物，不说水“咀嚼进土里”。"}, {"text": "闪烁", "is_correct": false, "explanation": "语义：“闪烁”指光亮忽明忽暗，与水流入土中无关。"}, {"text": "拍打", "is_correct": false, "explanation": "搭配：“拍打”指用手或物体击打，不表示水慢慢进入土里。"}, {"text": "渗透", "is_correct": true, "explanation": "正确选项“渗透”表示水慢慢流入物体的缝隙，与“雨停了，水慢慢……进土里”相合。"}], "explanations": {"咀嚼": "搭配：“咀嚼”的对象是食物，不说水“咀嚼进土里”。", "闪烁": "语义：“闪烁”指光亮忽明忽暗，与水流入土中无关。", "拍打": "搭配：“拍打”指用手或物体击打，不表示水慢慢进入土里。", "渗透": "正确选项“渗透”表示水慢慢流入物体的缝隙，与“雨停了，水慢慢……进土里”相合。"}, "sentence_index": 0, "correct_answer": "渗透"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "小虫一点一点渗透进了洞里。", "explanation": "这里应该用〈钻〉。渗透只用于液体、气体，不用于虫子主动钻入。"}, {"text": "他把水渗透进瓶子里。", "explanation": "这里应该用〈灌〉。渗透指液体自然慢慢透入，不用于人有意注入。"}, {"text": "他的脚一点一点渗透进了泥里。", "explanation": "这里应该用〈陷进〉。渗透只用于液体、气体，不用于人的脚等固体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23062, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "粘贴", "is_correct": false, "explanation": "搭配：“粘贴”指把东西贴在一起，水不能被粘贴进小洞。"}, {"text": "切割", "is_correct": false, "explanation": "语义：“切割”是用刀等割开，水不会切割进石缝。"}, {"text": "敲打", "is_correct": false, "explanation": "语义：“敲打”是击打，不表示水流入石缝。"}, {"text": "渗透", "is_correct": true, "explanation": "正确选项“渗透”表示水慢慢透入缝隙，与“石缝里的小洞，水一点一点……进去”相合。"}], "explanations": {"粘贴": "搭配：“粘贴”指把东西贴在一起，水不能被粘贴进小洞。", "切割": "语义：“切割”是用刀等割开，水不会切割进石缝。", "敲打": "语义：“敲打”是击打，不表示水流入石缝。", "渗透": "正确选项“渗透”表示水慢慢透入缝隙，与“石缝里的小洞，水一点一点……进去”相合。"}, "sentence_index": 6, "correct_answer": "渗透"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把杯子渗透到桌上。", "explanation": "这里应该用〈放〉。渗透用于液体自然透入，不用于人把物体放置。"}, {"text": "小猫用爪子渗透了那块地毯。", "explanation": "这里应该用〈抓〉。“渗透”只指水等液体慢慢透入，不用于动物用爪子抓握。"}, {"text": "妈妈慢慢渗透了一碗汤。", "explanation": "这里应该用〈喝〉。渗透是液体逐渐透入的意思，不用于人喝汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23062, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "雨水慢慢渗透墙缝里。", "corrected_sentence": "雨水慢慢渗透进墙缝里。", "error_description": "缺少方向补语：“渗透”后应接“进”，写作“渗透进墙缝里”，不能直接接处所词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23062, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水渗透很快。", "corrected_sentence": "水渗透得很快。", "error_description": "补语错误：表示程度的补语要用“得”连接，应为“渗透得很快”，不能只说“渗透很快”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0fcc3fe-1208-4d94-900c-0cca69d3dfe5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
