INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23064, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不能没有，少了就不行。", "primary_collocate": null, "pronunciation": "bù kě huò quē", "ipa": "pu˥˩ kʰɤ˨˩˦ xuo˥˩ tɕʰyɛ˥", "syllable_count": 4, "sentences": [{"text": "对学生来说，书是不可或缺的。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜里，辣椒是不可或缺的。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们球队不可或缺的人。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行时，地图是不可或缺的东西。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好老师对学校来说不可或缺。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "米和水是做粥不可或缺的材料。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在我家，奶奶的故事不可或缺。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，一件厚外套不可或缺。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的笑声是聚会上不可或缺的。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学汉语，每天练习是不可或缺的。", "target_word": "不可或缺", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不可或缺的", "label": "定语形式"}], "register": "书面语", "sense_fingerprint": "不能没有，少了就不行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9ba9e274-b8ab-4e4c-bbe4-4a904cae9285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23064, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饥饿", "is_correct": false, "explanation": "语义：书不会饥饿，“饥饿”只能说有生命的人或动物。"}, {"text": "健忘", "is_correct": false, "explanation": "搭配：“健忘”形容人记性差，不能用来说书。"}, {"text": "又高又胖", "is_correct": false, "explanation": "体貌：“又高又胖”描述人或动物的体形，书没有体形可说。"}, {"text": "不可或缺", "is_correct": true, "explanation": "“不可或缺”说明书对学生缺了就不行，符合句子的意思。"}], "explanations": {"饥饿": "语义：书不会饥饿，“饥饿”只能说有生命的人或动物。", "健忘": "搭配：“健忘”形容人记性差，不能用来说书。", "又高又胖": "体貌：“又高又胖”描述人或动物的体形，书没有体形可说。", "不可或缺": "“不可或缺”说明书对学生缺了就不行，符合句子的意思。"}, "sentence_index": 0, "correct_answer": "不可或缺"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子终会长大，这是不可或缺的。", "explanation": "这里应该用〈不可避免〉。不可或缺说缺了就不行，强调重要；说孩子长大是无法避免的，要用〈不可避免〉。"}, {"text": "这次远足很不可或缺，每个人都要带水。", "explanation": "这里应该用〈重要〉。不可或缺表示程度已到顶，不能用“很”修饰；“很重要”才是一般的程度强调。"}, {"text": "月亮每个月都会圆缺，这是不可或缺的。", "explanation": "这里应该用〈必然〉。不可或缺说缺了就不行，强调重要；说月亮圆缺是必然的规律，要用〈必然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23064, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "害羞", "is_correct": false, "explanation": "搭配：“害羞”形容人的心理状态，不能用来说“故事”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，故事没有身材可言。"}, {"text": "无精打采", "is_correct": false, "explanation": "搭配：“无精打采”形容人没有精神，不能用来形容故事。"}, {"text": "不可或缺", "is_correct": true, "explanation": "“不可或缺”说明奶奶的故事在家里缺了就不行，符合句子的语境。"}], "explanations": {"害羞": "搭配：“害羞”形容人的心理状态，不能用来说“故事”。", "高大": "体貌：“高大”形容身材，故事没有身材可言。", "无精打采": "搭配：“无精打采”形容人没有精神，不能用来形容故事。", "不可或缺": "“不可或缺”说明奶奶的故事在家里缺了就不行，符合句子的语境。"}, "sentence_index": 6, "correct_answer": "不可或缺"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "早上一醒来，天就会亮，这是不可或缺的。", "explanation": "这里应该用〈自然而然〉。不可或缺说缺了就不行，强调重要；说天亮是自然而然的事，要用〈自然而然〉。"}, {"text": "考试结束后，同学们都会放松，这是不可或缺的。", "explanation": "这里应该用〈必定〉。不可或缺说缺了就不行，强调重要；说考试后同学放松是必定会发生的，要用〈必定〉。"}, {"text": "火车到站时，外面下起了雨，这是不可或缺的。", "explanation": "这里应该用〈偶然〉。不可或缺说缺了就不行，强调重要；说到站时下雨是偶然的，要用〈偶然〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23064, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是学习中不可或缺工具。", "corrected_sentence": "这是学习中不可或缺的工具。", "error_description": "“不可或缺”修饰名词时要加“的”，应说“不可或缺的工具”；漏掉“的”不成词组。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23064, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位画家是美术界不可或缺的的人物。", "corrected_sentence": "这位画家是美术界不可或缺的人物。", "error_description": "“不可或缺”修饰名词只用一个“的”，“的的”多出了一个，应说“不可或缺的人物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7deeda03-da33-4b74-a27c-2bf61f5f2016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
