INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具让东西动起来。", "primary_collocate": null, "pronunciation": "cāo zuò", "ipa": "tsʰɑu̯˥ tswo˥˩", "syllable_count": 2, "sentences": [{"text": "他会操作这台新机器。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请按照说明书操作电脑。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在操作机器。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个手机很简单，老人也会操作。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不能随便操作这些按钮。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么操作显微镜。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用左手操作鼠标，很不习惯。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你操作错了，要先按红色的键。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他会操作吊车，工作很稳。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台洗衣机我不会操作，你来帮我吧。", "target_word": "操作", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "操作了", "label": "完成体"}, {"form": "操作着", "label": "持续体"}, {"form": "操作过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "操作|动词|用手或工具使机器、设备运转", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b13cb17d-02c1-4f79-bcfd-22a8dcf8b695') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "正确：操作（动词）指用手或工具使机器运转，与“这台新机器”搭配。"}, {"text": "阅读", "is_correct": false, "explanation": "语义：“阅读”的对象是文字，机器不能被读。"}, {"text": "喝", "is_correct": false, "explanation": "配价：“喝”的宾语须是饮品，不能说“喝这台新机器”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”的对象是歌曲，机器不能唱。"}], "explanations": {"操作": "正确：操作（动词）指用手或工具使机器运转，与“这台新机器”搭配。", "阅读": "语义：“阅读”的对象是文字，机器不能被读。", "喝": "配价：“喝”的宾语须是饮品，不能说“喝这台新机器”。", "唱": "语义：“唱”的对象是歌曲，机器不能唱。"}, "sentence_index": 0, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他站在台上操作乐队。", "explanation": "这里应用“指挥”。“操作”的对象是机器或设备，不能用来指挥乐队，指挥乐队要用“指挥”。"}, {"text": "老人会操作时间，很有经验。", "explanation": "这里应用“安排”。“操作”的对象是机器或设备，时间不能被“操作”，安排时间要用“安排”。"}, {"text": "这个手机会操作老人。", "explanation": "这里应用“控制”。“操作”指用手或工具让机器等东西动起来，施事是人、对象是机器；人被机器支配要说“控制”，不能说“操作”人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "操作", "is_correct": true, "explanation": "正确：操作（动词）指用手使鼠标运转，“用左手操作鼠标”符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "配价：“吃”的宾语须是食物，“用左手吃鼠标”不成立。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”一般指用牙齿咬食物或物体，“咬鼠标”不符合语境。"}, {"text": "写", "is_correct": false, "explanation": "语义：“写”的对象是文字或图形，不能写鼠标。"}], "explanations": {"操作": "正确：操作（动词）指用手使鼠标运转，“用左手操作鼠标”符合句意。", "吃": "配价：“吃”的宾语须是食物，“用左手吃鼠标”不成立。", "咬": "语义：“咬”一般指用牙齿咬食物或物体，“咬鼠标”不符合语境。", "写": "语义：“写”的对象是文字或图形，不能写鼠标。"}, "sentence_index": 6, "correct_answer": "操作"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我不会操作这首歌，你来唱吧。", "explanation": "这里应用“演唱”。“操作”的对象是机器或设备，歌曲不能被“操作”，唱歌要用“演唱”。"}, {"text": "我会操作这碗饭，你放心吧。", "explanation": "这里应用“煮”。“操作”的对象是机器或设备，饭要用“煮”或“做”，不能被“操作”。"}, {"text": "妈妈每天操作一朵花，很认真。", "explanation": "这里应用“浇”。“操作”的对象是机器或设备，花要用“浇”或“照顾”，不能被“操作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位工人把那台大型机器操作很熟练。", "corrected_sentence": "这位工人把那台大型机器操作得很熟练。", "error_description": "错误形式：“操作很熟练”。正确形式：“操作得很熟练”。程度补语前须用“得”连接动词与补语“很熟练”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23068, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你能帮我操作一下了这台电脑吗？", "corrected_sentence": "你能帮我操作一下这台电脑吗？", "error_description": "错误形式：“操作一下了这台电脑”。正确形式：“操作一下这台电脑”。动量词“一下”之后不能直接接“了”，多余的“了”应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b8ce0e32-1612-422e-a57e-9a90541b1d45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使水体、土壤等变成酸性，或使其酸性增强。", "primary_collocate": null, "pronunciation": "suān huà", "ipa": "swan˥ xwa˥˩", "syllable_count": 2, "sentences": [{"text": "酸性物质进入湖泊后，会使湖水酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气中的二氧化碳会酸化海水。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的气体让雨水酸化了。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地的土已经酸化了，花长不好。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖水酸化以后，鱼很难活下去。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多的化肥会让土地慢慢酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大量排放二氧化硫，会让湖泊酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酸化的海水对小鱼很不好。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他检查了湖水有没有酸化。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地球的海洋正在酸化，很多贝类受到影响。", "target_word": "酸化", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "酸化了", "label": "完成体"}, {"form": "酸化过", "label": "经历体"}, {"form": "酸化作用", "label": "复合词"}], "register": "科技", "sense_fingerprint": "使水体、土壤等变成酸性（pH降低）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "正确：「会使湖水酸化」指使水变酸，与前句「酸性物质进入湖泊」的因果关系一致。"}, {"text": "净化", "is_correct": false, "explanation": "语义：「净化」指去除杂质、变干净，与酸性物质带来的污染后果相反。"}, {"text": "澄清", "is_correct": false, "explanation": "语义：「澄清」指水变清澈，与酸性物质的危害不符。"}, {"text": "硬化", "is_correct": false, "explanation": "搭配：「硬化」一般用于土地、混凝土等，不能说「使湖水硬化」。"}], "explanations": {"酸化": "正确：「会使湖水酸化」指使水变酸，与前句「酸性物质进入湖泊」的因果关系一致。", "净化": "语义：「净化」指去除杂质、变干净，与酸性物质带来的污染后果相反。", "澄清": "语义：「澄清」指水变清澈，与酸性物质的危害不符。", "硬化": "搭配：「硬化」一般用于土地、混凝土等，不能说「使湖水硬化」。"}, "sentence_index": 0, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种酸液酸化了金属管道。", "explanation": "这里应该用〈腐蚀〉。酸化是使物质变酸，酸液损坏金属应说「腐蚀」。"}, {"text": "用石灰酸化了酸性土壤。", "explanation": "这里应该用〈中和〉。石灰是碱性物质，用它处理酸性土壤是为了降低酸性，应说「中和」。"}, {"text": "冰块放在太阳下，很快就酸化了。", "explanation": "这里应该用〈融化〉。固体受热变成液体叫「融化」，「酸化」指使物质变酸，不能用于冰块。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "酸化", "is_correct": true, "explanation": "正确：「会让湖泊酸化」指排放的二氧化硫使湖水变酸，与前句的因果关系吻合。"}, {"text": "变红", "is_correct": false, "explanation": "语义：湖泊变红不是二氧化硫排放的后果，与句中的因果关系无关。"}, {"text": "美化", "is_correct": false, "explanation": "语义：「美化」指使环境变美，与排放污染物的语境相反。"}, {"text": "变甜", "is_correct": false, "explanation": "搭配：「变甜」一般用于食物或味道，不能用于湖泊。"}], "explanations": {"酸化": "正确：「会让湖泊酸化」指排放的二氧化硫使湖水变酸，与前句的因果关系吻合。", "变红": "语义：湖泊变红不是二氧化硫排放的后果，与句中的因果关系无关。", "美化": "语义：「美化」指使环境变美，与排放污染物的语境相反。", "变甜": "搭配：「变甜」一般用于食物或味道，不能用于湖泊。"}, "sentence_index": 6, "correct_answer": "酸化"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "铁在潮湿的空气中酸化了，表面长出了红锈。", "explanation": "这里应该用〈氧化〉。生锈是氧化反应，「酸化」指物质变酸，与此不符。"}, {"text": "这台电脑用了五年，屏幕已经酸化了。", "explanation": "这里应该用〈老化〉。电脑用久了会老化，「酸化」指物质变成酸性，不能用于电子设备。"}, {"text": "衣服晾在太阳下，很快就酸化了。", "explanation": "这里应该用〈烘干〉。衣服变干是水分蒸发，「酸化」指物质变酸，不能用于衣物干燥。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些废水让河水了酸化了。", "corrected_sentence": "这些废水让河水酸化了。", "error_description": "「酸化」是一个不可拆分的词，「了」不能插在它前面。错误：「河水了酸化了」多了一个「了」，应删去「酸化」前的「了」，句末「酸化了」表示完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23072, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "酸性废水让河水酸化的很快。", "corrected_sentence": "酸性废水让河水酸化得很快。", "error_description": "「酸化」后接补语要用助词「得」，不用「的」。错误：「酸化的很快」；正确：「酸化得很快」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
