INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23078, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "就是真的，不是假的。", "primary_collocate": null, "pronunciation": "shí wéi", "ipa": "ʂɻ̩˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "经专家检查，这块玉实为真品。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信实为爷爷亲笔所写，不是别人代写。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经过检验，这张画实为名家真迹。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他说的话句句实为真情，没有一点假。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这枚古钱币实为宋代之物，并非仿制。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "记者调查后发现，这些照片实为现场所拍。", "target_word": "实为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，这座塔实为千年前所建，不是新修的。", "target_word": "实为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份名单实为本人所写，请大家放心。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件首饰实为纯金所制，不是镀金的。", "target_word": "实为", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "检查结果显示，这批茶叶实为有机产品。", "target_word": "实为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "實為", "label": "繁体"}], "register": "书面", "sense_fingerprint": "确认真实可靠，不是假的：确实是", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6771e508-33d8-4986-99ed-fd591f44ae84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23078, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "实为", "is_correct": true, "explanation": "实为 shí wéi，意思是确实是、真正是，是正确答案。"}, {"text": "视为", "is_correct": false, "explanation": "视为 shì wéi 与 shí wéi 第一个音节声调不同（第四声与第二声），意思是把……看作。"}, {"text": "十位", "is_correct": false, "explanation": "十位 shí wèi 与 shí wéi 第二个音节声调不同（第四声），意思是十的位数。"}, {"text": "四维", "is_correct": false, "explanation": "四维 sì wéi 与 shí wéi 声母 s 与 sh 不同，声调也不同，意思是四个维度。"}, {"text": "诗味", "is_correct": false, "explanation": "诗味 shī wèi 两个音节的声调都与 shí wéi 不同，意思是诗的味道。"}], "explanations": {"实为": "实为 shí wéi，意思是确实是、真正是，是正确答案。", "视为": "视为 shì wéi 与 shí wéi 第一个音节声调不同（第四声与第二声），意思是把……看作。", "十位": "十位 shí wèi 与 shí wéi 第二个音节声调不同（第四声），意思是十的位数。", "四维": "四维 sì wéi 与 shí wéi 声母 s 与 sh 不同，声调也不同，意思是四个维度。", "诗味": "诗味 shī wèi 两个音节的声调都与 shí wéi 不同，意思是诗的味道。"}, "sentence_index": null, "correct_answer": "实为"}, "level_3": {"options": [{"text": "实为", "is_correct": true, "explanation": "实为表示确实是，与“经专家检查”得出的真品结论一致。"}, {"text": "冒充", "is_correct": false, "explanation": "语义：“冒充”指假装，与“经专家检查”得出的真品结论相反。"}, {"text": "成为", "is_correct": false, "explanation": "语义：“成为”指由别的状态转变，句中只是检查，并无变化。"}, {"text": "鉴别", "is_correct": false, "explanation": "语义：“鉴别”是人辨认真假，玉本身不能鉴别真品，句意不通。"}], "explanations": {"实为": "实为表示确实是，与“经专家检查”得出的真品结论一致。", "冒充": "语义：“冒充”指假装，与“经专家检查”得出的真品结论相反。", "成为": "语义：“成为”指由别的状态转变，句中只是检查，并无变化。", "鉴别": "语义：“鉴别”是人辨认真假，玉本身不能鉴别真品，句意不通。"}, "sentence_index": 0, "correct_answer": "实为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道题实为很难，大家都做不出来。", "explanation": "这里应该用〈确实〉。实为要接“是”或名词性成分，不能直接接“很难”这样的形容词。"}, {"text": "他实为可能是老师，我们都不太清楚。", "explanation": "这里应该用〈也许〉。实为表示已经确认的事实，不能与“可能”这类推测词同用，否则自相矛盾。"}, {"text": "我实为是学生。", "explanation": "实为本身已含“是”的意思，后面不能再加“是”，应说“我实为学生”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23078, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "实为", "is_correct": true, "explanation": "实为 shí wéi，意思是确实是、真正是，是正确答案。"}, {"text": "四围", "is_correct": false, "explanation": "四围 sì wéi 与 shí wéi 声母 s 与 sh 不同，声调也不同，意思是四周。"}, {"text": "四位", "is_correct": false, "explanation": "四位 sì wèi 与 shí wéi 的声母和声调都不同，意思是第四位或四位数。"}, {"text": "失位", "is_correct": false, "explanation": "失位 shī wèi 两个音节的声调都与 shí wéi 不同，意思是失去职位或位置。"}], "explanations": {"实为": "实为 shí wéi，意思是确实是、真正是，是正确答案。", "四围": "四围 sì wéi 与 shí wéi 声母 s 与 sh 不同，声调也不同，意思是四周。", "四位": "四位 sì wèi 与 shí wéi 的声母和声调都不同，意思是第四位或四位数。", "失位": "失位 shī wèi 两个音节的声调都与 shí wéi 不同，意思是失去职位或位置。"}, "sentence_index": null, "correct_answer": "实为"}, "level_3": {"options": [{"text": "实为", "is_correct": true, "explanation": "实为表示确实是，与“专家说”的确定判断一致。"}, {"text": "竟是", "is_correct": false, "explanation": "语义：“竟是”表示出乎意料，与“专家说”的平实陈述不符，句中没有意外的语境。"}, {"text": "也是", "is_correct": false, "explanation": "语义：“也是”表示并列，句中没有可与之并列的对象，与“专家说”的判断不合。"}, {"text": "据说", "is_correct": false, "explanation": "语义：“据说”表示传闻、未经证实，与“专家说”的确定判断相矛盾。"}], "explanations": {"实为": "实为表示确实是，与“专家说”的确定判断一致。", "竟是": "语义：“竟是”表示出乎意料，与“专家说”的平实陈述不符，句中没有意外的语境。", "也是": "语义：“也是”表示并列，句中没有可与之并列的对象，与“专家说”的判断不合。", "据说": "语义：“据说”表示传闻、未经证实，与“专家说”的确定判断相矛盾。"}, "sentence_index": 6, "correct_answer": "实为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "你实为哪国人？", "explanation": "这里应该用〈是〉。实为用来确认事实，不用于疑问句，问国籍应说“你是哪国人”。"}, {"text": "哈哈，这个玩笑实为逗死我了！", "explanation": "这里应该用〈真〉。实为表示“确实就是”的事实判断，用来陈述真相，不用于玩笑后的感叹；表达“好笑到极点”应说“真”。"}, {"text": "我们实为一起去买菜吧。", "explanation": "实为用来陈述事实，不能用于提议。提议应说“我们一起去买菜吧”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23078, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这份报告实为了他写的。", "corrected_sentence": "这份报告实为他写的。", "error_description": "错误：“实为”后误加了体标“了”。正确：“实为”是书面副词，本身不带体标，应说“这份报告实为他写的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23078, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座庙实为实为清代所建。", "corrected_sentence": "这座庙实为清代所建。", "error_description": "错误：“实为”重复出现。正确：“实为”只用一次，应说“这座庙实为清代所建”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
