INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23082, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工程学是教人们怎么造东西的学问。", "primary_collocate": null, "pronunciation": "gōng chéng xué", "ipa": "kʊŋ⁵⁵ ʈʂʰɤŋ³⁵ ɕɥe³⁵", "syllable_count": 3, "sentences": [{"text": "工程学告诉人们怎么造桥。", "target_word": "工程学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我弟弟想学工程学，以后自己造汽车。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程学是一门有用的学问。", "target_word": "工程学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸是工程学老师，教学生造小机器。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学了工程学，你就知道房子怎么盖。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程学课很有意思，我们每周做一个小东西。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想造机器人，要先学工程学。", "target_word": "工程学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对工程学很感兴趣，常常自己造东西。", "target_word": "工程学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程学不难，但要多动手。", "target_word": "工程学", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这所大学的工程学很有名。", "target_word": "工程学", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "工程學", "label": "繁体"}], "register": "中性", "sense_fingerprint": "工程学：教人怎么造东西的学问", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23082, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工程学", "is_correct": true, "explanation": "工程学：教人怎么造东西的学问，填入后“工程学告诉人们怎么造桥”符合语境。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，不会告诉人怎么造桥。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不能告诉人们造桥的方法。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“告诉”的主语要能说话或是文字，“咖啡”不能作“告诉”的主语。"}], "explanations": {"工程学": "工程学：教人怎么造东西的学问，填入后“工程学告诉人们怎么造桥”符合语境。", "厨房": "语义：厨房是做饭的地方，不会告诉人怎么造桥。", "蔬菜": "语义：蔬菜是食物，不能告诉人们造桥的方法。", "咖啡": "搭配：“告诉”的主语要能说话或是文字，“咖啡”不能作“告诉”的主语。"}, "sentence_index": 0, "correct_answer": "工程学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座桥的工程学要用两年才能完成。", "explanation": "这里应该用〈工程〉。工程指具体的建设项目，工程学是学问，不能指一项工程。"}, {"text": "他是一名工程学。", "explanation": "这里应该用〈工程师〉。工程学指学问，指人要说工程师。"}, {"text": "这座大楼的工程学很漂亮。", "explanation": "这里应该用〈建筑〉。工程学是学问，不能用来形容大楼的外观。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23082, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工程学", "is_correct": true, "explanation": "工程学：教人怎么造东西的学问，填入后“想造机器人，要先学工程学”符合语境。"}, {"text": "书法", "is_correct": false, "explanation": "语义：学书法与造机器人无关，不需要先学书法。"}, {"text": "芭蕾", "is_correct": false, "explanation": "语义：芭蕾是舞蹈，与造机器人无关。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“学”的对象是学科或技能，“石头”不能被“学”。"}], "explanations": {"工程学": "工程学：教人怎么造东西的学问，填入后“想造机器人，要先学工程学”符合语境。", "书法": "语义：学书法与造机器人无关，不需要先学书法。", "芭蕾": "语义：芭蕾是舞蹈，与造机器人无关。", "石头": "搭配：“学”的对象是学科或技能，“石头”不能被“学”。"}, "sentence_index": 6, "correct_answer": "工程学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工程学有三百名工人。", "explanation": "这里应该用〈工厂〉。工程学是学问，不能指拥有工人的单位。"}, {"text": "工程学上的工人很忙。", "explanation": "这里应该用〈工地〉。工地是施工的场所，工程学是学问，不是地点。"}, {"text": "这家工程学下个月要搬到新大楼。", "explanation": "这里应该用〈公司〉。工程学是学问，不能搬家，指单位要说公司。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23082, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我弟弟明年想学一个工程学。", "corrected_sentence": "我弟弟明年想学一门工程学。", "error_description": "量词错误：学科用“门”，不用“个”。应说“一门工程学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23082, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学工程学学很扎实。", "corrected_sentence": "他学工程学学得很扎实。", "error_description": "补语标记“得”漏掉。“学”的程度补语要用“学得很扎实”，应说“学工程学学得很扎实”，不能说“学工程学学很扎实”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
