INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23086, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "没有固定形状、能四处流动的物质。", "primary_collocate": null, "pronunciation": "qì tǐ", "ipa": "tɕʰi˥˩ tʰi˨˩˦", "syllable_count": 2, "sentences": [{"text": "水烧开后会变成气体。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氧气是一种没有颜色的气体。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个瓶子里装着一种有毒的气体。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气球里充满了气体，所以飞得很高。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂排出的气体让空气变脏了。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气体、液体和固体是物质的三种样子。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车排出的气体对环境不好。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开盖子，里面的气体跑出来了。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种气体没有味道，所以很危险。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干冰很冷，它会直接变成气体。", "target_word": "气体", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种气体", "label": "量词"}, {"form": "一团气体", "label": "量词"}], "register": "中性", "sense_fingerprint": "像空气一样没有固定形状、能四处流动的物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f20be542-fd2b-4af9-92a3-e1943594c231') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23086, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "气体", "is_correct": true, "explanation": "正确：气体指没有固定形状、能流动的物质，符合“水烧开后会变成”的语境。"}, {"text": "固体", "is_correct": false, "explanation": "语义：水烧开后变成的是气体，不会变成固体，这与烧开的常识相反。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：水烧开后不会变成冰块，冰块是低温形成的，与“烧开”矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“变成”后面要接一种物质，颜色是属性，不能说水变成颜色。"}], "explanations": {"气体": "正确：气体指没有固定形状、能流动的物质，符合“水烧开后会变成”的语境。", "固体": "语义：水烧开后变成的是气体，不会变成固体，这与烧开的常识相反。", "冰块": "语义：水烧开后不会变成冰块，冰块是低温形成的，与“烧开”矛盾。", "颜色": "搭配：“变成”后面要接一种物质，颜色是属性，不能说水变成颜色。"}, "sentence_index": 0, "correct_answer": "气体"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "夏天的气体很闷，让人喘不过气。", "explanation": "这里应该用〈空气〉。气体是较专业的词，描述日常环境中的空气要用空气。"}, {"text": "这道菜的气体很辣，吃完嘴巴发麻。", "explanation": "这里说的是味道，应该用〈味道〉。气体指一种物质，不能用来形容菜的辣味。"}, {"text": "他跑完步，气体很急，说不出话。", "explanation": "这里说的是呼吸，应该用〈呼吸〉。气体指一种物质，不能用来形容人喘气的样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23086, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "气体", "is_correct": true, "explanation": "正确：气体是汽车排放的废气中的物质，符合“汽车排出的”。"}, {"text": "形状", "is_correct": false, "explanation": "搭配：排出指排放物质，形状是属性，不能被排出。"}, {"text": "水果", "is_correct": false, "explanation": "语义：汽车不会排出水果，这与“排出”的常识不符。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：汽车排出的不是树叶，句子的意思会变得荒谬。"}], "explanations": {"气体": "正确：气体是汽车排放的废气中的物质，符合“汽车排出的”。", "形状": "搭配：排出指排放物质，形状是属性，不能被排出。", "水果": "语义：汽车不会排出水果，这与“排出”的常识不符。", "树叶": "语义：汽车排出的不是树叶，句子的意思会变得荒谬。"}, "sentence_index": 6, "correct_answer": "气体"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这杯果汁是气体。", "explanation": "果汁是液体，不是气体。这里应该用〈液体〉。"}, {"text": "他性格很强，是一种很强的气体。", "explanation": "气体指一种物质，不能用来形容人的性格或气势。"}, {"text": "我喝了一杯气体，很解渴。", "explanation": "这里把气体当成了〈汽水〉这类饮料。气体指空气一样的物质，不能拿来喝，应该说〈汽水〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23086, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室的桌子上放着一只气体。", "corrected_sentence": "实验室的桌子上放着一瓶气体。", "error_description": "错误：量词“一只”。“只”用于单个动物，不能用于气体。正确：“一瓶气体”，盛装气体要用〈瓶〉等量词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23086, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些气体们都没有颜色。", "corrected_sentence": "这些气体都没有颜色。", "error_description": "错误：“气体们”，在气体后面加了“们”。“们”只用于指人的名词，“这些”已经表示复数，不能再加“们”。正确：“这些气体”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2bc82110-a7fa-4448-8b51-2c6a20f47e0a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
