INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23090, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "可以产生变化的能力。", "primary_collocate": null, "pronunciation": "huó xìng", "ipa": "xwo˧˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "这个社区缺少活性，年轻人都搬走了。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新政策给市场带来了新的活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想增强团队的活性，让大家多提意见。", "target_word": "活性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市很有活性，每年都有新的变化。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的活性来自学生们的新想法。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老办法太多，会让工作失去活性。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "农村市场的活性正在慢慢变强。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把新游戏加进课堂，增强了课堂的活性。", "target_word": "活性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个行业几年没变化，已经没有活性了。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "一个有活性的系统，能很快适应新情况。", "target_word": "活性", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词：市场、社区、团队等能够产生新变化的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c72e6fc1-6a04-4152-89a4-f1736e5d22de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23090, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "活性：指社区能不断产生新变化的能力，缺少它年轻人才会离开，符合句意。"}, {"text": "身高", "is_correct": false, "explanation": "搭配：“身高”是人的属性，社区不能说“缺少身高”。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”只用于人，社区没有年龄，句子说不通。"}, {"text": "密码", "is_correct": false, "explanation": "语义：密码与社区缺少什么无关，句子不通。"}], "explanations": {"活性": "活性：指社区能不断产生新变化的能力，缺少它年轻人才会离开，符合句意。", "身高": "搭配：“身高”是人的属性，社区不能说“缺少身高”。", "年龄": "搭配：“年龄”只用于人，社区没有年龄，句子说不通。", "密码": "语义：密码与社区缺少什么无关，句子不通。"}, "sentence_index": 0, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件衣服的活性很高，我买不起。", "explanation": "这里应该用〈价格〉。活性指事物能产生变化的能力，不用来说衣服的贵贱；说衣服贵要用价格。"}, {"text": "这块石头的活性很大，一个人搬不动。", "explanation": "这里应该用〈重量〉。活性不用来形容物体的轻重，石头搬不动要说重量。"}, {"text": "这辆车的活性很快，半小时就到了。", "explanation": "这里应该用〈速度〉。活性不用来说车的行驶快慢，说车跑得快要用速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23090, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "活性", "is_correct": true, "explanation": "活性：指市场能不断产生新变化的能力，“变强”说的正是它。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：“变强”不用来形容寿命，寿命一般说长短。"}, {"text": "长度", "is_correct": false, "explanation": "搭配：长度说长短，不说“变强”，句子不通。"}, {"text": "字数", "is_correct": false, "explanation": "语义：“字数”只说多少，不说强弱，“变强”说不通。"}], "explanations": {"活性": "活性：指市场能不断产生新变化的能力，“变强”说的正是它。", "寿命": "搭配：“变强”不用来形容寿命，寿命一般说长短。", "长度": "搭配：长度说长短，不说“变强”，句子不通。", "字数": "语义：“字数”只说多少，不说强弱，“变强”说不通。"}, "sentence_index": 6, "correct_answer": "活性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个箱子的活性很大，放在车里正好。", "explanation": "这里应该用〈体积〉。活性不用来说箱子的大小，说箱子大小要用体积。"}, {"text": "这条绳子的活性很长，能绕好几圈。", "explanation": "这里应该用〈长度〉。活性不用来形容绳子的长短，说绳子长短要用长度。"}, {"text": "这座山的活性很高，要爬一整天。", "explanation": "这里应该用〈高度〉。活性指事物能产生变化的能力，不用来说山的高低；说山的高低要用高度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23090, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家小店有一只新的活性，客人总是很多。", "corrected_sentence": "这家小店有一种新的活性，客人总是很多。", "error_description": "量词错误：“活性”是抽象名词，量词应用“种”，“只”只用于动物等具体事物，不能说“一只活性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23090, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个行业有一只新的活性，年轻人都愿意来。", "corrected_sentence": "这个行业有一股新的活性，年轻人都愿意来。", "error_description": "量词错误：“活性”是抽象名词，量词应用“股”或“种”，“只”只用于动物等具体事物，不能说“一只活性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63017762-d4c3-4a05-8ade-f11114f105dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
