INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23094, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23094, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "氧是一种没有颜色、没有味道的气体，人能呼吸，火也离不开它。", "primary_collocate": null, "pronunciation": "yǎng", "ipa": "jɑŋ˨˩˦", "syllable_count": 1, "sentences": [{"text": "氧没有颜色，也没有味道。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人没有氧就不能呼吸。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "火也需要氧才能烧。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气里有氧。", "target_word": "氧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "树和草会放出氧。", "target_word": "氧", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爬山的时候，人会呼吸得更快，把氧吸进身体。", "target_word": "氧", "complexity_tier": "T3", "furigana": "pá shān de shíhou, rén huì hūxī de gèng kuài, bǎ yǎng xī jìn shēntǐ", "sentence_source": "generated"}, {"text": "水里有氧，鱼才能活。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医院里的病人有时要吸氧。", "target_word": "氧", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人每天都要呼吸，呼吸离不开氧。", "target_word": "氧", "complexity_tier": "T3", "furigana": "rén měi tiān dōu yào hūxī, hūxī lí bu kāi yǎng", "sentence_source": "generated"}, {"text": "老师说，氧和氢结合在一起能生成水。", "target_word": "氧", "complexity_tier": "T3", "furigana": "lǎoshī shuō, yǎng hé qīng jiéhé zài yìqǐ néng shēngchéng shuǐ", "sentence_source": "generated"}], "morphological_forms": [{"form": "氧气", "label": "复合词"}, {"form": "缺氧", "label": "复合词"}, {"form": "液氧", "label": "复合词"}], "register": "科技", "sense_fingerprint": "无色无味、人呼吸和火燃烧都需要的气体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0d47bea1-7ac4-4021-b5ba-f873b2971d0e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23094, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "氧", "is_correct": true, "explanation": "氧读 yǎng（第三声），是本题的正确词，指无色无味的气体。"}, {"text": "羊", "is_correct": false, "explanation": "「yǎng（第三声）与 yáng（第二声）声调不同，意思是羊」。"}, {"text": "样", "is_correct": false, "explanation": "「yǎng（第三声）与 yàng（第四声）声调不同，意思是样子、样品」。"}, {"text": "眼", "is_correct": false, "explanation": "「ng 与 n 韵尾不同，yǎn 意思是眼睛」。"}, {"text": "阳", "is_correct": false, "explanation": "「声调不同，yáng 意思是太阳、阳光」。"}], "explanations": {"氧": "氧读 yǎng（第三声），是本题的正确词，指无色无味的气体。", "羊": "「yǎng（第三声）与 yáng（第二声）声调不同，意思是羊」。", "样": "「yǎng（第三声）与 yàng（第四声）声调不同，意思是样子、样品」。", "眼": "「ng 与 n 韵尾不同，yǎn 意思是眼睛」。", "阳": "「声调不同，yáng 意思是太阳、阳光」。"}, "sentence_index": null, "correct_answer": "氧"}, "level_3": {"options": [{"text": "氧", "is_correct": true, "explanation": "正确：氧是无色、无味的气体。"}, {"text": "氯", "is_correct": false, "explanation": "语义：氯气是黄绿色、有刺激性气味的气体，与句中“没有颜色，也没有味道”相反。"}, {"text": "硫", "is_correct": false, "explanation": "体貌：硫是黄色固体，外观与“没有颜色”不符。"}, {"text": "醋", "is_correct": false, "explanation": "语义：醋有酸味，与句中“没有味道”相反。"}], "explanations": {"氧": "正确：氧是无色、无味的气体。", "氯": "语义：氯气是黄绿色、有刺激性气味的气体，与句中“没有颜色，也没有味道”相反。", "硫": "体貌：硫是黄色固体，外观与“没有颜色”不符。", "醋": "语义：醋有酸味，与句中“没有味道”相反。"}, "sentence_index": 0, "correct_answer": "氧"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "有人想用氧代替汽油做燃料。", "explanation": "这里应该用〈氢〉。氢能燃烧，是常用的燃料；氧只能助燃，不能代替汽油作燃料。"}, {"text": "这杯氧很好喝。", "explanation": "这里应该用〈水〉。氧是气体，没有味道，也不能用杯子装着喝。"}, {"text": "妈妈把氧切成了几片，放进汤里。", "explanation": "这里应该用〈萝卜〉。氧是气体，不能切片，也不能放进汤里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23094, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "氧", "is_correct": true, "explanation": "氧读 yǎng（第三声），是本题的正确词，指无色无味的气体。"}, {"text": "秧", "is_correct": false, "explanation": "「yǎng（第三声）与 yāng（第一声）声调不同，意思是稻秧」。"}, {"text": "央", "is_correct": false, "explanation": "「声调不同，yāng 意思是中央」。"}, {"text": "洋", "is_correct": false, "explanation": "「yǎng（第三声）与 yáng（第二声）声调不同，意思是海洋」。"}, {"text": "杨", "is_correct": false, "explanation": "「声调不同，yáng 意思是杨树」。"}], "explanations": {"氧": "氧读 yǎng（第三声），是本题的正确词，指无色无味的气体。", "秧": "「yǎng（第三声）与 yāng（第一声）声调不同，意思是稻秧」。", "央": "「声调不同，yāng 意思是中央」。", "洋": "「yǎng（第三声）与 yáng（第二声）声调不同，意思是海洋」。", "杨": "「声调不同，yáng 意思是杨树」。"}, "sentence_index": null, "correct_answer": "氧"}, "level_3": {"options": [{"text": "氧", "is_correct": true, "explanation": "正确：鱼要靠水里的氧呼吸才能活。"}, {"text": "毒", "is_correct": false, "explanation": "语义：水里有毒，鱼就会死，与“鱼才能活”相矛盾。"}, {"text": "酒精", "is_correct": false, "explanation": "语义：酒精会杀死鱼，与“鱼才能活”相矛盾。"}, {"text": "油", "is_correct": false, "explanation": "搭配：“水里有油”指浮在水面的油污，不是鱼需要的物质，说“水里有油，鱼才能活”不成立。"}], "explanations": {"氧": "正确：鱼要靠水里的氧呼吸才能活。", "毒": "语义：水里有毒，鱼就会死，与“鱼才能活”相矛盾。", "酒精": "语义：酒精会杀死鱼，与“鱼才能活”相矛盾。", "油": "搭配：“水里有油”指浮在水面的油污，不是鱼需要的物质，说“水里有油，鱼才能活”不成立。"}, "sentence_index": 6, "correct_answer": "氧"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用氧炒了一盘青菜。", "explanation": "这里应该用〈油〉。氧是气体，不能用来炒菜，炒菜要用油。"}, {"text": "他每天早上都要吃一碗氧。", "explanation": "这里应该用〈粥〉。氧是气体，不能吃，“一碗”装的应是粥之类的食物。"}, {"text": "老师用氧在黑板上写了一个字。", "explanation": "这里应该用〈粉笔〉。氧是气体，不能用来写字，写字要用粉笔。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23094, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生给病人氧供。", "corrected_sentence": "医生给病人供氧。", "error_description": "错误：“氧供”。正确：“供氧”。“供氧”是动宾结构，氧要放在“供”之后，不能前置。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23094, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "水草在阳光下会放氧出。", "corrected_sentence": "水草在阳光下会放出氧。", "error_description": "错误：“放氧出”。正确：“放出氧”。补语“出”应紧跟动词“放”，不能放在宾语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '86edcbdb-0d29-4288-92c4-00ef3e326339') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
