INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23096, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西关起来放好，以后再用。", "primary_collocate": null, "pronunciation": "fēng cún", "ipa": "fəŋ˥ tsʰwən˧˥", "syllable_count": 2, "sentences": [{"text": "夏天到了，妈妈把厚被子封存起来。", "target_word": "封存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双新鞋我先封存在盒子里，等冬天再穿。", "target_word": "封存", "complexity_tier": "T3", "furigana": "这双新鞋我先封[fēng]存[cún]在盒子里，等冬天再穿。", "sentence_source": "generated"}, {"text": "他把小时候的玩具封存在箱子里。", "target_word": "封存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些老照片我都封存在相册里，以后再看。", "target_word": "封存", "complexity_tier": "T3", "furigana": "这些老照片我都封[fēng]存[cún]在相册里，以后再看。", "sentence_source": "generated"}, {"text": "这些旧书先封存起来，搬家后再用。", "target_word": "封存", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "奶奶把过年用的大红灯笼封存在柜子里，明年再挂。", "target_word": "封存", "complexity_tier": "T3", "furigana": "奶奶把过年用的大红灯笼封[fēng]存[cún]在柜子里，明年再挂。", "sentence_source": "generated"}, {"text": "冬天的衣服要洗干净再封存，明年还能穿。", "target_word": "封存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把这瓶酒封存到明年再喝。", "target_word": "封存", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸把那台旧缝纫机封存在阁楼里，以后再用。", "target_word": "封存", "complexity_tier": "T3", "furigana": "爸爸把那台旧缝纫机封[fēng]存[cún]在阁楼里，以后再用。", "sentence_source": "generated"}, {"text": "这套瓷器我先封存在柜子里，客人来了再用。", "target_word": "封存", "complexity_tier": "T3", "furigana": "这套瓷器我先封[fēng]存[cún]在柜子里，客人来了再用。", "sentence_source": "generated"}], "morphological_forms": [{"form": "封存了", "label": "完成体（了）"}, {"form": "封存过", "label": "经历体（过）"}, {"form": "封存着", "label": "持续体（着）"}], "register": "中性", "sense_fingerprint": "把东西收起来放好，留待以后再用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6771e508-33d8-4986-99ed-fd591f44ae84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23096, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "封存", "is_correct": true, "explanation": "封存：把东西收起来放好，留待以后再用，与“把厚被子收起来”的语境一致。"}, {"text": "排放", "is_correct": false, "explanation": "语义：“排放”指向外排出，与把被子收好留待以后使用的意思相反。"}, {"text": "燃烧", "is_correct": false, "explanation": "语义：“燃烧”会把东西烧掉，与“夏天到了，把厚被子收起来”的语境不合。"}, {"text": "晾晒", "is_correct": false, "explanation": "语义：“晾晒”是在外面晒干，不是收起来放好，与“收起来”的语境不符。"}], "explanations": {"封存": "封存：把东西收起来放好，留待以后再用，与“把厚被子收起来”的语境一致。", "排放": "语义：“排放”指向外排出，与把被子收好留待以后使用的意思相反。", "燃烧": "语义：“燃烧”会把东西烧掉，与“夏天到了，把厚被子收起来”的语境不合。", "晾晒": "语义：“晾晒”是在外面晒干，不是收起来放好，与“收起来”的语境不符。"}, "sentence_index": 0, "correct_answer": "封存"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些老照片我都封存在相册里，每天拿出来看。", "explanation": "这里应该用〈收藏〉。封存是收起来暂不使用，老照片每天要拿出来看，应说“收藏”，不能用封存。"}, {"text": "他把小时候的小猫封存在箱子里。", "explanation": "这里应该用〈关〉。封存指把物品收起来放好，把活的小猫关进箱子应说“关”，封存不能用于活的动物。"}, {"text": "这顿饭我已经封存了，等会儿就吃掉。", "explanation": "这里应该用〈享用〉。封存是收起来暂不使用，饭马上要吃，表示食用应说“享用”，不能用封存。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23096, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "丢弃", "is_correct": false, "explanation": "语义：“丢弃”是扔掉，与“明年还能穿”矛盾。"}, {"text": "拆开", "is_correct": false, "explanation": "语义：“拆开”是打开，与“洗干净再收起来”的语境不合。"}, {"text": "封存", "is_correct": true, "explanation": "封存：收起来放好，留待明年再穿，与“明年还能穿”的语境一致。"}, {"text": "撕破", "is_correct": false, "explanation": "语义：“撕破”会损坏衣服，与“明年还能穿”矛盾。"}], "explanations": {"丢弃": "语义：“丢弃”是扔掉，与“明年还能穿”矛盾。", "拆开": "语义：“拆开”是打开，与“洗干净再收起来”的语境不合。", "封存": "封存：收起来放好，留待明年再穿，与“明年还能穿”的语境一致。", "撕破": "语义：“撕破”会损坏衣服，与“明年还能穿”矛盾。"}, "sentence_index": 6, "correct_answer": "封存"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民给花封存了一次水。", "explanation": "这里应该用〈浇〉。封存是把东西收起来放好，不能用于给花浇水。"}, {"text": "妈妈给我封存了一个拥抱。", "explanation": "这里应该用〈送〉。封存是把物品收起来放好，拥抱是动作，不能封存，表示给予应说“送”。"}, {"text": "他对我封存了一句话，我没听清。", "explanation": "这里应该用〈说〉。封存是收起来放好，不能用于说话。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23096, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我先把这件冬衣封存了在柜子里，明年再穿。", "corrected_sentence": "我先把这件冬衣封存在柜子里，明年再穿。", "error_description": "“了”位置错误：“了”不能插在“封存”和“在柜子里”之间。这里不需要“了”，正确说法是“我先把这件冬衣封存在柜子里，明年再穿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23096, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把这些旧书把封存在箱子里，搬家后再用。", "corrected_sentence": "我把这些旧书封存在箱子里，搬家后再用。", "error_description": "“把”字重复：把字句只用一个“把”，“把这些旧书”后面不能再加“把”。正确说法是“我把这些旧书封存在箱子里，搬家后再用”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
