INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23102, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "基质是东西下面或里面用来支撑或生长的基础材料。", "primary_collocate": null, "pronunciation": "jī zhì", "ipa": "tɕi˥ ʈʂʅ˥˩", "syllable_count": 2, "sentences": [{"text": "花盆里的基质要经常换。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "蘑菇长在木屑基质上。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种基质透气性好，植物根系不容易烂掉。", "target_word": "基质", "complexity_tier": "T3", "furigana": "jī zhì", "sentence_source": "generated"}, {"text": "我在网上买了一包花卉基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的基质能让种子很快发芽。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这盆水培植物用小石子当基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把种子放进湿的基质里，盖好盖子。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "基质下面有一层小石头，可以排水。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么配好基质。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在基质里种下了豆子。", "target_word": "基质", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "花卉基质", "label": "复合"}, {"form": "栽培基质", "label": "复合"}, {"form": "包", "label": "量词"}, {"form": "基質", "label": "繁体"}], "register": "书面", "sense_fingerprint": "放在下面或里面、支撑并供其生长的基础材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9de9a87f-9352-48aa-a1f5-bcc350764b12') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23102, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。基质指放在花盆或容器里、支撑植物生长的基础材料。"}, {"text": "极致", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是达到的最高程度。"}, {"text": "几只", "is_correct": false, "explanation": "jǐ zhī（第三声、第一声）与 jī zhì 声调不同，意思是几只（动物）。"}, {"text": "寄至", "is_correct": false, "explanation": "jì（第四声）与 jī（第一声）声调不同，意思是寄送到某处。"}], "explanations": {"基质": "正确。基质指放在花盆或容器里、支撑植物生长的基础材料。", "极致": "jí（第二声）与 jī（第一声）声调不同，意思是达到的最高程度。", "几只": "jǐ zhī（第三声、第一声）与 jī zhì 声调不同，意思是几只（动物）。", "寄至": "jì（第四声）与 jī（第一声）声调不同，意思是寄送到某处。"}, "sentence_index": null, "correct_answer": "基质"}, "level_3": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。花盆里要经常换的是种植用的基础材料。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：花盆里不放玩具，“花盆里的玩具”句意不通。"}, {"text": "课本", "is_correct": false, "explanation": "语义：花盆里不放课本，“课本要经常换”与花盆无关。"}, {"text": "镜子", "is_correct": false, "explanation": "搭配：“花盆里的镜子”不是常见说法，镜子也不需要像基质那样经常更换。"}], "explanations": {"基质": "正确。花盆里要经常换的是种植用的基础材料。", "玩具": "语义：花盆里不放玩具，“花盆里的玩具”句意不通。", "课本": "语义：花盆里不放课本，“课本要经常换”与花盆无关。", "镜子": "搭配：“花盆里的镜子”不是常见说法，镜子也不需要像基质那样经常更换。"}, "sentence_index": 0, "correct_answer": "基质"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用基质给手机充电。", "explanation": "这里应该用〈电池〉。基质指东西下面或里面用来支撑或生长的材料，不能充电。"}, {"text": "我们学了一个小时的基质。", "explanation": "这里应该用〈课〉。基质指支撑或生长的基础材料，不指学习的内容。"}, {"text": "妈妈用基质煮了一锅汤。", "explanation": "这里应该用〈食材〉。基质是种植用的材料，不能用来煮汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23102, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。基质指放在花盆或容器里、支撑植物生长的基础材料。"}, {"text": "资质", "is_correct": false, "explanation": "zī（第一声）与 jī 声母不同（z 与 j），意思是资格和能力。"}, {"text": "精致", "is_correct": false, "explanation": "jīng 比 jī 多一个韵尾 -ng，意思是精巧细致。"}, {"text": "鸡只", "is_correct": false, "explanation": "zhī（第一声）与 zhì（第四声）声调不同，意思是鸡的数量。"}], "explanations": {"基质": "正确。基质指放在花盆或容器里、支撑植物生长的基础材料。", "资质": "zī（第一声）与 jī 声母不同（z 与 j），意思是资格和能力。", "精致": "jīng 比 jī 多一个韵尾 -ng，意思是精巧细致。", "鸡只": "zhī（第一声）与 zhì（第四声）声调不同，意思是鸡的数量。"}, "sentence_index": null, "correct_answer": "基质"}, "level_3": {"options": [{"text": "基质", "is_correct": true, "explanation": "正确。此处指播种时用来盛放种子的湿润基础材料，与“放进……里”相符。"}, {"text": "歌词", "is_correct": false, "explanation": "语义：种子不能放进歌词里，句意不通。"}, {"text": "故事", "is_correct": false, "explanation": "语义：种子不能放进故事里，句子不成立。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：钥匙不能用来盛放种子，句意不通。"}], "explanations": {"基质": "正确。此处指播种时用来盛放种子的湿润基础材料，与“放进……里”相符。", "歌词": "语义：种子不能放进歌词里，句意不通。", "故事": "语义：种子不能放进故事里，句子不成立。", "钥匙": "语义：钥匙不能用来盛放种子，句意不通。"}, "sentence_index": 6, "correct_answer": "基质"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子们用基质拍了一张照片。", "explanation": "这里应该用〈相机〉。基质是支撑或生长的基础材料，不能用来拍照。"}, {"text": "这盆豆子每天要喝一杯基质。", "explanation": "这里应该用〈营养液〉。基质是固体种植材料，不能用来饮用。"}, {"text": "孩子们用基质洗了手。", "explanation": "这里应该用〈洗手液〉。基质是种植材料，不用来清洁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23102, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了一只基质。", "corrected_sentence": "我买了一包基质。", "error_description": "量词错误：“基质”应搭配量词“包”或“种”，不能用“只”（“只”多用于动物）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23102, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这盆花的基质们很透气。", "corrected_sentence": "这盆花的基质很透气。", "error_description": "“们”不能加在物质名词“基质”后表示复数，句中应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44183ad9-646a-425b-b406-d8fcc4e41ba8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
