INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23104, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得又软又烂，可以当肥料。", "primary_collocate": null, "pronunciation": "fǔ shú", "ipa": "fu˨˩˦ ʂu˧˥", "syllable_count": 2, "sentences": [{"text": "菜叶放久了会慢慢腐熟。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腐熟的肥料闻起来不太臭。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把落叶堆好，让它腐熟。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天热，垃圾腐熟得快。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说这堆肥还没腐熟。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "腐熟以后，这些草就能当肥料了。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用桶装厨余，让它在家里腐熟。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，树叶腐熟要等很久。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "肥料没腐熟，不能放在花根旁边。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了三个月，这堆草已经腐熟了。", "target_word": "腐熟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "腐熟了", "label": "体标"}, {"form": "腐熟过", "label": "体标"}], "register": "中性", "sense_fingerprint": "东西变软变烂、可以当肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23104, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "复述", "is_correct": false, "explanation": "fù（第四声）与 fǔ（第三声）声调不同，shù（第四声）与 shú（第二声）声调不同，意思是复述，即把话再说一遍。"}, {"text": "腐熟", "is_correct": true, "explanation": "正确答案。腐熟指东西慢慢变得又软又烂，可以当肥料。"}, {"text": "腐蚀", "is_correct": false, "explanation": "shí（第二声）与 shú（第二声）韵母不同，意思是腐蚀，指物质被侵蚀损坏。"}, {"text": "服输", "is_correct": false, "explanation": "fú（第二声）与 fǔ（第三声）、shū（第一声）与 shú（第二声）声调不同，意思是认输。"}], "explanations": {"复述": "fù（第四声）与 fǔ（第三声）声调不同，shù（第四声）与 shú（第二声）声调不同，意思是复述，即把话再说一遍。", "腐熟": "正确答案。腐熟指东西慢慢变得又软又烂，可以当肥料。", "腐蚀": "shí（第二声）与 shú（第二声）韵母不同，意思是腐蚀，指物质被侵蚀损坏。", "服输": "fú（第二声）与 fǔ（第三声）、shū（第一声）与 shú（第二声）声调不同，意思是认输。"}, "sentence_index": null, "correct_answer": "腐熟"}, "level_3": {"options": [{"text": "腐熟", "is_correct": true, "explanation": "正确：腐熟指东西慢慢变软变烂，与「放久了会慢慢」的变化相符。"}, {"text": "切碎", "is_correct": false, "explanation": "语义：切碎要靠人用刀完成，与「放久了会慢慢」的自然变化相反。"}, {"text": "烧熟", "is_correct": false, "explanation": "语义：烧熟需要加热，句中没有加热的条件，与「放久了」不合。"}, {"text": "煮沸", "is_correct": false, "explanation": "搭配：煮沸多用于水或汤，不能用来描述菜叶慢慢变化。"}], "explanations": {"腐熟": "正确：腐熟指东西慢慢变软变烂，与「放久了会慢慢」的变化相符。", "切碎": "语义：切碎要靠人用刀完成，与「放久了会慢慢」的自然变化相反。", "烧熟": "语义：烧熟需要加热，句中没有加热的条件，与「放久了」不合。", "煮沸": "搭配：煮沸多用于水或汤，不能用来描述菜叶慢慢变化。"}, "sentence_index": 0, "correct_answer": "腐熟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面粉要先腐熟，再做成馒头。", "explanation": "这里应该用〈发酵〉。面粉变松要说发酵，腐熟指东西变软变烂、可当肥料。"}, {"text": "这把铁锤埋在土里，慢慢腐熟了。", "explanation": "腐熟只用于有机物，铁锤是金属，埋在土里只会生锈，不会腐熟。"}, {"text": "饼干放进烤箱，腐熟了二十分钟。", "explanation": "这里应该用〈烤〉。腐熟是东西慢慢变软烂的过程，靠加热处理要说烤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23104, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "腐熟", "is_correct": true, "explanation": "正确答案。腐熟指东西慢慢变得又软又烂，可以当肥料。"}, {"text": "复数", "is_correct": false, "explanation": "fù（第四声）与 fǔ（第三声）声调不同，shù（第四声）与 shú（第二声）声调不同，意思是数学或语法中的概念。"}, {"text": "服输", "is_correct": false, "explanation": "fú（第二声）与 fǔ（第三声）、shū（第一声）与 shú（第二声）声调不同，意思是认输。"}, {"text": "附属", "is_correct": false, "explanation": "fù（第四声）与 fǔ（第三声）、shǔ（第三声）与 shú（第二声）声调不同，意思是从属于某一方。"}], "explanations": {"腐熟": "正确答案。腐熟指东西慢慢变得又软又烂，可以当肥料。", "复数": "fù（第四声）与 fǔ（第三声）声调不同，shù（第四声）与 shú（第二声）声调不同，意思是数学或语法中的概念。", "服输": "fú（第二声）与 fǔ（第三声）、shū（第一声）与 shú（第二声）声调不同，意思是认输。", "附属": "fù（第四声）与 fǔ（第三声）、shǔ（第三声）与 shú（第二声）声调不同，意思是从属于某一方。"}, "sentence_index": null, "correct_answer": "腐熟"}, "level_3": {"options": [{"text": "腐熟", "is_correct": true, "explanation": "正确：腐熟指厨余在家里慢慢变软烂，可用作肥料，与句意相符。"}, {"text": "出售", "is_correct": false, "explanation": "语义：出售要有买卖对象，与「让它在家里」的做法不符，句意不通。"}, {"text": "煎炸", "is_correct": false, "explanation": "搭配：煎炸用于做菜、需要热油，不能用来形容厨余慢慢变化。"}, {"text": "出口", "is_correct": false, "explanation": "配价：「出口」的宾语应指货物，厨余不能以「它」的身份出口，句子不通。"}], "explanations": {"腐熟": "正确：腐熟指厨余在家里慢慢变软烂，可用作肥料，与句意相符。", "出售": "语义：出售要有买卖对象，与「让它在家里」的做法不符，句意不通。", "煎炸": "搭配：煎炸用于做菜、需要热油，不能用来形容厨余慢慢变化。", "出口": "配价：「出口」的宾语应指货物，厨余不能以「它」的身份出口，句子不通。"}, "sentence_index": 6, "correct_answer": "腐熟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这面墙在潮湿的地方放了三年，已经腐熟了。", "explanation": "这里应该用〈风化〉。墙是无机物，受风雨侵蚀变松散要说风化，腐熟指东西变软烂、可当肥料。"}, {"text": "他在地里待了一天，身体慢慢腐熟了。", "explanation": "这里应该用〈虚弱〉。腐熟指东西变软烂、可当肥料，人的身体变得无力要说虚弱。"}, {"text": "把湿衣服放在火上，很快就腐熟了。", "explanation": "这里应该用〈烘干〉。衣服变干要说烘干，腐熟指东西变软烂、可当肥料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23104, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这堆肥已经腐熟着，可以用了。", "corrected_sentence": "这堆肥已经腐熟了，可以用了。", "error_description": "错误形式：腐熟着；正确形式：腐熟了。「已经」后面表示动作完成，应用「了」，不用「着」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23104, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这堆枯枝没还腐熟，不能直接施用。", "corrected_sentence": "这堆枯枝还没腐熟，不能直接施用。", "error_description": "错误形式：没还腐熟；正确形式：还没腐熟。副词「还」应放在否定副词「没」前面，表示尚未完成。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
