INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23106, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "产物就是做一件事后得到的东西。", "primary_collocate": null, "pronunciation": "chǎn wù", "ipa": "tʂʰan˨˩˦ u˥˩", "syllable_count": 2, "sentences": [{"text": "发酵的产物是酒。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个化学反应的产物是水和盐。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做豆腐的产物之一是豆渣。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们写出这个实验的产物。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "燃烧木头的产物有灰和烟。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把实验的产物放进了瓶子里。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "光合作用的产物是氧气和糖。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "炼油的产物有汽油和柴油。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验有两种产物，一种是气体。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "煤燃烧后的产物会污染空气。", "target_word": "产物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "副产物", "label": "复合"}, {"form": "產物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "反应、加工等过程后得到的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4e92c63b-3679-442a-a17d-628878172573') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23106, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "产物", "is_correct": true, "explanation": "产物：发酵过程得到的东西，此处指酒，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”不是发酵得到的东西，“发酵的颜色是酒”说不通。"}, {"text": "工具", "is_correct": false, "explanation": "搭配：“发酵”的结果是产物，不说“发酵的工具”。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不是发酵得到的东西，“发酵的桌子是酒”说不通。"}], "explanations": {"产物": "产物：发酵过程得到的东西，此处指酒，与句意相符。", "颜色": "语义：“颜色”不是发酵得到的东西，“发酵的颜色是酒”说不通。", "工具": "搭配：“发酵”的结果是产物，不说“发酵的工具”。", "桌子": "语义：桌子不是发酵得到的东西，“发酵的桌子是酒”说不通。"}, "sentence_index": 0, "correct_answer": "产物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次实验让我有很大产物。", "explanation": "这里应该用〈收获〉。“产物”指做完一件事后得到的东西，个人在实验中学到的东西要说〈收获〉。"}, {"text": "老师让我们准备这个实验的产物。", "explanation": "这里应该用〈材料〉。“产物”是做完一件事后得到的东西，准备实验时用的东西要说〈材料〉。"}, {"text": "这个实验只得到了一把产物。", "explanation": "这里应该用〈种〉。“产物”前的量词用“种”，“把”用于有柄的器具，不能用来数产物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23106, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "产物", "is_correct": true, "explanation": "产物：光合作用生成的东西，此处是氧气和糖，与句意相符。"}, {"text": "原料", "is_correct": false, "explanation": "语义：光合作用的原料是二氧化碳和水等投入物，氧气和糖不是原料。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是光合作用生成的东西，“光合作用的颜色是氧气和糖”说不通。"}, {"text": "设备", "is_correct": false, "explanation": "搭配：“光合作用”的结果不是设备，“光合作用的设备是氧气和糖”搭配不当。"}], "explanations": {"产物": "产物：光合作用生成的东西，此处是氧气和糖，与句意相符。", "原料": "语义：光合作用的原料是二氧化碳和水等投入物，氧气和糖不是原料。", "颜色": "语义：颜色不是光合作用生成的东西，“光合作用的颜色是氧气和糖”说不通。", "设备": "搭配：“光合作用”的结果不是设备，“光合作用的设备是氧气和糖”搭配不当。"}, "sentence_index": 6, "correct_answer": "产物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂每天需要大量产物才能运转。", "explanation": "这里应该用〈原料〉。“产物”是做完一件事后得到的东西，工厂生产前投入的东西要说〈原料〉。"}, {"text": "我们得出了这个实验的产物。", "explanation": "这里应该用〈结论〉。“得出”搭配的是结论，不搭配产物。"}, {"text": "这个实验得到了一条产物。", "explanation": "这里应该用〈种〉。“条”多用于细长的东西，不用于数产物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23106, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次反应只得到了一只产物。", "corrected_sentence": "这次反应只得到了一种产物。", "error_description": "量词错误：“产物”前应用“种”，不用“只”（“只”多用于动物或成对的物件）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23106, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个实验的产物我们已经检查了过。", "corrected_sentence": "这个实验的产物我们已经检查过了。", "error_description": "“了”“过”顺序错误：动词后应说“检查过了”，不能说“检查了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e2358d00-a4f8-463a-ab76-8616ee88e52f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
