INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23108, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "东西放好不会动，或者事情不会变。", "primary_collocate": null, "pronunciation": "wěn dìng", "ipa": "wən˨˩˦ tiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的工作很稳定，收入也不错。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个架子很稳定，不会倒。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近天气不稳定，一会儿晴一会儿雨。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的情绪一直很稳定。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "物价稳定，大家生活得更安心。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子需要一个稳定的家。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的生意越来越稳定了。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的生意很稳定，每天都有老顾客来。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水温要保持稳定，鱼才不会生病。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的关系很稳定，吵架也不多。", "target_word": "稳定", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "稳定性", "label": "复合"}, {"form": "不稳定", "label": "复合"}], "register": "中性", "sense_fingerprint": "稳定：不晃动、不变化，保持平稳", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89604cde-aa36-49a3-b834-19b3606a7411') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23108, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "稳定", "is_correct": true, "explanation": "正确。“很稳定”描述工作状况平稳，与“收入也不错”相符。"}, {"text": "懒惰", "is_correct": false, "explanation": "搭配：“懒惰”形容人的品质，不能用来修饰“工作”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述外形，不用于形容“工作”。"}, {"text": "通红", "is_correct": false, "explanation": "体貌：“通红”描述颜色和外貌，不能用来形容“工作”。"}], "explanations": {"稳定": "正确。“很稳定”描述工作状况平稳，与“收入也不错”相符。", "懒惰": "搭配：“懒惰”形容人的品质，不能用来修饰“工作”。", "高大": "体貌：“高大”描述外形，不用于形容“工作”。", "通红": "体貌：“通红”描述颜色和外貌，不能用来形容“工作”。"}, "sentence_index": 0, "correct_answer": "稳定"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一听到这个消息，他就稳定地跳了起来。", "explanation": "“稳定”指保持不变、平稳，不能用来形容突然跳起来的动作。"}, {"text": "他一紧张，手就稳定了，抖个不停。", "explanation": "“稳定”指平稳不变动，不能用来形容抖个不停的状态。"}, {"text": "这辆车很稳定地撞到了树上。", "explanation": "“稳定”形容平稳的状态，不能用来描述撞车这样的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23108, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "稳定", "is_correct": true, "explanation": "正确。“越来越稳定”描述生意逐渐平稳、有保障，与语境相符。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”描述身高，不能用来形容“生意”的变化。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”多用于排列或样子，不能用来形容“生意”。"}, {"text": "明亮", "is_correct": false, "explanation": "体貌：“明亮”描述光线或外观，不能用来形容“生意”。"}], "explanations": {"稳定": "正确。“越来越稳定”描述生意逐渐平稳、有保障，与语境相符。", "矮": "体貌：“矮”描述身高，不能用来形容“生意”的变化。", "整齐": "搭配：“整齐”多用于排列或样子，不能用来形容“生意”。", "明亮": "体貌：“明亮”描述光线或外观，不能用来形容“生意”。"}, "sentence_index": 6, "correct_answer": "稳定"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们的关系很稳定地一起去了北京。", "explanation": "“稳定”形容状态，不能用来修饰“去”这样的动作。"}, {"text": "他的稳定是一个大学生。", "explanation": "“稳定”指状态或性质，不指人，不能说“他的稳定是……”。"}, {"text": "这块玻璃很稳定地掉了下来。", "explanation": "“稳定”形容平稳不动，不能用来描述玻璃掉落这样的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23108, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座桥很稳定性，车辆可以安全通过。", "corrected_sentence": "这座桥很稳定，车辆可以安全通过。", "error_description": "“稳定性”是名词，不能直接用“很”修饰。这里应该用形容词“稳定”，说“很稳定”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23108, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的情绪一直很稳定化，从不发脾气。", "corrected_sentence": "他的情绪一直很稳定，从不发脾气。", "error_description": "“稳定化”是指使事物变稳定的过程名词，不能用“很”修饰；“稳定”是形容词，应说“很稳定”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe6a8d1c-091f-4a38-8fae-b32d42373c35') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23110, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "降低", "is_correct": true, "explanation": "降低：使水平变低，与「提升」的意思相反，是反义词。"}, {"text": "放松", "is_correct": false, "explanation": "放松：指使紧张或严格的状态缓和，与「提升」的意思没有反义关系。"}, {"text": "讨论", "is_correct": false, "explanation": "讨论：指大家交流意见，与「使变得更好更高」没有反义关系。"}, {"text": "保存", "is_correct": false, "explanation": "保存：指使东西保留下来不受损失，与「提升」没有反义关系。"}], "correct_answer": "降低", "explanations": {"降低": "降低：使水平变低，与「提升」的意思相反，是反义词。", "放松": "放松：指使紧张或严格的状态缓和，与「提升」的意思没有反义关系。", "讨论": "讨论：指大家交流意见，与「使变得更好更高」没有反义关系。", "保存": "保存：指使东西保留下来不受损失，与「提升」没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23110, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "下降", "is_correct": true, "explanation": "下降：指水平由高变低，与「提升」的意思相反，是反义词。"}, {"text": "安排", "is_correct": false, "explanation": "安排：指事先布置，与「提升」没有反义关系。"}, {"text": "收集", "is_correct": false, "explanation": "收集：指把东西聚在一起，与「提升」没有反义关系。"}, {"text": "感谢", "is_correct": false, "explanation": "感谢：指表达谢意，与「提升」没有反义关系。"}], "correct_answer": "下降", "explanations": {"下降": "下降：指水平由高变低，与「提升」的意思相反，是反义词。", "安排": "安排：指事先布置，与「提升」没有反义关系。", "收集": "收集：指把东西聚在一起，与「提升」没有反义关系。", "感谢": "感谢：指表达谢意，与「提升」没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23110, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变得更好或更高。", "primary_collocate": null, "pronunciation": "tí shēng", "ipa": "tʰi˧˥ ʂʌŋ˥", "syllable_count": 2, "sentences": [{"text": "多读书可以提升你的中文水平。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司想提升工作的质量。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天跑步，想提升自己的体力。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个方法提升了我的成绩。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过一年学习，她的能力提升了很多。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店想提升服务质量。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要提升网络的速度。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动能提升身体的健康水平。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新电脑把工作的效率提升了。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想提升自己的画画水平。", "target_word": "提升", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提升了", "label": "体标"}, {"form": "提升过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使水平、质量、能力等变得更好更高", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd0b36993-6be1-4beb-8bc2-c6c37fd0d0a8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23110, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "提升", "is_correct": true, "explanation": "正确答案。提升 tí shēng，意思是使水平、质量等变得更好更高。"}, {"text": "提神", "is_correct": false, "explanation": "shén（第二声）与 shēng（第一声）韵母不同（n 与 ng），意思是使精神振作，不是使水平提高。"}, {"text": "提审", "is_correct": false, "explanation": "shěn（第三声）与 shēng（第一声）韵母与声调都不同，意思是把人提到法庭上审问。"}, {"text": "提成", "is_correct": false, "explanation": "chéng（第二声）与 shēng（第一声）声母不同（ch 与 sh），意思是按比例抽取的报酬。"}, {"text": "提醒", "is_correct": false, "explanation": "xǐng（第三声）与 shēng（第一声）声母不同（x 与 sh），声调也不同，意思是让人注意某事。"}], "explanations": {"提升": "正确答案。提升 tí shēng，意思是使水平、质量等变得更好更高。", "提神": "shén（第二声）与 shēng（第一声）韵母不同（n 与 ng），意思是使精神振作，不是使水平提高。", "提审": "shěn（第三声）与 shēng（第一声）韵母与声调都不同，意思是把人提到法庭上审问。", "提成": "chéng（第二声）与 shēng（第一声）声母不同（ch 与 sh），意思是按比例抽取的报酬。", "提醒": "xǐng（第三声）与 shēng（第一声）声母不同（x 与 sh），声调也不同，意思是让人注意某事。"}, "sentence_index": null, "correct_answer": "提升"}, "level_3": {"options": [{"text": "提升", "is_correct": true, "explanation": "提升：使水平变得更高，与「中文水平」搭配，符合句意。"}, {"text": "降低", "is_correct": false, "explanation": "语义：「降低」是使变低，与「多读书」带来进步的意思相反。"}, {"text": "丢失", "is_correct": false, "explanation": "语义：「丢失」是失去，与「多读书」带来进步的意思相反。"}, {"text": "参观", "is_correct": false, "explanation": "配价：「参观」要带场所或具体对象作宾语，不能带「中文水平」这样的抽象宾语。"}], "explanations": {"提升": "提升：使水平变得更高，与「中文水平」搭配，符合句意。", "降低": "语义：「降低」是使变低，与「多读书」带来进步的意思相反。", "丢失": "语义：「丢失」是失去，与「多读书」带来进步的意思相反。", "参观": "配价：「参观」要带场所或具体对象作宾语，不能带「中文水平」这样的抽象宾语。"}, "sentence_index": 0, "correct_answer": "提升"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的病情提升了，需要住院。", "explanation": "这里应该用〈加重〉。“提升”用于水平、质量等积极的变化，病情变坏要用“加重”。"}, {"text": "这个城市的噪音提升了很多。", "explanation": "这里应该用〈增大〉。“提升”用于水平、质量等积极的变化，噪音变大是负面变化，要用“增大”。"}, {"text": "这个小区的犯罪率提升了许多，晚上越来越不安全。", "explanation": "这里应该用〈上升〉。“提升”用于水平、质量等积极的变化，犯罪率这类负面数值要用“上升”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23110, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "提升", "is_correct": true, "explanation": "提升：使网速变得更快，与「网络的速度」搭配，符合句意。"}, {"text": "品尝", "is_correct": false, "explanation": "语义：「品尝」是用舌头辨别滋味，不能用于网络的速度。"}, {"text": "演唱", "is_correct": false, "explanation": "搭配：「演唱」要搭配歌曲，不能说「演唱网络的速度」。"}, {"text": "游览", "is_correct": false, "explanation": "配价：「游览」要带地点宾语，「网络的速度」不是可以游览的地方。"}], "explanations": {"提升": "提升：使网速变得更快，与「网络的速度」搭配，符合句意。", "品尝": "语义：「品尝」是用舌头辨别滋味，不能用于网络的速度。", "演唱": "搭配：「演唱」要搭配歌曲，不能说「演唱网络的速度」。", "游览": "配价：「游览」要带地点宾语，「网络的速度」不是可以游览的地方。"}, "sentence_index": 6, "correct_answer": "提升"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家画廊想提升展厅之间的距离。", "explanation": "这里应该用〈缩短〉。提升表示变得更好更高，距离的增减要用缩短或拉大，不能说提升。"}, {"text": "老师希望我们提升作业中的错误。", "explanation": "这里应该用〈减少〉。提升表示变得更好更高，错误、问题这类负面的东西要用减少。"}, {"text": "我们要提升两人之间的误会。", "explanation": "这里应该用〈消除〉。提升表示变得更好，误会这类负面的东西要用消除。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23110, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他终于把自己的成绩提升。", "corrected_sentence": "他终于把自己的成绩提升了。", "error_description": "“把”字句中动词后要有“了”或其他成分表示完成，“提升”后应加“了”，说“他终于把自己的成绩提升了”，不能说“他终于把自己的成绩提升”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23110, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个课程让我的口语水平提升在了新的高度。", "corrected_sentence": "这个课程让我的口语水平提升到了新的高度。", "error_description": "错误：结果补语「在」用错了。表示结果到达某个位置或程度要用「到」，应说「提升到了新的高度」，不能说「提升在」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0c70bd67-1f70-4fec-9ce1-5b472ee1565d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
