INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23112, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "土里的小土块粘在一起，像小球一样。", "primary_collocate": null, "pronunciation": "tuán lì jié gòu", "ipa": "tʰwan˧˥ li˥˩ tɕje˧˥ kou˥˩", "syllable_count": 4, "sentences": [{"text": "抓一把土，能看到团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好土里的小球，就是团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花盆里的土有团粒结构，很松软。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土块粘成小球，这就是团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种花前，先看土有没有团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团粒结构像一颗颗小球。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用手一捏，团粒结构就散开了。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿土里的团粒结构更容易看到。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在花园里找到了团粒结构。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种土的团粒结构很明显。", "target_word": "团粒结构", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "土壤团粒结构", "label": "复合"}], "register": "通用", "sense_fingerprint": "团粒结构|名词|小土块粘成小球", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbc18688-d601-46ef-99b3-ee748b978efe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23112, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "声音", "is_correct": false, "explanation": "语义：声音是听到的，不能用眼睛“看到”，与抓土的情境不符。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”通常说“闻到”或“尝到”，不说“看到味道”。"}, {"text": "团粒结构", "is_correct": true, "explanation": "正确：“能看到”后接土中可以看见的团粒结构，即小土块粘成的小球。"}, {"text": "价格", "is_correct": false, "explanation": "语义：抓一把土时土里没有可以看到的价格，“能看到价格”与语境完全不符。"}], "explanations": {"声音": "语义：声音是听到的，不能用眼睛“看到”，与抓土的情境不符。", "味道": "搭配：“味道”通常说“闻到”或“尝到”，不说“看到味道”。", "团粒结构": "正确：“能看到”后接土中可以看见的团粒结构，即小土块粘成的小球。", "价格": "语义：抓一把土时土里没有可以看到的价格，“能看到价格”与语境完全不符。"}, "sentence_index": 0, "correct_answer": "团粒结构"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "团粒结构要揉到光滑才好做馒头。", "explanation": "这里应该用〈面团〉。团粒结构是土壤里粘成小球的土块，不能揉光；能揉光做馒头的是“面团”。"}, {"text": "这块地的团粒结构很硬，要用锄头敲开。", "explanation": "这里应该用〈土块〉。团粒结构是松散易碎的小团粒，形容“硬”要用“土块”。"}, {"text": "河边有很多团粒结构，可以用来铺路。", "explanation": "这里应该用〈石子〉。团粒结构是土壤中的小团粒，不指河边的石子，不能用来铺路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23112, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "皮球", "is_correct": false, "explanation": "语义：皮球被手一捏只会变形，不会“就散开”，这句说的是土的性质。"}, {"text": "铁块", "is_correct": false, "explanation": "语义：铁块很坚硬，用手一捏不会散开，与“就散开了”矛盾。"}, {"text": "人群", "is_correct": false, "explanation": "配价：“捏”要求受事是能被手捏的东西，人群不能被手一捏。"}, {"text": "团粒结构", "is_correct": true, "explanation": "正确：“用手一捏，团粒结构就散开了”说明小团粒结构易碎，手一捏就散。"}], "explanations": {"皮球": "语义：皮球被手一捏只会变形，不会“就散开”，这句说的是土的性质。", "铁块": "语义：铁块很坚硬，用手一捏不会散开，与“就散开了”矛盾。", "人群": "配价：“捏”要求受事是能被手捏的东西，人群不能被手一捏。", "团粒结构": "正确：“用手一捏，团粒结构就散开了”说明小团粒结构易碎，手一捏就散。"}, "sentence_index": 6, "correct_answer": "团粒结构"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这种团粒结构很甜，孩子们都爱吃。", "explanation": "这里应该用〈西瓜〉。团粒结构是土壤里粘成小球的土块，不能吃，也谈不上甜；说甜、爱吃要用“西瓜”这类食物。"}, {"text": "妈妈烤了一些团粒结构，很香。", "explanation": "这里应该用〈饼干〉。团粒结构是土壤里的小土块，不能烤来吃；烤出来很香的应是“饼干”这类食物。"}, {"text": "昨天的团粒结构输了，大家都很难过。", "explanation": "这里应该用〈比赛〉。“输”用于比赛、钱财等有输赢的事，团粒结构不能说输赢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23112, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块地的土里有很多团粒结构们。", "corrected_sentence": "这块地的土里有很多团粒结构。", "error_description": "“团粒结构”是表示物质结构的名词，不能加“们”表示复数，应为“很多团粒结构”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23112, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "雨水多的时候，花园里的土容易失去团粒结构们。", "corrected_sentence": "雨水多的时候，花园里的土容易失去团粒结构。", "error_description": "“团粒结构”指土里小土块粘成的结构状态，是不可数的名词，不能加“们”表示复数，应去掉“们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
