INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23114, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西留水下来，不让水跑掉。", "primary_collocate": null, "pronunciation": "bǎo shuǐ", "ipa": "pɑʊ˨˩˦ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这块海绵很保水，洗碗特别好用。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "沙子不保水，水一倒下去就漏光了。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个花盆底下有洞，不保水。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "黏土保水，所以可以做水池的底。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这块布很保水，盖在苗上不容易干。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "稻田要保水，所以田边要堆高一点。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种陶罐很保水，装满水放一夜，水还是满的。", "target_word": "保水", "complexity_tier": "T3", "furigana": "zhè zhǒng táo guàn hěn bǎo shuǐ, zhuāng mǎn shuǐ fàng yí yè, shuǐ hái shì mǎn de", "sentence_source": "generated"}, {"text": "树根旁边盖上草，土会更保水。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新买的水桶不保水，我只好换一个。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厚土层保水，薄土层不保水。", "target_word": "保水", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "保水性", "label": "复合"}, {"form": "保水剂", "label": "复合"}], "register": "中性", "sense_fingerprint": "物体或容器把水留住、不让水漏掉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbc18688-d601-46ef-99b3-ee748b978efe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23114, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保水", "is_correct": true, "explanation": "正确：保水，指让东西把水留住，不让水跑掉。"}, {"text": "保税", "is_correct": false, "explanation": "保税（bǎo shuì）的 shuì（第四声）与 shuǐ（第三声）声调不同，意思是保税，指货物暂缓纳税。"}, {"text": "报税", "is_correct": false, "explanation": "报税（bào shuì）与保水的两个音节声调都不同，意思是报税，即向税务机关申报纳税。"}, {"text": "跑水", "is_correct": false, "explanation": "跑水（pǎo shuǐ）的 pǎo 与 bǎo 声母不同（p 与 b），意思是水从管道或容器里漏出。"}], "explanations": {"保水": "正确：保水，指让东西把水留住，不让水跑掉。", "保税": "保税（bǎo shuì）的 shuì（第四声）与 shuǐ（第三声）声调不同，意思是保税，指货物暂缓纳税。", "报税": "报税（bào shuì）与保水的两个音节声调都不同，意思是报税，即向税务机关申报纳税。", "跑水": "跑水（pǎo shuǐ）的 pǎo 与 bǎo 声母不同（p 与 b），意思是水从管道或容器里漏出。"}, "sentence_index": null, "correct_answer": "保水"}, "level_3": {"options": [{"text": "发霉", "is_correct": false, "explanation": "语义：海绵发霉会影响使用，与“洗碗特别好用”的说法矛盾。"}, {"text": "怕热", "is_correct": false, "explanation": "搭配：“怕热”多用于人或动物，不用来形容海绵。"}, {"text": "保水", "is_correct": true, "explanation": "正确：“这块海绵很保水”指海绵能把水留在里面，所以洗碗好用。"}, {"text": "漏水", "is_correct": false, "explanation": "语义：“很漏水”与“保水”相反，海绵漏水就不好用了，与“洗碗特别好用”矛盾。"}], "explanations": {"发霉": "语义：海绵发霉会影响使用，与“洗碗特别好用”的说法矛盾。", "怕热": "搭配：“怕热”多用于人或动物，不用来形容海绵。", "保水": "正确：“这块海绵很保水”指海绵能把水留在里面，所以洗碗好用。", "漏水": "语义：“很漏水”与“保水”相反，海绵漏水就不好用了，与“洗碗特别好用”矛盾。"}, "sentence_index": 0, "correct_answer": "保水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件外套很保水，下雨也不湿。", "explanation": "这里应该用〈防水〉。保水指把水留在物体里，防水指挡住外面的水；外套挡雨要用“防水”。"}, {"text": "喝了这杯果汁，我很快就保水了。", "explanation": "这里应该用〈解渴〉。保水指东西留住水、不让水跑掉，不能用来说人喝水后不渴；说喝水后不渴要用“解渴”。"}, {"text": "水管破了，水一直往外保水。", "explanation": "这里应该用〈漏〉。保水指让水留在东西里、不让水跑掉；水从破裂的地方往外流要用“漏”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23114, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "透水", "is_correct": false, "explanation": "语义：「透水」指水能穿过去，与「装满水放一夜，水还是满的」矛盾。"}, {"text": "吸水", "is_correct": false, "explanation": "语义：“吸水”会把水吸进陶罐，水位就会下降，与“水还是满的”矛盾。"}, {"text": "生锈", "is_correct": false, "explanation": "搭配：“生锈”多用于金属，与陶罐不搭配。"}, {"text": "保水", "is_correct": true, "explanation": "正确：“这种陶罐很保水”指陶罐能把水留住，所以装满水放一夜水还是满的。"}], "explanations": {"透水": "语义：「透水」指水能穿过去，与「装满水放一夜，水还是满的」矛盾。", "吸水": "语义：“吸水”会把水吸进陶罐，水位就会下降，与“水还是满的”矛盾。", "生锈": "搭配：“生锈”多用于金属，与陶罐不搭配。", "保水": "正确：“这种陶罐很保水”指陶罐能把水留住，所以装满水放一夜水还是满的。"}, "sentence_index": 6, "correct_answer": "保水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑很保水，用起来很快。", "explanation": "这里应该用〈耐用〉。保水指物体留住水分，不能用来形容电脑的性能；说电脑经久耐用要用“耐用”。"}, {"text": "这本书很保水，我每天都读它。", "explanation": "这里应该用〈耐读〉。保水指物体留住水分，不能用来形容书的内容；说书值得反复读要用“耐读”。"}, {"text": "我的小狗很保水，每天都想出去玩。", "explanation": "这里应该用〈活泼〉。保水指留住水分，不能用来形容动物的性格；说小狗精力旺盛要用“活泼”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23114, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个盆不保水，装满水一夜还是满的。", "corrected_sentence": "这个盆很保水，装满水一夜还是满的。", "error_description": "“很”误作“不”。“不保水”表示不能留水，与后文“装满水一夜还是满的”矛盾，应为“很保水”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23114, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个竹篮保水过，效果很好。", "corrected_sentence": "这个竹篮保过水，效果很好。", "error_description": "“过”的位置错误：应紧跟动词，即“保过水”；“保水过”把“过”放在了整个词之后，不符合语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
