INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23118, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指好的方向或态度。", "primary_collocate": null, "pronunciation": "zhèng xiàng", "ipa": "ʈʂəŋ˥˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她总是用正向的态度面对困难。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题时，要正向思考。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的想法很正向，大家都喜欢他。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈教我用正向的眼光看世界。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保持正向的心态，生活会更好。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书讲怎样正向地面对失败。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友的话让我变得更正向了。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师希望大家多说正向的话。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是一个很正向的人，从不抱怨。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到事情正向的一面，心情就好了。", "target_word": "正向", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "正向思考", "label": "复合"}, {"form": "正向能量", "label": "复合"}], "register": "中性", "sense_fingerprint": "正向：好的、积极的方向或态度，如正向思考、很正向的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6771e508-33d8-4986-99ed-fd591f44ae84') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23118, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "正向", "is_correct": true, "explanation": "正向 zhèng xiàng 指好的、积极的方向或态度，是正确答案。"}, {"text": "成像", "is_correct": false, "explanation": "成像 chéng xiàng 与 zhèng xiàng 声母 zh 与 ch 不同，意思是形成影像。"}, {"text": "正弦", "is_correct": false, "explanation": "正弦 zhèng xián 与 zhèng xiàng 韵母 ang 与 an 不同，是数学术语，意思是正弦函数。"}, {"text": "正线", "is_correct": false, "explanation": "正线 zhèng xiàn 与 zhèng xiàng 韵母 ang 与 an 不同，意思是主要的线路。"}, {"text": "真香", "is_correct": false, "explanation": "真香 zhēn xiāng 第一个音节韵母 en 与 eng 不同，第二个音节声调也不同，意思是很香。"}], "explanations": {"正向": "正向 zhèng xiàng 指好的、积极的方向或态度，是正确答案。", "成像": "成像 chéng xiàng 与 zhèng xiàng 声母 zh 与 ch 不同，意思是形成影像。", "正弦": "正弦 zhèng xián 与 zhèng xiàng 韵母 ang 与 an 不同，是数学术语，意思是正弦函数。", "正线": "正线 zhèng xiàn 与 zhèng xiàng 韵母 ang 与 an 不同，意思是主要的线路。", "真香": "真香 zhēn xiāng 第一个音节韵母 en 与 eng 不同，第二个音节声调也不同，意思是很香。"}, "sentence_index": null, "correct_answer": "正向"}, "level_3": {"options": [{"text": "正向", "is_correct": true, "explanation": "正向指积极的态度，与“她总是用……的态度面对困难”的语境一致。"}, {"text": "红色", "is_correct": false, "explanation": "搭配：“红色”指颜色，不能用来修饰“态度”。"}, {"text": "高大", "is_correct": false, "explanation": "搭配：“高大”形容体形，不用来修饰“态度”。"}, {"text": "高速", "is_correct": false, "explanation": "语义：“高速”形容速度快，不能修饰“态度”，句意不通。"}], "explanations": {"正向": "正向指积极的态度，与“她总是用……的态度面对困难”的语境一致。", "红色": "搭配：“红色”指颜色，不能用来修饰“态度”。", "高大": "搭配：“高大”形容体形，不用来修饰“态度”。", "高速": "语义：“高速”形容速度快，不能修饰“态度”，句意不通。"}, "sentence_index": 0, "correct_answer": "正向"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "房间的光线很正向。", "explanation": "这里应该用〈明亮〉。“正向”描述人的态度或想法，不用来形容光线。"}, {"text": "我们应该用正向的工具面对困难。", "explanation": "这里应该用〈态度〉。“正向”修饰的是态度或想法，不能修饰“工具”。"}, {"text": "他身体很正向，每天都锻炼。", "explanation": "这里应该用〈健康〉。“正向”指态度或想法，不用来形容身体状况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23118, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "正向", "is_correct": true, "explanation": "正向 zhèng xiàng 指好的、积极的方向或态度，是正确答案。"}, {"text": "争相", "is_correct": false, "explanation": "争相 zhēng xiāng 的两个音节声调都与 zhèng xiàng 不同，意思是争着。"}, {"text": "真相", "is_correct": false, "explanation": "真相 zhēn xiàng 第一个音节韵母 en 与 eng 不同，声调也不同，意思是事情的实际情况。"}, {"text": "正香", "is_correct": false, "explanation": "正香 zhèng xiāng 只有第二个音节声调不同，意思是香得正好（口语）。"}], "explanations": {"正向": "正向 zhèng xiàng 指好的、积极的方向或态度，是正确答案。", "争相": "争相 zhēng xiāng 的两个音节声调都与 zhèng xiàng 不同，意思是争着。", "真相": "真相 zhēn xiàng 第一个音节韵母 en 与 eng 不同，声调也不同，意思是事情的实际情况。", "正香": "正香 zhèng xiāng 只有第二个音节声调不同，意思是香得正好（口语）。"}, "sentence_index": null, "correct_answer": "正向"}, "level_3": {"options": [{"text": "正向", "is_correct": true, "explanation": "正向指积极的态度或想法，与“朋友的话让我变得更……了”的语境一致。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”形容物体或液体，不用来描述人的心态变化。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”指空间大，不能用来描述人的态度。"}, {"text": "瑰丽", "is_correct": false, "explanation": "语域：“瑰丽”多用于描写景物或文学语境，与这种口语描述不合。"}], "explanations": {"正向": "正向指积极的态度或想法，与“朋友的话让我变得更……了”的语境一致。", "透明": "搭配：“透明”形容物体或液体，不用来描述人的心态变化。", "宽敞": "搭配：“宽敞”指空间大，不能用来描述人的态度。", "瑰丽": "语域：“瑰丽”多用于描写景物或文学语境，与这种口语描述不合。"}, "sentence_index": 6, "correct_answer": "正向"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脸色很正向。", "explanation": "这里应该用〈红润〉。“正向”形容态度或想法，不用来形容脸色。"}, {"text": "他的声音很正向。", "explanation": "这里应该用〈响亮〉。“正向”不用来形容声音。"}, {"text": "这条路很正向。", "explanation": "这里应该用〈宽阔〉。“正向”不用来形容道路。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23118, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师一直用正向了的方式鼓励学生。", "corrected_sentence": "老师一直用正向的方式鼓励学生。", "error_description": "错误：“正向”作定语，后面不能加体标“了”。正确：应说“用正向的方式”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23118, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我看到他变得了正向了。", "corrected_sentence": "我看到他变得正向了。", "error_description": "错误：“变得”后不能插入“了”，应直接接形容词。正确：“变得正向了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c3cfeb27-25a9-4787-b0f8-1a25ba7e20be') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
