INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "别人告诉你想法或结果，你再告诉别人。", "primary_collocate": null, "pronunciation": "fǎn kuì", "ipa": "fan˨˩˦ kʰweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "小王的意见我已经反馈给经理了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "xiǎo wáng de yìjiàn wǒ yǐjīng fǎnkuì gěi jīnglǐ le", "sentence_source": "generated"}, {"text": "我已经把考试成绩反馈给家长了。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们的意见班长已经反馈给老师了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "tóngxuémen de yìjiàn bānzhǎng yǐjīng fǎnkuì gěi lǎoshī le", "sentence_source": "generated"}, {"text": "经理的几点建议我已经反馈给团队了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "jīnglǐ de jǐ diǎn jiànyì wǒ yǐjīng fǎnkuì gěi tuánduì le", "sentence_source": "generated"}, {"text": "客户的问题我马上反馈给技术部。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "kèhù de wèntí wǒ mǎshàng fǎnkuì gěi jìshùbù", "sentence_source": "generated"}, {"text": "客服已经把这条投诉反馈给后台了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "kèfú yǐjīng bǎ zhè tiáo tóusù fǎnkuì gěi hòutái le", "sentence_source": "generated"}, {"text": "他把检查结果反馈给了医生。", "target_word": "反馈", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你收到的消息记得反馈给我。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "nǐ shōudào de xiāoxi jìde fǎnkuì gěi wǒ", "sentence_source": "generated"}, {"text": "上面的通知她已经反馈给大家了。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "shàngmiàn de tōngzhī tā yǐjīng fǎnkuì gěi dàjiā le", "sentence_source": "generated"}, {"text": "她很快就把这个结果反馈给了同事。", "target_word": "反馈", "complexity_tier": "T3", "furigana": "tā hěn kuài jiù bǎ zhège jiéguǒ fǎnkuì gěi le tóngshì", "sentence_source": "generated"}], "morphological_forms": [{"form": "反馈了", "label": "体标"}, {"form": "反馈过", "label": "体标"}, {"form": "反馈意见", "label": "复合"}], "register": "中性", "sense_fingerprint": "把得到的想法或结果再告诉别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "反馈", "is_correct": true, "explanation": "正确。听到的是“反馈”fǎnkuì，指把得到的想法或结果再告诉别人。"}, {"text": "反对", "is_correct": false, "explanation": "反对 fǎnduì 与 反馈 只差声母：duì 的 d 与 kuì 的 k 不同，意思是持不同意见或抵制。"}, {"text": "反悔", "is_correct": false, "explanation": "反悔 fǎnhuǐ 与 反馈 只有第二音节不同：huǐ 与 kuì 的声母和声调都不同，意思是后悔、改变承诺。"}, {"text": "返回", "is_correct": false, "explanation": "返回 fǎnhuí 与 反馈 只有第二音节不同：huí（第二声）与 kuì（第四声），意思是回到原处，与反馈无关。"}], "explanations": {"反馈": "正确。听到的是“反馈”fǎnkuì，指把得到的想法或结果再告诉别人。", "反对": "反对 fǎnduì 与 反馈 只差声母：duì 的 d 与 kuì 的 k 不同，意思是持不同意见或抵制。", "反悔": "反悔 fǎnhuǐ 与 反馈 只有第二音节不同：huǐ 与 kuì 的声母和声调都不同，意思是后悔、改变承诺。", "返回": "返回 fǎnhuí 与 反馈 只有第二音节不同：huí（第二声）与 kuì（第四声），意思是回到原处，与反馈无关。"}, "sentence_index": null, "correct_answer": "反馈"}, "level_3": {"options": [{"text": "反馈", "is_correct": true, "explanation": "正确。“反馈给经理”指把意见转告给经理，与“已经……了”的完成语境相符。"}, {"text": "隐瞒", "is_correct": false, "explanation": "配价：“隐瞒”不能用“给”引出对象，应说“对……隐瞒”，而且意思与传递相反。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”是留存自用，不是交给经理，与“已经给经理了”相悖。"}, {"text": "扣下", "is_correct": false, "explanation": "语义：“扣下”是留住不给，与“已经给经理了”的完成动作相悖。"}], "explanations": {"反馈": "正确。“反馈给经理”指把意见转告给经理，与“已经……了”的完成语境相符。", "隐瞒": "配价：“隐瞒”不能用“给”引出对象，应说“对……隐瞒”，而且意思与传递相反。", "收藏": "语义：“收藏”是留存自用，不是交给经理，与“已经给经理了”相悖。", "扣下": "语义：“扣下”是留住不给，与“已经给经理了”的完成动作相悖。"}, "sentence_index": 0, "correct_answer": "反馈"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本书我已经反馈给朋友了。", "explanation": "这里应该用〈分享〉。反馈的宾语是想法、意见或结果，书是实物，不能用反馈。"}, {"text": "我昨天反馈了一台电脑。", "explanation": "这里应该用〈修〉。反馈的宾语是想法、意见或结果，电脑是实物，修电脑要说修。"}, {"text": "我昨天反馈了一场比赛。", "explanation": "这里应该用〈参加〉。反馈的宾语是想法或结果，比赛是活动，不能反馈。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "反馈", "is_correct": true, "explanation": "正确。“反馈给医生”指把检查结果告诉医生，与句子的常规语境相符。"}, {"text": "销毁", "is_correct": false, "explanation": "搭配：“销毁”的对象是物件，不能与“给了医生”搭配，句子读不通。"}, {"text": "删除", "is_correct": false, "explanation": "语义：“删除”是抹去，不是交给医生，与“给了医生”的传递方向相反。"}, {"text": "掩盖", "is_correct": false, "explanation": "语义：“掩盖”是遮住真相，与“给了医生”的传递相反。"}], "explanations": {"反馈": "正确。“反馈给医生”指把检查结果告诉医生，与句子的常规语境相符。", "销毁": "搭配：“销毁”的对象是物件，不能与“给了医生”搭配，句子读不通。", "删除": "语义：“删除”是抹去，不是交给医生，与“给了医生”的传递方向相反。", "掩盖": "语义：“掩盖”是遮住真相，与“给了医生”的传递相反。"}, "sentence_index": 6, "correct_answer": "反馈"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末去医院反馈生病的朋友。", "explanation": "这里应该用〈看望〉。反馈的宾语是想法或结果，不能是人，也不能表示探望。"}, {"text": "她很快就把这束花反馈给了同事。", "explanation": "这里应该用〈送〉。反馈只用于想法、意见或结果，花是实物，不能用反馈。"}, {"text": "医生很快就把药反馈给了病人。", "explanation": "这里应该用〈开〉。反馈的宾语是想法或结果，药是实物，要说开药或发药。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把新的看法反馈团队了。", "corrected_sentence": "我把新的看法反馈给团队了。", "error_description": "错误：“反馈”后漏了“给”，应说“反馈给团队了”。“反馈”要用“给”引出接收者，不能直接接名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23122, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把化验结果反馈了给医生。", "corrected_sentence": "她把化验结果反馈给了医生。", "error_description": "错误：“了”放错了位置。“反馈”后先接“给”，再接“了”，应说“反馈给了医生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把药物、肥料等用到人或植物身上，如用药治病。", "primary_collocate": null, "pronunciation": "shī yòng", "ipa": "ʂʅ˥ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "医生每天给他施用两次这种针剂。", "target_word": "施用", "complexity_tier": "T3", "furigana": "yī shēng měi tiān gěi tā shī yòng liǎng cì zhè zhǒng zhēn jì。", "sentence_source": "generated"}, {"text": "这种药膏应直接施用于患处。", "target_word": "施用", "complexity_tier": "T3", "furigana": "zhè zhǒng yào gāo yīng zhí jiē shī yòng yú huàn chù。", "sentence_source": "generated"}, {"text": "儿童不宜随便施用成人的药物。", "target_word": "施用", "complexity_tier": "T3", "furigana": "ér tóng bù yí suí biàn shī yòng chéng rén de yào wù。", "sentence_source": "generated"}, {"text": "医生教奶奶怎样施用这瓶药。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "施用这种针剂后，他的疼痛明显减轻。", "target_word": "施用", "complexity_tier": "T3", "furigana": "shī yòng zhè zhǒng zhēn jì hòu，tā de téng tòng míng xiǎn jiǎn qīng。", "sentence_source": "generated"}, {"text": "药要按说明书施用，不能多也不能少。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生给病人施用了新药，病很快就好了。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生在手术中施用这种麻醉药，效果很好。", "target_word": "施用", "complexity_tier": "T3", "furigana": "yī shēng zài shǒu shù zhōng shī yòng zhè zhǒng má zuì yào，xiào guǒ hěn hǎo。", "sentence_source": "generated"}, {"text": "这种针剂每次只能施用一支，不能多用。", "target_word": "施用", "complexity_tier": "T3", "furigana": "zhè zhǒng zhēn jì měi cì zhǐ néng shī yòng yì zhī，bù néng duō yòng。", "sentence_source": "generated"}, {"text": "请在医生的帮助下施用这种药。", "target_word": "施用", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "施用了", "label": "体标（了）"}, {"form": "施用过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "施用|用药治病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用 shī yòng：用药治病，即所听到的词。"}, {"text": "实用", "is_correct": false, "explanation": "实用 shí yòng 与 shī yòng 第一个音节的声调不同（第二声与第一声），意思是实际有用。"}, {"text": "试用", "is_correct": false, "explanation": "试用 shì yòng 与 shī yòng 第一个音节的声调不同（第四声与第一声），意思是先使用看效果。"}, {"text": "私用", "is_correct": false, "explanation": "私用 sī yòng 与 shī yòng 第一个音节的声母不同（s 与 sh），意思是为私人使用。"}], "explanations": {"施用": "施用 shī yòng：用药治病，即所听到的词。", "实用": "实用 shí yòng 与 shī yòng 第一个音节的声调不同（第二声与第一声），意思是实际有用。", "试用": "试用 shì yòng 与 shī yòng 第一个音节的声调不同（第四声与第一声），意思是先使用看效果。", "私用": "私用 sī yòng 与 shī yòng 第一个音节的声母不同（s 与 sh），意思是为私人使用。"}, "sentence_index": null, "correct_answer": "施用"}, "level_3": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用：给病人用药，与句意相合。"}, {"text": "收集", "is_correct": false, "explanation": "语义：收集是把东西聚拢，不是给病人用药，与“给他……两次”不合。"}, {"text": "冲洗", "is_correct": false, "explanation": "搭配：“冲洗”用于伤口或器物，不说冲洗给病人的针剂。"}, {"text": "粉碎", "is_correct": false, "explanation": "语义：粉碎会毁掉针剂，无法给病人用药。"}], "explanations": {"施用": "施用：给病人用药，与句意相合。", "收集": "语义：收集是把东西聚拢，不是给病人用药，与“给他……两次”不合。", "冲洗": "搭配：“冲洗”用于伤口或器物，不说冲洗给病人的针剂。", "粉碎": "语义：粉碎会毁掉针剂，无法给病人用药。"}, "sentence_index": 0, "correct_answer": "施用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "奶奶每天施用两个苹果。", "explanation": "这里应该用〈吃〉。施用指把药物、肥料用到人或植物身上，苹果是食物，要说“吃”。"}, {"text": "妈妈用抹布施用桌子。", "explanation": "这里应该用〈擦〉。施用不用于清洁物体，擦桌子要说“擦”。"}, {"text": "他每天施用衣服。", "explanation": "这里应该用〈穿〉。施用不用于衣物，穿衣服要说“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "施用", "is_correct": true, "explanation": "施用：给病人用了新药，与“病很快就好了”相合。"}, {"text": "销毁", "is_correct": false, "explanation": "语义：销毁药物会让病人无药可用，与“病很快就好了”矛盾。"}, {"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉药物不能使病人好转，与句意相反。"}, {"text": "研磨", "is_correct": false, "explanation": "搭配：“研磨”多用于谷物、矿石，不说研磨给病人的药。"}], "explanations": {"施用": "施用：给病人用了新药，与“病很快就好了”相合。", "销毁": "语义：销毁药物会让病人无药可用，与“病很快就好了”矛盾。", "扔掉": "语义：扔掉药物不能使病人好转，与句意相反。", "研磨": "搭配：“研磨”多用于谷物、矿石，不说研磨给病人的药。"}, "sentence_index": 6, "correct_answer": "施用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对门施用了很大的力。", "explanation": "这里应该用〈施加〉。施用指把药物、肥料用到人或植物上，力气要说“施加”。"}, {"text": "妈妈在厨房施用米饭。", "explanation": "这里应该用〈煮〉。施用不用于烹饪，做米饭要说“煮”。"}, {"text": "他每天施用房间。", "explanation": "这里应该用〈打扫〉。施用不用于清扫场所，打扫房间要说“打扫”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种软膏应当直接施用伤口。", "corrected_sentence": "这种软膏应当直接施用于伤口。", "error_description": "介词缺失：“施用”后带处所时须加“于”，应说“施用于伤口”，漏掉“于”即为错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位病人以前施用了过这种针剂。", "corrected_sentence": "这位病人以前施用过这种针剂。", "error_description": "体标语序错误：“过”须紧接动词，应说“施用过”；“了过”的语序不合规范，不能说“施用了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
