INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23128, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "表示把一件事说清楚。", "primary_collocate": null, "pronunciation": "biǎo míng", "ipa": "pjɑʊ˨˩˦ miŋ˧˥", "syllable_count": 2, "sentences": [{"text": "他用行动表明了自己的态度。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "调查表明，大多数人喜欢坐地铁。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数字表明今年的雨水很多。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师表明了自己的看法。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他表明自己不想去。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究表明，早睡对身体好。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的话表明她很生气。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司表明会马上解决问题。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事实表明，他是对的。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你表明你的意见。", "target_word": "表明", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "表明了", "label": "完成体"}, {"form": "表明过", "label": "经历体"}], "register": "中性", "sense_fingerprint": "把态度、看法或事实清楚地显示出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9dc599-3173-4820-a892-52e831b34649') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "表明", "is_correct": true, "explanation": "表明：表示把态度清楚地显示出来，与“自己的态度”搭配，符合句意。"}, {"text": "解决", "is_correct": false, "explanation": "语义：“解决”的对象是问题，不能用来解决“态度”，句意不通。"}, {"text": "出现", "is_correct": false, "explanation": "配价：“出现”是不及物动词，不能带“自己的态度”作宾语。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：“修理”用于机器、物品，不能用于“态度”。"}], "explanations": {"表明": "表明：表示把态度清楚地显示出来，与“自己的态度”搭配，符合句意。", "解决": "语义：“解决”的对象是问题，不能用来解决“态度”，句意不通。", "出现": "配价：“出现”是不及物动词，不能带“自己的态度”作宾语。", "修理": "搭配：“修理”用于机器、物品，不能用于“态度”。"}, "sentence_index": 0, "correct_answer": "表明"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在台上表明了一句台词。", "explanation": "这里应该用〈念〉。念指把台词、文字说出来；“表明”指把看法、事实说清楚，不用于说台词。"}, {"text": "他在会上表明了一段讲话。", "explanation": "这里应该用〈发表〉。发表用于讲话、意见；“表明”不能带“讲话”作宾语。"}, {"text": "演员在舞台上表明了一个魔术。", "explanation": "这里应该用〈表演〉。表演是把节目演给人看；“表明”不指演出魔术。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "表明", "is_correct": true, "explanation": "表明：表示说话的内容显示出她的心情，符合句意。"}, {"text": "发明", "is_correct": false, "explanation": "语义：“发明”指创造新东西，与“她很生气”无关，句意不通。"}, {"text": "消失", "is_correct": false, "explanation": "配价：“消失”是不及物动词，不能带“她很生气”这样的小句作宾语。"}, {"text": "打开", "is_correct": false, "explanation": "搭配：“打开”后面一般接门、窗、包等物体，不能接“她很生气”。"}], "explanations": {"表明": "表明：表示说话的内容显示出她的心情，符合句意。", "发明": "语义：“发明”指创造新东西，与“她很生气”无关，句意不通。", "消失": "配价：“消失”是不及物动词，不能带“她很生气”这样的小句作宾语。", "打开": "搭配：“打开”后面一般接门、窗、包等物体，不能接“她很生气”。"}, "sentence_index": 6, "correct_answer": "表明"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屏幕上表明了今天的日期。", "explanation": "这里应该用〈显示〉。显示指把画面、数字呈现出来；“表明”用于说明观点、态度或事实，不用来描述屏幕上的画面。"}, {"text": "博物馆表明了一幅古画。", "explanation": "这里应该用〈展示〉。展示指把物品摆出来给人看；“表明”不能用来指展出古画。"}, {"text": "他一眼就表明了那位老师。", "explanation": "这里应该用〈认出〉。认出指根据外貌辨认出某人；“表明”是把事情说清楚，不能用来辨认人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用沉默表明了过自己的立场。", "corrected_sentence": "他用沉默表明过自己的立场。", "error_description": "错误：“了”和“过”不能同时用在同一动词后。表示曾经做过某事只用“过”，应写作“表明过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们曾经向校方表明了过反对意见。", "corrected_sentence": "我们曾经向校方表明过反对意见。", "error_description": "错误：“了”和“过”不能同时用在动词后面。正确：表示曾经做过某事只用“过”，写作“表明过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
