INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23130, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "电流从电源出来，经过电器，再回到电源的那条路。", "primary_collocate": null, "pronunciation": "huí lù", "ipa": "xweɪ˧˥ lu˥˩", "syllable_count": 2, "sentences": [{"text": "电流走的这条路叫回路。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯不亮，因为回路断了。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电池、开关和灯泡连成了一个回路。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们画一个简单的回路。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回路里的电流太大，保险丝烧了。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把开关关上，回路就通了。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个回路里有两个灯泡。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电线接错了，回路没有接通。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用电池和电线做了一个回路。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回路一断，电器就不工作了。", "target_word": "回路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "闭合回路", "label": "复合"}], "register": "中性", "sense_fingerprint": "电流从电源出发经电器再回到电源的通路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '88f3bb72-e6b9-4d54-bc89-55e59a88509c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23130, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "回路", "is_correct": true, "explanation": "正确。回路指电流从电源出发、经电器再回到电源的通路。"}, {"text": "回炉", "is_correct": false, "explanation": "lú（第二声）与 lù（第四声）声调不同，意思是重新熔化或返工。"}, {"text": "回流", "is_correct": false, "explanation": "liú 比 lù 多一个 i 音，且声调不同，意思是向相反方向流动。"}, {"text": "回礼", "is_correct": false, "explanation": "lǐ 与 lù 的韵母和声调都不同，意思是还礼或回赠的礼物。"}, {"text": "贿赂", "is_correct": false, "explanation": "huì（第四声）与 huí（第二声）声调不同，意思是用财物收买。"}], "explanations": {"回路": "正确。回路指电流从电源出发、经电器再回到电源的通路。", "回炉": "lú（第二声）与 lù（第四声）声调不同，意思是重新熔化或返工。", "回流": "liú 比 lù 多一个 i 音，且声调不同，意思是向相反方向流动。", "回礼": "lǐ 与 lù 的韵母和声调都不同，意思是还礼或回赠的礼物。", "贿赂": "huì（第四声）与 huí（第二声）声调不同，意思是用财物收买。"}, "sentence_index": null, "correct_answer": "回路"}, "level_3": {"options": [{"text": "回路", "is_correct": true, "explanation": "正确。句中指电流走的闭合路径。"}, {"text": "桥梁", "is_correct": false, "explanation": "语义：桥梁是跨越河流或道路的建筑，不是电流经过的路径，句中不成立。"}, {"text": "眉毛", "is_correct": false, "explanation": "体貌：眉毛是脸部的器官，与电流走的路无关，句中不成立。"}, {"text": "水库", "is_correct": false, "explanation": "语义：水库是蓄水的地方，不能指电流走的路，句中不成立。"}], "explanations": {"回路": "正确。句中指电流走的闭合路径。", "桥梁": "语义：桥梁是跨越河流或道路的建筑，不是电流经过的路径，句中不成立。", "眉毛": "体貌：眉毛是脸部的器官，与电流走的路无关，句中不成立。", "水库": "语义：水库是蓄水的地方，不能指电流走的路，句中不成立。"}, "sentence_index": 0, "correct_answer": "回路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们沿着这条回路走到终点。", "explanation": "这里应该用〈路线〉。回路是闭合的电流路径，不能指一段通向终点的路线。"}, {"text": "我们穿过这个回路去操场。", "explanation": "这里应该用〈通道〉。回路是闭合的电流路径，不是人可以穿过去的通道。"}, {"text": "孩子们在这条回路上放风筝。", "explanation": "这里应该用〈空地〉。回路是闭合的电流路径，不是可以放风筝的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "回路", "is_correct": true, "explanation": "正确。句中指由电池、开关等组成的电路。"}, {"text": "树林", "is_correct": false, "explanation": "语义：树林是植物聚集的地方，不能与灯泡组成这种结构，句中不成立。"}, {"text": "脸", "is_correct": false, "explanation": "体貌：脸是人的器官，不能装着灯泡，句中不成立。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是广阔的水域，不能装有灯泡，句中不成立。"}], "explanations": {"回路": "正确。句中指由电池、开关等组成的电路。", "树林": "语义：树林是植物聚集的地方，不能与灯泡组成这种结构，句中不成立。", "脸": "体貌：脸是人的器官，不能装着灯泡，句中不成立。", "海洋": "语义：海洋是广阔的水域，不能装有灯泡，句中不成立。"}, "sentence_index": 6, "correct_answer": "回路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条回路通往学校。", "explanation": "这里应该用〈道路〉。回路是闭合的电流路径，不能指通往学校的道路。"}, {"text": "这条回路把水送到楼上。", "explanation": "这里应该用〈管道〉。回路是闭合的电流路径，不能用来输送水。"}, {"text": "运动员在这条回路上奔跑。", "explanation": "这里应该用〈跑道〉。回路是闭合的电流路径，不是供人奔跑的场地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张回路断了，灯就不亮了。", "corrected_sentence": "这条回路断了，灯就不亮了。", "error_description": "量词错误：“张”用于纸、桌子等扁平物，“回路”应该用“条”或“个”，应说“这条回路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把电线接上，回路就了通。", "corrected_sentence": "他把电线接上，回路就通了。", "error_description": "“了”位置错误：“通”前不能加“了”，应说“回路就通了”，不能说“回路就了通了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '649dba5f-72da-431b-9d36-f803aab50222') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
