INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23134, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23134, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "床是晚上我们睡觉用的、软软的、平的地方。", "primary_collocate": null, "pronunciation": "chuáng", "ipa": "tʂʰuɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "晚上十点，孩子已经躺在床上了。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张床又软又舒服，我一躺下就睡着了。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他病了，只能躺在床上休息。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的床靠着窗户，早上有阳光。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宾馆的床很干净，我睡得很好。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟在床上跳来跳去，妈妈很生气。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床太硬了，我昨晚没睡好。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉以前，她在床上看了一会儿书。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的房间里有两张床。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张床很高，小孩自己上不去。", "target_word": "床", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "张", "label": "量词"}, {"form": "床单", "label": "复合"}, {"form": "床垫", "label": "复合"}], "register": "中性", "sense_fingerprint": "床-夜晚睡觉用的柔软平坦的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1a78db7-dd1f-4ce9-a28b-f3b315ed5bc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "床", "is_correct": true, "explanation": "正确答案：床（chuáng），夜里睡觉用的柔软平坦的地方。"}, {"text": "窗", "is_correct": false, "explanation": "chuāng（第一声）与 chuáng（第二声）声调不同，意思是窗户。"}, {"text": "船", "is_correct": false, "explanation": "chuán 与 chuáng 韵母不同（-an 与 -ang），意思是船。"}, {"text": "双", "is_correct": false, "explanation": "shuāng 与 chuáng 声母不同（sh 与 ch），声调也不同，意思是两个、成对。"}, {"text": "闯", "is_correct": false, "explanation": "chuǎng（第三声）与 chuáng（第二声）声调不同，意思是冲撞、闯入。"}, {"text": "创", "is_correct": false, "explanation": "chuàng（第四声）与 chuáng（第二声）声调不同，意思是创造。"}], "explanations": {"床": "正确答案：床（chuáng），夜里睡觉用的柔软平坦的地方。", "窗": "chuāng（第一声）与 chuáng（第二声）声调不同，意思是窗户。", "船": "chuán 与 chuáng 韵母不同（-an 与 -ang），意思是船。", "双": "shuāng 与 chuáng 声母不同（sh 与 ch），声调也不同，意思是两个、成对。", "闯": "chuǎng（第三声）与 chuáng（第二声）声调不同，意思是冲撞、闯入。", "创": "chuàng（第四声）与 chuáng（第二声）声调不同，意思是创造。"}, "sentence_index": null, "correct_answer": "床"}, "level_3": {"options": [{"text": "床", "is_correct": true, "explanation": "正确：“躺在床上”是睡觉时的常见说法，符合句意。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板是用来写字的，不能躺在上面，“躺在黑板上”句意不通。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不是可以躺的地方，“躺在电视上”句意不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“躺”一般不与“冰箱”搭配，冰箱不是可以躺的地方。"}], "explanations": {"床": "正确：“躺在床上”是睡觉时的常见说法，符合句意。", "黑板": "语义：黑板是用来写字的，不能躺在上面，“躺在黑板上”句意不通。", "电视": "语义：电视不是可以躺的地方，“躺在电视上”句意不通。", "冰箱": "搭配：“躺”一般不与“冰箱”搭配，冰箱不是可以躺的地方。"}, "sentence_index": 0, "correct_answer": "床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给我买了一把床，放在阳台上。", "explanation": "这里应该用〈张〉。床是平面家具，量词用“张”；“把”用于椅子、刀等有柄的东西。"}, {"text": "这台机床的床很重，需要两个人抬。", "explanation": "此句中的“床”指机床的床身，是机器的承托部件，不是供人睡觉的家具，与本词义项不同。"}, {"text": "奶奶给我缝了一床厚被子，冬天很暖和。", "explanation": "此句中的“床”作被褥的量词，指成套的被子，是另一个义项；本词指供人睡觉的家具，这里不这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23134, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "床", "is_correct": true, "explanation": "正确答案：床（chuáng），夜里睡觉用的柔软平坦的地方。"}, {"text": "穿", "is_correct": false, "explanation": "chuān（第一声）与 chuáng（第二声）韵母不同（-uan 与 -uang），意思是穿（衣服）。"}, {"text": "撞", "is_correct": false, "explanation": "zhuàng 与 chuáng 声母不同（zh 与 ch），声调也不同，意思是撞击。"}, {"text": "爽", "is_correct": false, "explanation": "shuǎng 与 chuáng 声母不同（sh 与 ch），声调也不同，意思是爽快、舒服。"}, {"text": "霜", "is_correct": false, "explanation": "shuāng 与 chuáng 声母不同（sh 与 ch），声调也不同，意思是霜。"}, {"text": "壮", "is_correct": false, "explanation": "zhuàng 与 chuáng 声母不同（zh 与 ch），声调也不同，意思是强壮。"}], "explanations": {"床": "正确答案：床（chuáng），夜里睡觉用的柔软平坦的地方。", "穿": "chuān（第一声）与 chuáng（第二声）韵母不同（-uan 与 -uang），意思是穿（衣服）。", "撞": "zhuàng 与 chuáng 声母不同（zh 与 ch），声调也不同，意思是撞击。", "爽": "shuǎng 与 chuáng 声母不同（sh 与 ch），声调也不同，意思是爽快、舒服。", "霜": "shuāng 与 chuáng 声母不同（sh 与 ch），声调也不同，意思是霜。", "壮": "zhuàng 与 chuáng 声母不同（zh 与 ch），声调也不同，意思是强壮。"}, "sentence_index": null, "correct_answer": "床"}, "level_3": {"options": [{"text": "床", "is_correct": true, "explanation": "正确：“床太硬”指睡觉的床硬，与“没睡好”的因果相符。"}, {"text": "饭", "is_correct": false, "explanation": "语义：饭是吃的东西，“饭太硬”与“没睡好”没有因果关系，句意不通。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是睡觉的地方，与“没睡好”的原因不符。"}, {"text": "头发", "is_correct": false, "explanation": "体貌：头发是身体的毛发，“太硬”说的是外形，与“没睡好”无关。"}], "explanations": {"床": "正确：“床太硬”指睡觉的床硬，与“没睡好”的因果相符。", "饭": "语义：饭是吃的东西，“饭太硬”与“没睡好”没有因果关系，句意不通。", "面包": "语义：面包是食物，不是睡觉的地方，与“没睡好”的原因不符。", "头发": "体貌：头发是身体的毛发，“太硬”说的是外形，与“没睡好”无关。"}, "sentence_index": 6, "correct_answer": "床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家新买了一条床，放在卧室里。", "explanation": "这里应该用〈张〉。“条”用于长条形的东西，床是平面家具，量词用“张”。"}, {"text": "他打开床透透气，屋里很闷。", "explanation": "这里应该用〈窗户〉。“打开”用于门窗等可开合的东西，床不能打开，这里应该用〈窗户〉。"}, {"text": "他拧开床洗了洗手。", "explanation": "这里应该用〈水龙头〉。“拧开”用于水龙头、瓶盖等，床不能拧开，这里应该用〈水龙头〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们家有一只旧床，已经用了十年。", "corrected_sentence": "我们家有一张旧床，已经用了十年。", "error_description": "量词错误：床是平面家具，量词应用“张”，“只”用于动物或成对的东西。把“一只旧床”改为“一张旧床”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子在床玩得很开心。", "corrected_sentence": "孩子在床上玩得很开心。", "error_description": "位置错误：表示在床的表面要说“在床上”，漏掉“上”。把“在床玩”改为“在床上玩”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e5c3db9f-034b-4ee2-a951-b031ba786b8a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
