INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23136, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指数是一个数字，它告诉我们一个数要自己乘自己多少次。", "primary_collocate": null, "pronunciation": "zhǐ shù", "ipa": "ʈʂʅ˨˩ ʂu˥˩", "syllable_count": 2, "sentences": [{"text": "指数是一个小数字。", "target_word": "指数", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在3²里，2是指数。", "target_word": "指数", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "指数写在数字的右上角。", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指数是3，就要乘三次。", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在课上学习什么是指数。", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个指数告诉我们要乘多少次。", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我看见数字旁边有一个小指数。", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "指数是2，就是自己乘自己。", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问：“这个数的指数是几？”", "target_word": "指数", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把指数写错了，答案也错了。", "target_word": "指数", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "指數", "label": "繁体"}, {"form": "指数函数", "label": "复合"}], "register": "中性", "sense_fingerprint": "告诉我们自乘多少次的小数字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23136, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "指数", "is_correct": true, "explanation": "正确答案：指数 zhǐshù，指告诉我们自乘多少次的小数字。"}, {"text": "质数", "is_correct": false, "explanation": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是质数（素数）。"}, {"text": "指示", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是指示、指点。"}, {"text": "字数", "is_correct": false, "explanation": "zì（第四声）与 zhǐ（第三声）声母与声调都不同，意思是字的数目。"}, {"text": "指使", "is_correct": false, "explanation": "shǐ（第三声）与 shù（第四声）韵母与声调不同，意思是指使、差遣。"}], "explanations": {"指数": "正确答案：指数 zhǐshù，指告诉我们自乘多少次的小数字。", "质数": "zhì（第四声）与 zhǐ（第三声）声调不同，意思是质数（素数）。", "指示": "shì（第四声）与 shù（第四声）韵母不同（i 与 u），意思是指示、指点。", "字数": "zì（第四声）与 zhǐ（第三声）声母与声调都不同，意思是字的数目。", "指使": "shǐ（第三声）与 shù（第四声）韵母与声调不同，意思是指使、差遣。"}, "sentence_index": null, "correct_answer": "指数"}, "level_3": {"options": [{"text": "指数", "is_correct": true, "explanation": "正确：“指数是一个小数字”说明指数的本质，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑的一部分，不是数字，与“小数字”的说法不符。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：颜色不是数字，不能说“颜色是一个小数字”。"}, {"text": "体温", "is_correct": false, "explanation": "体貌：“体温”指人或动物身体的温度，与数字无关。"}], "explanations": {"指数": "正确：“指数是一个小数字”说明指数的本质，符合句意。", "窗户": "语义：窗户是建筑的一部分，不是数字，与“小数字”的说法不符。", "颜色": "语义：颜色不是数字，不能说“颜色是一个小数字”。", "体温": "体貌：“体温”指人或动物身体的温度，与数字无关。"}, "sentence_index": 0, "correct_answer": "指数"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年的物价指数比去年高了两个百分点。", "explanation": "这里的“指数”是物价指数，衡量价格总体水平的变化，与自乘次数的意思不同。"}, {"text": "今天的空气质量指数是85，属于良。", "explanation": "这里的“指数”指空气质量指数，是衡量空气污染程度的数值，与表示自乘次数的意思不同。"}, {"text": "在2⁴里，指数是2，就要乘四次。", "explanation": "这里应该用〈底数〉。2是被乘的底数，指数应是4（乘四次）；把指数说成2，就混淆了底数和指数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23136, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "指数", "is_correct": true, "explanation": "正确答案：指数 zhǐshù，指告诉我们自乘多少次的小数字。"}, {"text": "次数", "is_correct": false, "explanation": "cì（第四声）与 zhǐ（第三声）声母与声调不同，意思是次数。"}, {"text": "实数", "is_correct": false, "explanation": "shí（第二声）与 zhǐ（第三声）声母与声调不同，意思是实数。"}, {"text": "自述", "is_correct": false, "explanation": "zì（第四声）与 zhǐ（第三声）声母与声调不同，意思是自己叙述。"}, {"text": "只是", "is_correct": false, "explanation": "shì（第四声）与 shù（第四声）韵母不同，意思是只是、仅仅。"}], "explanations": {"指数": "正确答案：指数 zhǐshù，指告诉我们自乘多少次的小数字。", "次数": "cì（第四声）与 zhǐ（第三声）声母与声调不同，意思是次数。", "实数": "shí（第二声）与 zhǐ（第三声）声母与声调不同，意思是实数。", "自述": "zì（第四声）与 zhǐ（第三声）声母与声调不同，意思是自己叙述。", "只是": "shì（第四声）与 shù（第四声）韵母不同，意思是只是、仅仅。"}, "sentence_index": null, "correct_answer": "指数"}, "level_3": {"options": [{"text": "指数", "is_correct": true, "explanation": "正确：“数字旁边有一个小指数”指写在数字右上角的小数字，符合语境。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”不是写在数字旁边的符号，与“小指数”的说法不符。"}, {"text": "烟头", "is_correct": false, "explanation": "语义：烟头是香烟燃烧后的残余，不会出现在数字旁边作为数学符号。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”描述人或物的重量，不能指数字旁边的小符号。"}], "explanations": {"指数": "正确：“数字旁边有一个小指数”指写在数字右上角的小数字，符合语境。", "年龄": "语义：“年龄”不是写在数字旁边的符号，与“小指数”的说法不符。", "烟头": "语义：烟头是香烟燃烧后的残余，不会出现在数字旁边作为数学符号。", "体重": "体貌：“体重”描述人或物的重量，不能指数字旁边的小符号。"}, "sentence_index": 6, "correct_answer": "指数"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一只指数基金。", "explanation": "这里的“指数”是“指数基金”的意思，指跟踪某个市场指数的基金，与自乘次数的意思无关。"}, {"text": "今天股市的指数涨了两个百分点。", "explanation": "这里的“指数”指股票市场的综合指标，与数学中表示自乘次数的意思不同。"}, {"text": "这个数的指数是625，也就是5的4次方的结果。", "explanation": "这里应该用〈幂〉。625是5的4次方的结果，即幂；指数只表示乘的次数（这里是4），不能指计算结果。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "在4²里，这个指数是，表示4要自己乘两次。", "corrected_sentence": "在4²里，这个指数是2，表示4要自己乘两次。", "error_description": "成分残缺：“是”后缺少数字“2”，应为“这个指数是2”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23136, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们做题时要认真指数。", "corrected_sentence": "孩子们做题时要认真看指数。", "error_description": "漏字：“认真”后应接动词“看”，“指数”作宾语，缺少动词，“认真指数”不成句；正确说法是“认真看指数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23138, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一性", "is_correct": true, "explanation": "单一性指事物只有一种或种类很少，与多样性「很多东西各不相同」相反，是多样性的反义。"}, {"text": "速度", "is_correct": false, "explanation": "速度指运动的快慢，与多样性的种类差异无关，不构成反义。"}, {"text": "规律", "is_correct": false, "explanation": "规律指事物发展中稳定的联系，与多样性不构成反义关系。"}, {"text": "温度", "is_correct": false, "explanation": "温度指冷热程度，与多样性不构成反义关系。"}], "correct_answer": "单一性", "explanations": {"单一性": "单一性指事物只有一种或种类很少，与多样性「很多东西各不相同」相反，是多样性的反义。", "速度": "速度指运动的快慢，与多样性的种类差异无关，不构成反义。", "规律": "规律指事物发展中稳定的联系，与多样性不构成反义关系。", "温度": "温度指冷热程度，与多样性不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23138, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "单一性", "is_correct": true, "explanation": "单一性指事物只有一种或种类很少，与多样性「很多东西各不相同」相反，是多样性的反义。"}, {"text": "长度", "is_correct": false, "explanation": "长度指线状事物的长短，与多样性的种类差异无关，不构成反义。"}, {"text": "寿命", "is_correct": false, "explanation": "寿命指存在或存续的时间，与多样性不构成反义关系。"}, {"text": "密度", "is_correct": false, "explanation": "密度指单位体积内物质的多少，与多样性不构成反义关系。"}], "correct_answer": "单一性", "explanations": {"单一性": "单一性指事物只有一种或种类很少，与多样性「很多东西各不相同」相反，是多样性的反义。", "长度": "长度指线状事物的长短，与多样性的种类差异无关，不构成反义。", "寿命": "寿命指存在或存续的时间，与多样性不构成反义关系。", "密度": "密度指单位体积内物质的多少，与多样性不构成反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23138, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很多东西不一样", "primary_collocate": null, "pronunciation": "duō yàng xìng", "ipa": "tuo˥ jaŋ˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "这个城市的文化有很大的多样性。", "target_word": "多样性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保护动物就是保护生物的多样性。", "target_word": "多样性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校的课程有多样性，学生可以选自己喜欢的。", "target_word": "多样性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界的美来自它的多样性。", "target_word": "多样性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "森林里生物的多样性正在减少。", "target_word": "多样性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们要尊重人们想法的多样性。", "target_word": "多样性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京的饮食很有多样性，什么菜都能吃到。", "target_word": "多样性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多样性让我们的生活变得有意思。", "target_word": "多样性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司的员工来自不同国家，多样性很高。", "target_word": "多样性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写过一本书，讲的是语言的多样性。", "target_word": "多样性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "多样化", "label": "复合"}, {"form": "多樣性", "label": "繁体"}], "register": "书面", "sense_fingerprint": "事物种类多、各不相同的性质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9dc599-3173-4820-a892-52e831b34649') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "多样性", "is_correct": true, "explanation": "多样性指很多东西各不相同，这个城市的文化内容丰富、种类繁多，所以说有很大的多样性。"}, {"text": "体重", "is_correct": false, "explanation": "搭配：「体重」指人或物体的重量，文化没有体重，「有很大的体重」说不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：「身高」是人的外形特征，不能用来说城市文化。"}, {"text": "速度", "is_correct": false, "explanation": "语义：「速度」说的是运动的快慢，与文化的内容和种类无关。"}], "explanations": {"多样性": "多样性指很多东西各不相同，这个城市的文化内容丰富、种类繁多，所以说有很大的多样性。", "体重": "搭配：「体重」指人或物体的重量，文化没有体重，「有很大的体重」说不通。", "身高": "体貌：「身高」是人的外形特征，不能用来说城市文化。", "速度": "语义：「速度」说的是运动的快慢，与文化的内容和种类无关。"}, "sentence_index": 0, "correct_answer": "多样性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家只有一只猫，它的多样性很强。", "explanation": "这里应该用〈特点〉。多样性指很多事物彼此不同，只能描述一类事物的整体情况；描述单只猫的性质应说〈特点〉。"}, {"text": "科学家发明了一种多样性。", "explanation": "这里应该用〈新药〉。多样性指事物彼此不同的状况，不是可以被发明的具体东西；发明的对象应是〈新药〉这类具体事物。"}, {"text": "我对这次旅行有很深的多样性。", "explanation": "这里应该用〈感受〉。感受指个人的体会，可以说「有很深的感受」；多样性指事物彼此不同的状况，不能表示人的体会。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "多样性", "is_correct": true, "explanation": "多样性：饮食种类丰富，与后文「什么菜都能吃到」相呼应。"}, {"text": "长度", "is_correct": false, "explanation": "语义：「长度」指线状事物的长短，与饮食的种类不相符。"}, {"text": "寿命", "is_correct": false, "explanation": "搭配：「寿命」用于生物或器物的存续时间，不能说饮食有寿命。"}, {"text": "体格", "is_correct": false, "explanation": "体貌：「体格」指人的身体形态，饮食没有体格。"}], "explanations": {"多样性": "多样性：饮食种类丰富，与后文「什么菜都能吃到」相呼应。", "长度": "语义：「长度」指线状事物的长短，与饮食的种类不相符。", "寿命": "搭配：「寿命」用于生物或器物的存续时间，不能说饮食有寿命。", "体格": "体貌：「体格」指人的身体形态，饮食没有体格。"}, "sentence_index": 6, "correct_answer": "多样性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的多样性很坏，经常发火。", "explanation": "这里应该用〈脾气〉。脾气指人的性情，可以说「脾气很坏」；多样性指事物彼此不同的状况，不能用来形容人的性情。"}, {"text": "这辆车的多样性很快，开起来很舒服。", "explanation": "这里应该用〈速度〉。速度可以说「速度很快」；多样性指事物彼此不同的状况，不能用来描述快慢。"}, {"text": "这家书店的书多样性很重，我一个人搬不动。", "explanation": "这里应该用〈重量〉。“重”修饰的是重量，多样性指事物彼此不同的状况，不能用来说轻重。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的植物有很强地多样性。", "corrected_sentence": "这里的植物有很强的多样性。", "error_description": "错误：「很强地多样性」应改为「很强的多样性」。「的」用于连接修饰名词，「地」用于修饰动词或形容词，多样性是名词，前面要用「的」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座岛上有一种很特别地多样性。", "corrected_sentence": "这座岛上有一种很特别的多样性。", "error_description": "错误：「很特别地多样性」应改为「很特别的多样性」。「的」用于连接修饰名词，「地」用于修饰动词或形容词，多样性是名词，前面的修饰语要用「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
