INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23142, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "超过。", "primary_collocate": null, "pronunciation": "yú", "ipa": "y˧˥", "syllable_count": 1, "sentences": [{"text": "村里逾七成的人家都装了网络。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次活动的报名人数逾两千。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在这家医院工作逾三十年。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的雪厚逾一米，车开不上去。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵树的树龄逾千年，大家都很爱护它。", "target_word": "逾", "complexity_tier": "T3", "furigana": "Zhè kē shù de shùlíng yú qiān nián, dàjiā dōu hěn àihù tā.", "sentence_source": "generated"}, {"text": "奶奶年逾八十，耳朵还很好。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个包的价格逾五千元，我不敢买。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看书的速度很快，一小时逾百页。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参观博物馆的游客一天逾万人。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个湖的深度逾四十米，不能游泳。", "target_word": "逾", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逾期", "label": "复合"}, {"form": "逾越", "label": "复合"}], "register": "书面", "sense_fingerprint": "逾：书面语，超过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "逾", "is_correct": true, "explanation": "正确答案：逾（yú），意思是超过。"}, {"text": "雨", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。"}, {"text": "无", "is_correct": false, "explanation": "wú（第二声）与 yú（第二声）韵母不同（u 与 ü），意思是没有。"}, {"text": "玉", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是玉。"}, {"text": "语", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是语言。"}], "explanations": {"逾": "正确答案：逾（yú），意思是超过。", "雨": "yǔ（第三声）与 yú（第二声）声调不同，意思是雨。", "无": "wú（第二声）与 yú（第二声）韵母不同（u 与 ü），意思是没有。", "玉": "yù（第四声）与 yú（第二声）声调不同，意思是玉。", "语": "yǔ（第三声）与 yú（第二声）声调不同，意思是语言。"}, "sentence_index": null, "correct_answer": "逾"}, "level_3": {"options": [{"text": "逾", "is_correct": true, "explanation": "正确：“逾七成”表示超过七成，与“都装了网络”的语境相合。"}, {"text": "缺", "is_correct": false, "explanation": "语义：“缺”指缺少，与“都装了网络”的语境相矛盾。"}, {"text": "降", "is_correct": false, "explanation": "搭配：“降”指下降，不能用来描述人家所占的比例。"}, {"text": "退", "is_correct": false, "explanation": "搭配：“退”不能带“七成的人家”作主语或宾语，句意不通。"}], "explanations": {"逾": "正确：“逾七成”表示超过七成，与“都装了网络”的语境相合。", "缺": "语义：“缺”指缺少，与“都装了网络”的语境相矛盾。", "降": "搭配：“降”指下降，不能用来描述人家所占的比例。", "退": "搭配：“退”不能带“七成的人家”作主语或宾语，句意不通。"}, "sentence_index": 0, "correct_answer": "逾"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这支球队在实力上逾了对手。", "explanation": "这里应该用〈超越〉。逾多用于数量、时间等超过某个数值或期限，胜过对手这类竞争关系要用超越。"}, {"text": "周末我去医院逾奶奶。", "explanation": "这里应该用〈看望〉。逾用于超出界限，探望亲人要用看望。"}, {"text": "这个任务逾了我的能力。", "explanation": "这里应该用〈超出〉。逾用于时间、数量、程度的界限，能力范围这类抽象界限要用超出。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23142, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "逾", "is_correct": true, "explanation": "正确答案：逾（yú），意思是超过。"}, {"text": "与", "is_correct": false, "explanation": "yǔ（第三声）与 yú（第二声）声调不同，意思是和、跟。"}, {"text": "遇", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是遇见。"}, {"text": "油", "is_correct": false, "explanation": "yóu（第二声）与 yú（第二声）韵母不同（ou 与 ü），意思是油。"}, {"text": "欲", "is_correct": false, "explanation": "yù（第四声）与 yú（第二声）声调不同，意思是想要。"}], "explanations": {"逾": "正确答案：逾（yú），意思是超过。", "与": "yǔ（第三声）与 yú（第二声）声调不同，意思是和、跟。", "遇": "yù（第四声）与 yú（第二声）声调不同，意思是遇见。", "油": "yóu（第二声）与 yú（第二声）韵母不同（ou 与 ü），意思是油。", "欲": "yù（第四声）与 yú（第二声）声调不同，意思是想要。"}, "sentence_index": null, "correct_answer": "逾"}, "level_3": {"options": [{"text": "逾", "is_correct": true, "explanation": "正确：“逾五千元”表示超过五千元，与“我不敢买”的语境相合。"}, {"text": "送", "is_correct": false, "explanation": "搭配：“送”表示赠送，“价格送五千元”不成话。"}, {"text": "赚", "is_correct": false, "explanation": "语义：“赚”的主体通常是人，价格不能“赚”五千元。"}, {"text": "赔", "is_correct": false, "explanation": "搭配：“赔”表示赔偿或亏损，不能说“价格赔五千元”。"}], "explanations": {"逾": "正确：“逾五千元”表示超过五千元，与“我不敢买”的语境相合。", "送": "搭配：“送”表示赠送，“价格送五千元”不成话。", "赚": "语义：“赚”的主体通常是人，价格不能“赚”五千元。", "赔": "搭配：“赔”表示赔偿或亏损，不能说“价格赔五千元”。"}, "sentence_index": 6, "correct_answer": "逾"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每天上学都要逾马路。", "explanation": "此处“逾”取越过的意思，属另一义项。本词只表示超过，不用于跨过马路这类日常动作。"}, {"text": "孩子一下子逾了矮墙，跑了出去。", "explanation": "此处“逾”取越过的意思，属另一义项。本词此义不用于跨过矮墙这类具体障碍。"}, {"text": "猫一跃就逾了那条小河。", "explanation": "此处“逾”取越过的意思，属另一义项。本词只表示超过，不表示跨越河流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小区的住户很逾九成都装了空调。", "corrected_sentence": "这个小区的住户逾九成都装了空调。", "error_description": "错误：“逾”是动词，前面不能加程度副词“很”。正确：应说“住户逾九成”，去掉“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本词典的售价逾的两百元。", "corrected_sentence": "这本词典的售价逾两百元。", "error_description": "错误：“逾”后多加了“的”。正确：“逾”后直接接数量短语，不加“的”，应说“逾两百元”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
