INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23146, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "property", "definition": "植物不怕冷、不怕干的能力。", "primary_collocate": null, "pronunciation": "kàng nì xìng", "ipa": "kʰɑŋ˥˩ ni˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "仙人掌的抗逆性很强，不浇水也能活。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种花的抗逆性差，冬天要放在屋里。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的种子抗逆性强，天冷也能发芽。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农业专家想提高蔬菜的抗逆性。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草原上的草抗逆性强，风吹日晒都不怕。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵松树的抗逆性让它在雪山上长大。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了增强果树的抗逆性，他们改良了土壤。", "target_word": "抗逆性", "complexity_tier": "T3", "furigana": "Wèile zēngqiáng guǒshù de kàngnìxìng, tāmen gǎiliáng le tǔrǎng.", "sentence_source": "generated"}, {"text": "抗逆性好的麦子，今年冬天也没冻坏。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他选了几种抗逆性强的花放在阳台上。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花的抗逆性不同，所以养法也不同。", "target_word": "抗逆性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "抗逆", "label": "复合"}], "register": "书面", "sense_fingerprint": "抗逆性：植物耐寒、耐旱的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23146, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "抗逆性", "is_correct": true, "explanation": "正确：“仙人掌的抗逆性很强”指仙人掌抵抗干旱等环境的能力，与句意相合。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“很强”不修饰“颜色”，颜色应说“鲜艳”“淡雅”等。"}, {"text": "体温", "is_correct": false, "explanation": "语义：仙人掌没有恒定体温，“体温很强”说不通。"}, {"text": "外形", "is_correct": false, "explanation": "体貌：“外形”可以说“奇特”“端正”，不说“很强”。"}], "explanations": {"抗逆性": "正确：“仙人掌的抗逆性很强”指仙人掌抵抗干旱等环境的能力，与句意相合。", "颜色": "搭配：“很强”不修饰“颜色”，颜色应说“鲜艳”“淡雅”等。", "体温": "语义：仙人掌没有恒定体温，“体温很强”说不通。", "外形": "体貌：“外形”可以说“奇特”“端正”，不说“很强”。"}, "sentence_index": 0, "correct_answer": "抗逆性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个品种的抗逆性很漂亮，叶子是金黄色的。", "explanation": "这里应该用〈外观〉。抗逆性指植物抵抗不良环境的能力，不能用“漂亮”来形容，描述外貌应说“外观”。"}, {"text": "这种草的抗逆性很大，一车能装三百斤。", "explanation": "这里应该用〈重量〉。抗逆性是能力，不表示分量，说明重量应用“重量”。"}, {"text": "这批小麦的抗逆性很高，一亩能收四百斤。", "explanation": "这里应该用〈产量〉。抗逆性是抵抗不良环境的能力，不表示亩产，说明收成应用“产量”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23146, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "抗逆性", "is_correct": true, "explanation": "正确：“增强果树的抗逆性”指提高果树抵抗不良环境的能力，与句意相合。"}, {"text": "音量", "is_correct": false, "explanation": "语义：“音量”指声音的大小，与“增强果树”的语境不符。"}, {"text": "字迹", "is_correct": false, "explanation": "语义：“字迹”是人写的字，果树没有字迹可以被增强。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“脾气”多用于人或动物，不搭配“果树”。"}], "explanations": {"抗逆性": "正确：“增强果树的抗逆性”指提高果树抵抗不良环境的能力，与句意相合。", "音量": "语义：“音量”指声音的大小，与“增强果树”的语境不符。", "字迹": "语义：“字迹”是人写的字，果树没有字迹可以被增强。", "脾气": "搭配：“脾气”多用于人或动物，不搭配“果树”。"}, "sentence_index": 6, "correct_answer": "抗逆性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条抗逆性很强，干旱时也能活。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，抗逆性是抽象性质，应说“这种抗逆性”。"}, {"text": "这座抗逆性很强，冬天不怕冻。", "explanation": "这里应该用〈种〉。“座”用于山、楼房等大型物体，抗逆性是抽象性质，应说“这种抗逆性”。"}, {"text": "这块抗逆性很强，盐碱地也能长。", "explanation": "这里应该用〈种〉。“块”用于块状或片状的东西，抗逆性是抽象性质，应说“这种抗逆性”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种草的抗逆性强很，冬天也能活。", "corrected_sentence": "这种草的抗逆性很强，冬天也能活。", "error_description": "错误：“很”放在了“强”后面，程度副词应放在形容词前面。正确：应说“抗逆性很强”，不说“抗逆性强很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支抗逆性对果树的生长很重要。", "corrected_sentence": "这种抗逆性对果树的生长很重要。", "error_description": "错误：量词“支”多用于杆状物或队伍，修饰抽象性质“抗逆性”应用“种”，说“这种抗逆性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
