INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "abstract", "definition": "里面含有。", "primary_collocate": null, "pronunciation": "yùn hán", "ipa": "yn˥˩ xan˧˥", "syllable_count": 2, "sentences": [{"text": "这片土地下蕴含着丰富的石油。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大海里蕴含着很多我们不知道的宝藏。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座山蕴含着很多种珍贵的药材。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小小的种子里蕴含着生命的力量。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老房子的墙里蕴含着一家人的回忆。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的歌声蕴含着说不出的悲伤。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的每一页都蕴含着作者的心血。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "深山里蕴含着大量的水力资源。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看似普通的石头却蕴含着宝贵的矿物。", "target_word": "蕴含", "complexity_tier": "T3", "furigana": "kàn sì pǔ tōng de shí tou què yùn hán zhe bǎo guì de kuàng wù", "sentence_source": "generated"}, {"text": "这块地蕴含的资源，足够全村人用很多年。", "target_word": "蕴含", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "蕴含着", "label": "体标"}, {"form": "蕴含了", "label": "体标"}], "register": "书面", "sense_fingerprint": "蕴含:里面含有", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a818043-95f1-4634-87a5-2d86d4a18143') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "生长", "is_correct": false, "explanation": "搭配：“生长”指植物等的发育，不能用于石油。"}, {"text": "蕴含", "is_correct": true, "explanation": "蕴含指事物中含有，与“土地下的石油”搭配，填入后语义通顺。"}, {"text": "漂浮", "is_correct": false, "explanation": "语义：“漂浮”指浮在水面或空中，与“土地下”的位置相矛盾。"}, {"text": "堆放", "is_correct": false, "explanation": "语义：“堆放”指把东西摞在一起，与“土地下”的地下空间不符。"}], "explanations": {"生长": "搭配：“生长”指植物等的发育，不能用于石油。", "蕴含": "蕴含指事物中含有，与“土地下的石油”搭配，填入后语义通顺。", "漂浮": "语义：“漂浮”指浮在水面或空中，与“土地下”的位置相矛盾。", "堆放": "语义：“堆放”指把东西摞在一起，与“土地下”的地下空间不符。"}, "sentence_index": 0, "correct_answer": "蕴含"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "那条河里蕴含着一艘船。", "explanation": "这里应该用〈行驶〉。蕴含指事物内部隐含的内容，不用于说具体的船只在河上航行。"}, {"text": "屋子里蕴含着很多家具。", "explanation": "这里应该用〈摆〉。蕴含不用于说具体的家具陈设在某处。"}, {"text": "这棵树上蕴含着很多苹果。", "explanation": "这里应该用〈结〉。蕴含不用于说果实挂在树上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兑换", "is_correct": false, "explanation": "搭配：“兑换”的对象多是货币、积分等，不能接“心血”，句意讲不通。"}, {"text": "蕴含", "is_correct": true, "explanation": "蕴含指事物中隐含的内容，与“作者的心血”搭配，填入后语义通顺。"}, {"text": "占据", "is_correct": false, "explanation": "搭配：“占据”的宾语多是空间或位置，不能接“心血”。"}, {"text": "嫌弃", "is_correct": false, "explanation": "配价：“嫌弃”的宾语多是人或事，不能与“心血”搭配。"}], "explanations": {"兑换": "搭配：“兑换”的对象多是货币、积分等，不能接“心血”，句意讲不通。", "蕴含": "蕴含指事物中隐含的内容，与“作者的心血”搭配，填入后语义通顺。", "占据": "搭配：“占据”的宾语多是空间或位置，不能接“心血”。", "嫌弃": "配价：“嫌弃”的宾语多是人或事，不能与“心血”搭配。"}, "sentence_index": 6, "correct_answer": "蕴含"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里蕴含了一场比赛。", "explanation": "这里应该用〈举行〉。蕴含指事物中隐含的内容，不能用来说比赛这类活动在此进行。"}, {"text": "这个小组蕴含着很多成员。", "explanation": "这里应该用〈有〉。蕴含的主语是事物，不能说某个群体内部隐含着具体的人。"}, {"text": "去年这个村蕴含了一场洪水。", "explanation": "这里应该用〈遭受〉。蕴含指事物内部隐含的内容，不能用来说外来的灾害降临。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山里蕴含了着丰富的矿藏。", "corrected_sentence": "这座山里蕴含着丰富的矿藏。", "error_description": "错误：“蕴含”后同时用了“了”和“着”，体标重复。正确应只用“着”表示持续的状态：“这座山里蕴含着丰富的矿藏”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23152, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这片森林深处很蕴含着许多秘密。", "corrected_sentence": "这片森林深处蕴含着许多秘密。", "error_description": "错误：“蕴含”前多加了副词“很”。“蕴含”不能受“很”修饰；正确为“这片森林深处蕴含着许多秘密”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1a384705-d64a-4ba3-bbdd-bcf4c3a844f6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一件事做了之后，在别的地方或别的人身上产生的结果。", "primary_collocate": null, "pronunciation": "xiào yìng", "ipa": "ɕjɑʊ˥˩ iŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他的好心帮助，在同学们身上产生了很好的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师一夸，全班都努力，这个效应真好。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都买这个，就会有跟风的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件小事的效应，比我们想的大得多。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天早起，对全家人产生了很好的效应。", "target_word": "效应", "complexity_tier": "T3", "furigana": "xiào yìng", "sentence_source": "generated"}, {"text": "新地铁站开通，对附近的店产生了效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一笑，大家都笑了，这就是笑的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做的每件事，都会有一些效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，要想想这个办法的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的话在朋友中间产生了很大的效应。", "target_word": "效应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种效应", "label": "量词"}], "register": "通用", "sense_fingerprint": "一件事做了之后，在别处或别人身上产生的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '115bc740-bf98-4386-b8ea-52b5ee7d6f17') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "效应", "is_correct": true, "explanation": "效应指一件事做了之后，在别处或别人身上产生的结果，是本题的目标词。"}, {"text": "笑意", "is_correct": false, "explanation": "xiào yìng 与 xiào yì 的区别在于韵尾（有没有 -ng），笑意指笑的意思或笑容。"}, {"text": "校印", "is_correct": false, "explanation": "yìng 与 yìn 的区别在于韵尾（-ng 与 -n），校印指学校使用的印章。"}, {"text": "效益", "is_correct": false, "explanation": "yìng 与 yì 的区别在于韵尾（有没有 -ng），效益指经济上的收获。"}], "explanations": {"效应": "效应指一件事做了之后，在别处或别人身上产生的结果，是本题的目标词。", "笑意": "xiào yìng 与 xiào yì 的区别在于韵尾（有没有 -ng），笑意指笑的意思或笑容。", "校印": "yìng 与 yìn 的区别在于韵尾（-ng 与 -n），校印指学校使用的印章。", "效益": "yìng 与 yì 的区别在于韵尾（有没有 -ng），效益指经济上的收获。"}, "sentence_index": null, "correct_answer": "效应"}, "level_3": {"options": [{"text": "效应", "is_correct": true, "explanation": "“很好的效应”指好心帮助在同学身上产生的良好结果，与句意相符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”不能与“很好的”组合来描述帮助产生的结果，说“很好的颜色”不通。"}, {"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”指人或事物存在的时长，不能用来形容帮助产生的结果。"}, {"text": "罪过", "is_correct": false, "explanation": "语义：“罪过”含有错误、负面的意味，与“好心帮助”和“很好的”相矛盾。"}], "explanations": {"效应": "“很好的效应”指好心帮助在同学身上产生的良好结果，与句意相符。", "颜色": "搭配：“颜色”不能与“很好的”组合来描述帮助产生的结果，说“很好的颜色”不通。", "年龄": "搭配：“年龄”指人或事物存在的时长，不能用来形容帮助产生的结果。", "罪过": "语义：“罪过”含有错误、负面的意味，与“好心帮助”和“很好的”相矛盾。"}, "sentence_index": 0, "correct_answer": "效应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张优惠券仍然具有效应，可以在店里使用。", "explanation": "这里应该用〈效力〉。“具有……效力”指凭证或规定仍然有作用，效应不能这样用。"}, {"text": "这件衣服的效应很鲜艳，我每天都愿意穿。", "explanation": "这里应该用〈颜色〉。效应指一件事对别人或别处产生的结果，不能用来形容颜色，应说“颜色很鲜艳”。"}, {"text": "这盏灯的效应很亮，每个角落都看得清。", "explanation": "这里应该用〈亮度〉。效应指一件事产生的结果，不指灯的亮暗，说灯亮要用“亮度”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "效应", "is_correct": true, "explanation": "“笑的效应”指大家笑起来这一结果，与句中“大家都笑了”相符。"}, {"text": "重量", "is_correct": false, "explanation": "搭配：“重量”描述物体的轻重，不能用来指“笑”带来的结果。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”指商品的价值标准，与“笑”的结果不相关。"}, {"text": "哭声", "is_correct": false, "explanation": "语义：“哭声”与“大家都笑了”的情景相矛盾，不能作为“笑”的结果。"}], "explanations": {"效应": "“笑的效应”指大家笑起来这一结果，与句中“大家都笑了”相符。", "重量": "搭配：“重量”描述物体的轻重，不能用来指“笑”带来的结果。", "价格": "搭配：“价格”指商品的价值标准，与“笑”的结果不相关。", "哭声": "语义：“哭声”与“大家都笑了”的情景相矛盾，不能作为“笑”的结果。"}, "sentence_index": 6, "correct_answer": "效应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这套新软件的效应很高，打开文件只要两秒。", "explanation": "这里应该用〈效能〉。效能指工具或设备发挥作用的能力，说软件运行快要用“效能”；效应指事情产生的结果，不指性能。"}, {"text": "这次培训的效应很丰富，大家都学会了新技能。", "explanation": "这里应该用〈内容〉。效应指一件事对别处或别人产生的结果，不能用来形容内容多少，应说“内容很丰富”。"}, {"text": "这支笔的效应很粗，写出来的字很大。", "explanation": "这里应该用〈粗细〉。效应指一件事产生的结果，不指笔的粗细，笔的粗细应说“笔很粗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次讲座在大家中间产生了一条积极的效应。", "corrected_sentence": "这次讲座在大家中间产生了一种积极的效应。", "error_description": "错误形式是“一条效应”，正确形式是“一种效应”。“条”用于细长的东西，效应要用“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这种新方法地效应非常好，大家都愿意尝试。", "corrected_sentence": "这种新方法的效应非常好，大家都愿意尝试。", "error_description": "错误形式是“新方法地效应”，正确形式是“新方法的效应”。“地”用于修饰动词，修饰名词“效应”要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5818509c-6993-4e24-9b80-e1475903f8e1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
