INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23156, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "自己看到或经历过。", "primary_collocate": null, "pronunciation": "qīn lì", "ipa": "tɕʰin˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "我亲历了那场火灾，到现在还很害怕。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他亲历过一次海上的大风浪。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天我在现场，亲历了整个过程。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有亲历的事，不要随便乱说。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她亲历了城市二十年来的变化。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把自己亲历的事讲给我们听。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次洪水，村里人都亲历了。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他亲历了那次比赛，所以讲得很详细。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写的，都是作者亲历的事情。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我真想亲历一次太空旅行。", "target_word": "亲历", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "亲历了", "label": "体标"}, {"form": "亲历过", "label": "体标"}], "register": "书面", "sense_fingerprint": "自己看到或经历过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23156, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "亲历", "is_correct": true, "explanation": "正确：亲历指自己看到或经历过，与“那场火灾，到现在还很害怕”的语境相符。"}, {"text": "预防", "is_correct": false, "explanation": "语义：“预防”指事前防止，而火灾已经发生，与“那场火灾”相矛盾。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，火灾不能购买，不能说“购买了那场火灾”。"}, {"text": "喂养", "is_correct": false, "explanation": "搭配：“喂养”的对象是动物或植物，不能用于火灾，不能说“喂养了那场火灾”。"}], "explanations": {"亲历": "正确：亲历指自己看到或经历过，与“那场火灾，到现在还很害怕”的语境相符。", "预防": "语义：“预防”指事前防止，而火灾已经发生，与“那场火灾”相矛盾。", "购买": "搭配：“购买”的对象是商品，火灾不能购买，不能说“购买了那场火灾”。", "喂养": "搭配：“喂养”的对象是动物或植物，不能用于火灾，不能说“喂养了那场火灾”。"}, "sentence_index": 0, "correct_answer": "亲历"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在社区里亲历了一位新邻居。", "explanation": "这里应该用〈认识〉。亲历的宾语是事件，不能是人；认识新邻居要用认识。"}, {"text": "他亲历了那台电脑。", "explanation": "这里应该用〈购买〉。亲历的宾语必须是事件，电脑是买来用的，不能说亲历。"}, {"text": "我是从报纸上亲历这件事的。", "explanation": "这里应该用〈得知〉。亲历指自己看到或经历过，从报纸上知道的事情不是亲历。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23156, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "亲历", "is_correct": true, "explanation": "正确：亲历表示亲身经历，“村里人都……”符合村民亲身遭遇洪水的语境。"}, {"text": "预报", "is_correct": false, "explanation": "语义：“预报”是事前预测天气或灾害，洪水已经发生，不能再预报。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：庆祝的是喜事，洪水是灾害，“村里人都庆祝了”与语境矛盾。"}, {"text": "瞪", "is_correct": false, "explanation": "语义：“瞪”指睁大眼睛看人，与洪水没有关系，句意不通。"}], "explanations": {"亲历": "正确：亲历表示亲身经历，“村里人都……”符合村民亲身遭遇洪水的语境。", "预报": "语义：“预报”是事前预测天气或灾害，洪水已经发生，不能再预报。", "庆祝": "语义：庆祝的是喜事，洪水是灾害，“村里人都庆祝了”与语境矛盾。", "瞪": "语义：“瞪”指睁大眼睛看人，与洪水没有关系，句意不通。"}, "sentence_index": 6, "correct_answer": "亲历"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们亲历了一幅名画。", "explanation": "这里应该用〈欣赏〉。亲历的宾语必须是事件，名画是用来欣赏的，不能说亲历。"}, {"text": "他在北京亲历了三天。", "explanation": "这里应该用〈逗留〉。亲历的宾语是事件，“三天”是时段；在北京待了三天要用逗留。"}, {"text": "我在家里亲历了这场比赛。", "explanation": "这里应该用〈收看〉。亲历指亲身在场经历，在家通过电视看比赛要用收看。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他亲历了过那次停电，所以现在总备着蜡烛。", "corrected_sentence": "他亲历过那次停电，所以现在总备着蜡烛。", "error_description": "“了”和“过”不能同时用在动词“亲历”后面。表示经历过，应只用“过”，说“亲历过那次停电”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很亲历那次施工，只是看了照片。", "corrected_sentence": "他没亲历那次施工，只是看了照片。", "error_description": "程度副词“很”不能修饰动作动词“亲历”，表示没有经历应改用否定词“没”，应改为“他没亲历那次施工，只是看了照片。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
