INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23162, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让土变得有营养。", "primary_collocate": null, "pronunciation": "bǎo féi", "ipa": "paʊ̯˨˩˦ feɪ̯˧˥", "syllable_count": 2, "sentences": [{"text": "花农给花盆里的土加上腐叶来保肥。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种土保肥效果好，花长得特别漂亮。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让菜地保肥，每年都要加有机肥。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙地本来没营养，农民每年都施有机肥来保肥。", "target_word": "保肥", "complexity_tier": "T3", "furigana": "shā dì běn lái méi yíng yǎng, nóng mín měi nián dōu shī yǒu jī féi lái bǎo féi.", "sentence_source": "generated"}, {"text": "冬天来了，农民把稻草盖在地上保肥。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把茶叶渣埋进花盆里，想给土保肥。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块地多年不保肥，菜越种越小。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "养蚯蚓能让土更松，也能帮土保肥。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校的菜园用落叶堆肥来保肥。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种完豆子再种玉米，也是一种保肥的办法。", "target_word": "保肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "保水保肥", "label": "复合"}, {"form": "保肥能力", "label": "复合"}], "register": "中性", "sense_fingerprint": "给土加养分，让土保持有营养", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '01eeaa98-ccee-411a-b977-696f87b61517') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23162, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "保肥", "is_correct": true, "explanation": "正确答案。保肥指让土保持养分，使土地有营养。"}, {"text": "保费", "is_correct": false, "explanation": "féi（第二声）与 fèi（第四声）声调不同，意思是保险费。"}, {"text": "报废", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）、fèi（第四声）与 féi（第二声）声调不同，意思是报废，即不再使用。"}, {"text": "暴肥", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是短时间内身体迅速长肉，与土壤无关。"}], "explanations": {"保肥": "正确答案。保肥指让土保持养分，使土地有营养。", "保费": "féi（第二声）与 fèi（第四声）声调不同，意思是保险费。", "报废": "bào（第四声）与 bǎo（第三声）、fèi（第四声）与 féi（第二声）声调不同，意思是报废，即不再使用。", "暴肥": "bào（第四声）与 bǎo（第三声）声调不同，意思是短时间内身体迅速长肉，与土壤无关。"}, "sentence_index": null, "correct_answer": "保肥"}, "level_3": {"options": [{"text": "保肥", "is_correct": true, "explanation": "正确：保肥指让土保持养分，与「加上腐叶」的目的相符。"}, {"text": "挖掘", "is_correct": false, "explanation": "语义：挖掘是把土刨开，与加腐叶的目的无关，句意不通。"}, {"text": "修剪", "is_correct": false, "explanation": "搭配：修剪多用于枝叶，不能用于给土加东西的做法。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫指清除脏物，与加腐叶让土变肥的目的相反。"}], "explanations": {"保肥": "正确：保肥指让土保持养分，与「加上腐叶」的目的相符。", "挖掘": "语义：挖掘是把土刨开，与加腐叶的目的无关，句意不通。", "修剪": "搭配：修剪多用于枝叶，不能用于给土加东西的做法。", "打扫": "语义：打扫指清除脏物，与加腐叶让土变肥的目的相反。"}, "sentence_index": 0, "correct_answer": "保肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "牛奶能保肥孩子的身体，让他长高。", "explanation": "这里应该用〈滋养〉。保肥是让土壤有营养，给人补充营养要说滋养。"}, {"text": "这座水库能保肥，夏天就不缺水了。", "explanation": "这里应该用〈蓄水〉。保肥指土壤保持养分，水库存水要说蓄水。"}, {"text": "这双布鞋很保肥，穿了三年还很新。", "explanation": "保肥只用于土壤和肥料，布鞋耐用要说耐穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保肥", "is_correct": true, "explanation": "正确：保肥指土保持营养，与「菜越种越小」的原因相符。"}, {"text": "说话", "is_correct": false, "explanation": "语义：土地不会说话，句意不通，与「菜越种越小」的原因无关。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：唱歌与菜的生长无关，不能解释「菜越种越小」。"}, {"text": "跑步", "is_correct": false, "explanation": "配价：「跑步」以人为施事，不能以「这块地」作主语。"}], "explanations": {"保肥": "正确：保肥指土保持营养，与「菜越种越小」的原因相符。", "说话": "语义：土地不会说话，句意不通，与「菜越种越小」的原因无关。", "唱歌": "语义：唱歌与菜的生长无关，不能解释「菜越种越小」。", "跑步": "配价：「跑步」以人为施事，不能以「这块地」作主语。"}, "sentence_index": 6, "correct_answer": "保肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这床厚被子很保肥，冬天睡觉很暖和。", "explanation": "这里应该用〈保温〉。保肥指让土变得有营养，被子防寒要说保温。"}, {"text": "孩子多吃猪肝能保肥，身体更好。", "explanation": "保肥只用于土壤，给人补充铁等营养要说补铁。"}, {"text": "干旱时要及时保肥，庄稼才不会枯。", "explanation": "这里应该用〈浇水〉。庄稼干旱时缺的是水，不是养分，保肥无法解决。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "黏土被保肥，所以庄稼长得壮。", "corrected_sentence": "黏土能保肥，所以庄稼长得壮。", "error_description": "错误形式：被保肥；正确形式：能保肥。「保肥」是主动动词，不能直接加「被」；表示能力应用助动词「能」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这块地常加腐叶，保肥保很好。", "corrected_sentence": "这块地常加腐叶，保肥保得很好。", "error_description": "错误形式：保肥保很好；正确形式：保肥保得很好。动词后带形容词补语时，中间要用「得」连接。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd62a715d-2b21-4d59-a56a-51c1827d6c70') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
