INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23174, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "出门去某个地方。", "primary_collocate": null, "pronunciation": "chū xíng", "ipa": "ʈʂʰu˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "今天风很大，出行要小心。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们明天早上七点出行。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他出行时总是带着地图。", "target_word": "出行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面下雪了，老人不要出行。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末我想和朋友一起出行。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出行以前，请检查一下门窗。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她很少一个人出行。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个假期我们打算全家一起出行。", "target_word": "出行", "complexity_tier": "T3", "furigana": "zhè ge jià qī wǒ men dǎ suan quán jiā yì qǐ chū xíng", "sentence_source": "generated"}, {"text": "孩子们出行时要跟着老师。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为生病，他这几天没有出行。", "target_word": "出行", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "出行了", "label": "体标（了）"}, {"form": "出行过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "动词：出门去某个地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739f0140-8cbc-457e-8526-f10ae4204bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "出行", "is_correct": true, "explanation": "出行：出门去某地，此处指外出时要注意安全，与“风很大”的语境相符。"}, {"text": "吃饭", "is_correct": false, "explanation": "语义：大风与吃饭是否安全没有关系，句子说不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不是大风天需要特别小心的活动，句子不成立。"}, {"text": "写作业", "is_correct": false, "explanation": "语义：大风与写作业没有关系，“今天风很大，写作业要小心”说不通。"}], "explanations": {"出行": "出行：出门去某地，此处指外出时要注意安全，与“风很大”的语境相符。", "吃饭": "语义：大风与吃饭是否安全没有关系，句子说不通。", "睡觉": "语义：“睡觉”不是大风天需要特别小心的活动，句子不成立。", "写作业": "语义：大风与写作业没有关系，“今天风很大，写作业要小心”说不通。"}, "sentence_index": 0, "correct_answer": "出行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚饭后都在电脑前出行。", "explanation": "这里应该用〈坐〉。出行指离开住处到别的地方去，与“在电脑前”的语义相矛盾。"}, {"text": "这个周末我想和家人在家里出行。", "explanation": "这里应该用〈待在〉。出行表示出门、外出，和“在家里”的语义相矛盾。"}, {"text": "运动员明天在球场出行比赛。", "explanation": "这里应该用〈比赛〉。出行指出门去某地，不表示在某处进行比赛，应说“在球场比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "出行", "is_correct": true, "explanation": "出行：外出、出门，与“她很少一个人”的语境相符。"}, {"text": "同行", "is_correct": false, "explanation": "语义：“同行”指结伴一起走，与“一个人”相矛盾。"}, {"text": "聚会", "is_correct": false, "explanation": "搭配：“聚会”需要多人参加，不能和“一个人”搭配。"}, {"text": "团聚", "is_correct": false, "explanation": "语义：“团聚”指亲友或家人聚在一起，与“一个人”相矛盾。"}], "explanations": {"出行": "出行：外出、出门，与“她很少一个人”的语境相符。", "同行": "语义：“同行”指结伴一起走，与“一个人”相矛盾。", "聚会": "搭配：“聚会”需要多人参加，不能和“一个人”搭配。", "团聚": "语义：“团聚”指亲友或家人聚在一起，与“一个人”相矛盾。"}, "sentence_index": 6, "correct_answer": "出行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于出行了，可以在病床上静养了。", "explanation": "这里应该用〈康复〉。出行指外出去某地，与“在病床上静养”的语义相矛盾。"}, {"text": "我每天下午在游泳池出行。", "explanation": "这里应该用〈游泳〉。出行表示外出去某地，不指在泳池里做运动。"}, {"text": "孩子们在教室里出行了。", "explanation": "这里应该用〈上课〉。出行是出门、外出，与“在教室里”的语义相矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23174, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次我们坐飞机出行西藏。", "corrected_sentence": "这次我们坐飞机出行去西藏。", "error_description": "错误形式：“出行西藏”；正确形式：“出行去西藏”。“出行”后接目的地时要加“去”，不能直接带地名作宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他昨天一早没出行了。", "corrected_sentence": "他昨天一早就出行了。", "error_description": "错误形式：“没出行了”；正确形式：“就出行了”。“没”否定的是已经发生的动作，与表示完成的句末“了”相冲突；表示昨天一早已经出门，应说“就出行了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
