INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "能提供动力、热或电的自然资源，如煤、石油、太阳能。", "primary_collocate": null, "pronunciation": "néng yuán", "ipa": "nɤŋ˧˥ ɥɛn˧˥", "syllable_count": 2, "sentences": [{"text": "太阳能是一种干净的能源。", "target_word": "能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个国家缺少能源，要从国外买。", "target_word": "能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们应该节约能源，随手关灯。", "target_word": "能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "风是不会用完的能源。", "target_word": "能源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "现在越来越多的国家重视能源的开发和利用。", "target_word": "能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂每天要用很多能源。", "target_word": "能源", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "石油和煤都是重要的能源。", "target_word": "能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这座城市正在努力开发更多的能源。", "target_word": "能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冬天用电多，能源价格也会涨。", "target_word": "能源", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "能源不够时，机器就不能工作。", "target_word": "能源", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种能源", "label": "量词"}, {"form": "新能源", "label": "复合"}, {"form": "清洁能源", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词，能提供动力、热、电的资源，如煤、石油、太阳能", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fef3691-c05f-4979-b766-4af9a742d3ff') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23176, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "污水", "is_correct": false, "explanation": "搭配：「干净的」与「污水」意思矛盾，污水本身就不干净。"}, {"text": "能源", "is_correct": true, "explanation": "能源：能提供动力、热、电的资源。太阳能正是一种干净的能源，正确。"}, {"text": "污染", "is_correct": false, "explanation": "语义：污染与“干净”意思相反，太阳能不是污染。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾与“干净”相反，太阳能不可能是垃圾。"}], "explanations": {"污水": "搭配：「干净的」与「污水」意思矛盾，污水本身就不干净。", "能源": "能源：能提供动力、热、电的资源。太阳能正是一种干净的能源，正确。", "污染": "语义：污染与“干净”意思相反，太阳能不是污染。", "垃圾": "语义：垃圾与“干净”相反，太阳能不可能是垃圾。"}, "sentence_index": 0, "correct_answer": "能源"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天工作十二个小时，能源一直很充沛。", "explanation": "这里应该用〈精力〉。「能源」指可以提供动力、热、电的资源，人的精力不能说能源。"}, {"text": "我们学校的图书能源很丰富。", "explanation": "这里应该用〈资源〉。「能源」只指提供动力、热、电的东西，图书等资料要说资源。"}, {"text": "他的能源很强，学什么都很快。", "explanation": "这里应该用〈能力〉。「能源」指提供动力、热、电的资源，人的能力不能说能源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "搭配：「重要的」不能修饰颜色，石油和煤也不是颜色。"}, {"text": "食品", "is_correct": false, "explanation": "语义：石油和煤不是食品，句子说不通。"}, {"text": "能源", "is_correct": true, "explanation": "能源：能提供动力、热、电的资源。石油和煤都属于这一类，正确。"}, {"text": "疾病", "is_correct": false, "explanation": "语义：石油和煤不是疾病，与“重要的”语境无关。"}], "explanations": {"颜色": "搭配：「重要的」不能修饰颜色，石油和煤也不是颜色。", "食品": "语义：石油和煤不是食品，句子说不通。", "能源": "能源：能提供动力、热、电的资源。石油和煤都属于这一类，正确。", "疾病": "语义：石油和煤不是疾病，与“重要的”语境无关。"}, "sentence_index": 6, "correct_answer": "能源"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这匹布的能源很好，颜色也很漂亮。", "explanation": "这里应该用〈质地〉。「能源」指提供动力、热、电的资源，布料的品质要说质地。"}, {"text": "这块蛋糕的能源很漂亮，大家都想买一块。", "explanation": "这里应该用〈外形〉。「能源」指提供动力、热、电的资源，蛋糕的样子要说外形。"}, {"text": "这家公司的能源很充足，可以投资新项目。", "explanation": "这里应该用〈资金〉。公司的钱要说资金，「能源」指提供动力、热、电的资源。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座工厂使用的是一只新能源。", "corrected_sentence": "这座工厂使用的是一种新能源。", "error_description": "量词错误：「能源」应用「种」，「只」用于动物或小件物品，不能用于能源。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们要大力开发一颗新能源，保护环境。", "corrected_sentence": "我们要大力开发一种新能源，保护环境。", "error_description": "量词错误：「能源」应用「种」，「颗」用于粒状的小东西，不能用于能源。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57b75a7c-a155-452c-a492-ca710e44ce91') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23178, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "“浪费”与“节约”（不浪费）意义相反，是标准的反义词。"}, {"text": "参观", "is_correct": false, "explanation": "“参观”指到某地看看，与“节约”没有反义关系。"}, {"text": "发明", "is_correct": false, "explanation": "“发明”指创造新事物，与“节约”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "“散步”指随意走走，与“节约”没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "“浪费”与“节约”（不浪费）意义相反，是标准的反义词。", "参观": "“参观”指到某地看看，与“节约”没有反义关系。", "发明": "“发明”指创造新事物，与“节约”没有反义关系。", "散步": "“散步”指随意走走，与“节约”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23178, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "浪费", "is_correct": true, "explanation": "“浪费”与“节约”意义相反，是标准的反义词。"}, {"text": "旅行", "is_correct": false, "explanation": "“旅行”指到外地游览，与“节约”没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "“唱歌”指发出乐音，与“节约”没有反义关系。"}, {"text": "写作", "is_correct": false, "explanation": "“写作”指写文章，与“节约”没有反义关系。"}], "correct_answer": "浪费", "explanations": {"浪费": "“浪费”与“节约”意义相反，是标准的反义词。", "旅行": "“旅行”指到外地游览，与“节约”没有反义关系。", "唱歌": "“唱歌”指发出乐音，与“节约”没有反义关系。", "写作": "“写作”指写文章，与“节约”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23178, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不浪费东西。", "primary_collocate": null, "pronunciation": "jié yuē", "ipa": "tɕjɛ˧˥ ɥɛ˧˥", "syllable_count": 2, "sentences": [{"text": "我们要节约用水。", "target_word": "节约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈教我节约粮食。", "target_word": "节约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他每个月都节约一点钱。", "target_word": "节约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请大家节约用纸。", "target_word": "节约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "冬天节约用电，可以少花钱。", "target_word": "节约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爷爷过日子很会节约。", "target_word": "节约", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "学校号召同学们节约时间，不要浪费。", "target_word": "节约", "complexity_tier": "T3", "furigana": "xué xiào hào zhào tóng xué men jié yuē shí jiān, bú yào làng fèi.", "sentence_source": "generated"}, {"text": "她把吃剩的饭菜放进冰箱，这样可以节约粮食。", "target_word": "节约", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐公共汽车上班，既方便又节约钱。", "target_word": "节约", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "离开房间时随手关灯，就是节约用电。", "target_word": "节约", "complexity_tier": "T3", "furigana": "lí kāi fáng jiān shí suí shǒu guān dēng, jiù shì jié yuē yòng diàn.", "sentence_source": "generated"}], "morphological_forms": [{"form": "节约了", "label": "体标"}, {"form": "节约过", "label": "体标"}], "register": "中性", "sense_fingerprint": "节约：不浪费东西（作动词）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f775cb0c-f64a-45de-b26d-fcb784c8d131') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23178, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "节约", "is_correct": true, "explanation": "“节约用水”是常见搭配，指不浪费地使用水，与“我们要……”的劝导语气相符。"}, {"text": "浪费", "is_correct": false, "explanation": "语义：“浪费用水”表示白白用掉水，与“我们要”的劝导语气相反。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”的对象是场所或展览，不能接“用水”作宾语。"}, {"text": "散步", "is_correct": false, "explanation": "配价：“散步”是不及物动词，后面不能直接带“用水”这样的宾语。"}], "explanations": {"节约": "“节约用水”是常见搭配，指不浪费地使用水，与“我们要……”的劝导语气相符。", "浪费": "语义：“浪费用水”表示白白用掉水，与“我们要”的劝导语气相反。", "参观": "搭配：“参观”的对象是场所或展览，不能接“用水”作宾语。", "散步": "配价：“散步”是不及物动词，后面不能直接带“用水”这样的宾语。"}, "sentence_index": 0, "correct_answer": "节约"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们要节约垃圾。", "explanation": "这里应该用〈减少〉。“节约”指不浪费已有的东西，垃圾要用“减少”。"}, {"text": "我们要节约环境。", "explanation": "这里应该用〈保护〉。“节约”针对可以用掉的资源，环境要用“保护”。"}, {"text": "这家工厂要节约效率。", "explanation": "这里应该用〈提高〉。“效率”不能被“节约”，要说“提高效率”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23178, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "节约", "is_correct": true, "explanation": "“节约时间”与后半句“不要浪费”相符，是正确的动词形式。"}, {"text": "微笑", "is_correct": false, "explanation": "配价：“微笑”是不及物动词，不能带“时间”作宾语。"}, {"text": "消耗", "is_correct": false, "explanation": "语义：“消耗时间”与后半句“不要浪费”自相矛盾。"}, {"text": "出汗", "is_correct": false, "explanation": "配价：“出汗”是不及物动词，不能接“时间”这样的宾语。"}], "explanations": {"节约": "“节约时间”与后半句“不要浪费”相符，是正确的动词形式。", "微笑": "配价：“微笑”是不及物动词，不能带“时间”作宾语。", "消耗": "语义：“消耗时间”与后半句“不要浪费”自相矛盾。", "出汗": "配价：“出汗”是不及物动词，不能接“时间”这样的宾语。"}, "sentence_index": 6, "correct_answer": "节约"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要节约负担，让大家轻松一点。", "explanation": "这里应该用〈减轻〉。“节约”针对用掉的资源，负担要用“减轻”。"}, {"text": "政府要节约污染，保护河流。", "explanation": "这里应该用〈治理〉。“节约”不能用于污染，污染要说“治理”。"}, {"text": "我们要节约蚊子，减少疾病。", "explanation": "这里应该用〈消灭〉。“节约”指不浪费，蚊子要用“消灭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23178, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们应该节约得用电。", "corrected_sentence": "我们应该节约用电。", "error_description": "补语误用：“节约”与宾语之间不能插入“得”，应为“节约用电”。错误形式：节约得用电；正确形式：节约用电。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23178, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把家里的钱节约很好。", "corrected_sentence": "她把家里的钱节约得很好。", "error_description": "缺少“得”：“节约”后要用“得”引出补语“很好”，应说“节约得很好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0e4a91d6-71e2-4710-8870-96bbf7f7d5cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
