INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "一个事情引起另一个事情，这样一直下去。", "primary_collocate": null, "pronunciation": "liàn shì fǎn yìng", "ipa": "ljɛn⁵¹ ʂʐ̩⁵¹ fan²¹⁴ iŋ⁵¹", "syllable_count": 4, "sentences": [{"text": "一件小事会引起链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他迟到了，结果出现了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个坏消息引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面的车停下来，后面的车也停下来，这是链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水价上涨，带来了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要小看这件事，它可能引起链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "furigana": "liàn shì fǎn yìng", "sentence_source": "generated"}, {"text": "他起床晚，全家都晚了，真是链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的结果引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骨牌一个接一个倒下，就是链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的好心情在办公室里引起了链式反应。", "target_word": "链式反应", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一场链式反应", "label": "量词"}], "register": "中性", "sense_fingerprint": "一件事引起另一件事，连续不断", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0da7e96c-13a7-44d1-bb5d-15e217ce33fe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "链式反应", "is_correct": true, "explanation": "正确。“一件小事会引起链式反应”指一件事接连引出后续事件，与句意相符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指人的体型，不能作为小事引起的后果。"}, {"text": "饮水机", "is_correct": false, "explanation": "语义：“饮水机”是一种家电，不是事件，不能作为小事引起的结果。"}, {"text": "天气预报", "is_correct": false, "explanation": "搭配：“引起”后接的是事件或后果，“天气预报”是播报内容，不能作为引起的结果。"}], "explanations": {"链式反应": "正确。“一件小事会引起链式反应”指一件事接连引出后续事件，与句意相符。", "身材": "体貌：“身材”指人的体型，不能作为小事引起的后果。", "饮水机": "语义：“饮水机”是一种家电，不是事件，不能作为小事引起的结果。", "天气预报": "搭配：“引起”后接的是事件或后果，“天气预报”是播报内容，不能作为引起的结果。"}, "sentence_index": 0, "correct_answer": "链式反应"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她对我的道歉没有链式反应，只是低头走开了。", "explanation": "这里应该用〈回应〉。链式反应指一连串事件相继发生，对道歉的单次应答要用“回应”。"}, {"text": "他的成功引发了一台链式反应。", "explanation": "这里应该用〈场〉。量词“台”用于机器等器物，链式反应是事件过程，应搭配“场”。"}, {"text": "这次比赛他的链式反应很好。", "explanation": "这里应该用〈成绩〉。链式反应不是成绩，不能用来评价一个人这次比赛的表现。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "链式反应", "is_correct": true, "explanation": "正确。“真是链式反应”用来形容一件事接连引起的连锁后果，与“全家都晚了”相符。"}, {"text": "牙膏", "is_correct": false, "explanation": "语义：“牙膏”是日用品，不能用来形容一连串的连锁结果。"}, {"text": "流体力学", "is_correct": false, "explanation": "语域：“流体力学”是学术术语，不适合用在日常口语的感叹句中。"}, {"text": "图书馆", "is_correct": false, "explanation": "语义：“图书馆”指一个场所，不能用来概括这种接连发生的结果。"}], "explanations": {"链式反应": "正确。“真是链式反应”用来形容一件事接连引起的连锁后果，与“全家都晚了”相符。", "牙膏": "语义：“牙膏”是日用品，不能用来形容一连串的连锁结果。", "流体力学": "语域：“流体力学”是学术术语，不适合用在日常口语的感叹句中。", "图书馆": "语义：“图书馆”指一个场所，不能用来概括这种接连发生的结果。"}, "sentence_index": 6, "correct_answer": "链式反应"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家对这个活动的链式反应很高。", "explanation": "这里应该用〈热情〉。链式反应描述事件的连续发生，不能用来表示人的热情高低。"}, {"text": "她对老家的链式反应很深。", "explanation": "这里应该用〈感情〉。链式反应不是情感，不能用来表示对老家的感情深浅。"}, {"text": "他对这位老师的链式反应很好。", "explanation": "这里应该用〈印象〉。链式反应不表示对某人的印象好坏，应该用“印象”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个小失误就能引起到一场链式反应。", "corrected_sentence": "一个小失误就能引起一场链式反应。", "error_description": "补语错误：“引起”后直接带宾语，不能插入“到”。应删去“到”，改为“一个小失误就能引起一场链式反应。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一次小争执引起了一片链式反应。", "corrected_sentence": "一次小争执引起了一场链式反应。", "error_description": "量词错误：“片”用于叶子、田野等平面的东西，不能用于事件。“链式反应”可用量词“场”，应改为“一场链式反应”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4c8e51c3-3bfc-469e-9e97-3ab91a8e1540') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容一件事像在做仪式，很正式。", "primary_collocate": null, "pronunciation": "yí shì xìng", "ipa": "i˧˥ ʂʐ̩˥˩ ɕiŋ˥˩", "syllable_count": 3, "sentences": [{"text": "新年的第一顿饭很有仪式性。", "target_word": "仪式性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天泡茶的动作带着仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "毕业时的握手有点仪式性。", "target_word": "仪式性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个欢迎会太有仪式性，大家都很紧张。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把送礼物做得很有仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每次出门前都要照镜子，很有仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的晚餐不用太仪式性，随便吃吧。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "签字的动作看起来很仪式性。", "target_word": "仪式性", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打开箱子的过程有一种仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "升旗时大家站得笔直，非常有仪式性。", "target_word": "仪式性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "儀式性", "label": "繁体"}], "register": "中性", "sense_fingerprint": "仪式性：一件事做起来像仪式，很正式、很郑重", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '739f0140-8cbc-457e-8526-f10ae4204bc8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "仪式性", "is_correct": true, "explanation": "正确：“很有仪式性”形容这顿饭郑重、讲究形式，符合新年的氛围。"}, {"text": "竞争性", "is_correct": false, "explanation": "语义：“竞争性”指争夺胜负，与新年团圆的饭不相符。"}, {"text": "效率", "is_correct": false, "explanation": "搭配：“效率”用于工作、做事，不能用来形容一顿饭。"}, {"text": "攻击性", "is_correct": false, "explanation": "语义：“攻击性”与团圆、和气的氛围完全相反。"}], "explanations": {"仪式性": "正确：“很有仪式性”形容这顿饭郑重、讲究形式，符合新年的氛围。", "竞争性": "语义：“竞争性”指争夺胜负，与新年团圆的饭不相符。", "效率": "搭配：“效率”用于工作、做事，不能用来形容一顿饭。", "攻击性": "语义：“攻击性”与团圆、和气的氛围完全相反。"}, "sentence_index": 0, "correct_answer": "仪式性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们午饭吃得很仪式性，五分钟就完了。", "explanation": "这里应该用〈快〉。“仪式性”形容郑重讲究的仪式特点，与五分钟就吃完的快速相矛盾。"}, {"text": "他仪式性地打了个哈欠。", "explanation": "这里应该用〈无意识〉。“仪式性”指刻意、郑重地做事，打哈欠是无意识的生理反应，不能说“仪式性地”。"}, {"text": "他随口问了一句，语气很仪式性。", "explanation": "这里应该用〈随意〉。“仪式性”形容事情像在做仪式、很正式，不用来形容随口一问的语气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "仪式性", "is_correct": true, "explanation": "正确：“不用太仪式性”表示不必过于讲究形式，与后半句“随便吃吧”一致。"}, {"text": "随便", "is_correct": false, "explanation": "语义：“不用太随便”与后半句“随便吃吧”自相矛盾。"}, {"text": "马虎", "is_correct": false, "explanation": "搭配：“马虎”多形容做事、做作业不认真，不用来形容晚餐的形式。"}, {"text": "草率", "is_correct": false, "explanation": "语义：“草率”含不认真、不慎重之意，用在晚餐上语义不当。"}], "explanations": {"仪式性": "正确：“不用太仪式性”表示不必过于讲究形式，与后半句“随便吃吧”一致。", "随便": "语义：“不用太随便”与后半句“随便吃吧”自相矛盾。", "马虎": "搭配：“马虎”多形容做事、做作业不认真，不用来形容晚餐的形式。", "草率": "语义：“草率”含不认真、不慎重之意，用在晚餐上语义不当。"}, "sentence_index": 6, "correct_answer": "仪式性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "街边的小吃摊很仪式性，老板大声吆喝。", "explanation": "这里应该用〈热闹〉。“仪式性”形容事情像在做仪式、很正式，不用来形容街边小吃摊的吆喝。"}, {"text": "孩子们在操场上玩得很仪式性。", "explanation": "这里应该用〈活泼〉。“仪式性”形容郑重的仪式特点，不用来形容孩子玩耍的状态。"}, {"text": "他仪式性地打了个喷嚏。", "explanation": "这里应该用〈无意识〉。“仪式性”指刻意、郑重地做事，打喷嚏是无意识的生理反应，不能说“仪式性地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这一刻有很仪式性，大家都安静下来。", "corrected_sentence": "这一刻很有仪式性，大家都安静下来。", "error_description": "错误：“有很仪式性”，“很”与“有”的语序颠倒。正确：“很有仪式性”，“很”修饰“有”，“有”带宾语“仪式性”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次告别很有仪式性感，大家都很郑重。", "corrected_sentence": "这次告别很有仪式性，大家都很郑重。", "error_description": "错误：“仪式性感”，“仪式性”后不能加“感”；“仪式感”是名词，与形容词“仪式性”混用是常见错误。正确：“很有仪式性”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7fc5df72-7a7d-450b-9fca-b65c9e8b5d18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
