INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23188, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把身体放在椅子等东西上。", "primary_collocate": null, "pronunciation": "zuò", "ipa": "tsuo⁵¹", "syllable_count": 1, "sentences": [{"text": "请坐，喝杯茶吧。", "target_word": "坐", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他坐在椅子上看书。", "target_word": "坐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们坐在地上玩儿。", "target_word": "坐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里没有人坐，你坐吧。", "target_word": "坐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想坐在窗户旁边。", "target_word": "坐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师坐着给大家讲故事。", "target_word": "坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶每天坐在门口晒太阳。", "target_word": "坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你坐下来，我们慢慢说。", "target_word": "坐", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他坐了很久，腿有点儿累。", "target_word": "坐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们坐在沙发上看电视。", "target_word": "坐", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "坐着", "label": "体标"}, {"form": "坐了", "label": "体标"}, {"form": "坐下", "label": "复合"}], "register": "中性", "sense_fingerprint": "人坐下，臀部放在椅子、地面等东西上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c432fe6-4db2-4f87-8eb1-bd238a86f80d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23188, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "坐", "is_correct": true, "explanation": "正确：zuò（第四声）即“坐”，意思是把身体放在椅子等东西上。"}, {"text": "左", "is_correct": false, "explanation": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边。"}, {"text": "昨", "is_correct": false, "explanation": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天。"}, {"text": "错", "is_correct": false, "explanation": "cuò 与 zuò 声母不同（c 与 z），意思是错误。"}, {"text": "造", "is_correct": false, "explanation": "zào 与 zuò 韵母不同（ao 与 uo），意思是制造或建造。"}], "explanations": {"坐": "正确：zuò（第四声）即“坐”，意思是把身体放在椅子等东西上。", "左": "zuǒ（第三声）与 zuò（第四声）声调不同，意思是左边。", "昨": "zuó（第二声）与 zuò（第四声）声调不同，意思是昨天。", "错": "cuò 与 zuò 声母不同（c 与 z），意思是错误。", "造": "zào 与 zuò 韵母不同（ao 与 uo），意思是制造或建造。"}, "sentence_index": null, "correct_answer": "坐"}, "level_3": {"options": [{"text": "坐", "is_correct": true, "explanation": "正确：“请坐”是待客时请对方坐下，符合句意。"}, {"text": "走", "is_correct": false, "explanation": "语义：“走”是离开，与请人坐下喝茶的待客语境相反。"}, {"text": "跑", "is_correct": false, "explanation": "语义：“跑”是快速移动，请人跑着喝茶句意不通。"}, {"text": "躺", "is_correct": false, "explanation": "搭配：“请躺”不符合待客习惯，躺卧不能用来请人喝茶。"}], "explanations": {"坐": "正确：“请坐”是待客时请对方坐下，符合句意。", "走": "语义：“走”是离开，与请人坐下喝茶的待客语境相反。", "跑": "语义：“跑”是快速移动，请人跑着喝茶句意不通。", "躺": "搭配：“请躺”不符合待客习惯，躺卧不能用来请人喝茶。"}, "sentence_index": 0, "correct_answer": "坐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天晚上坐作业，很晚才睡觉。", "explanation": "这里应该用〈做〉。坐指把身体放在椅子等东西上，做作业要用做。"}, {"text": "他坐着一顶红帽子，很好看。", "explanation": "这里应该用〈戴〉。坐指身体放在椅子等上，戴帽子要用戴。"}, {"text": "我们每天坐一杯茶。", "explanation": "这里应该用〈喝〉。坐指身体放在椅子等东西上，喝茶要用喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23188, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "坐", "is_correct": true, "explanation": "正确：zuò（第四声）即“坐”，意思是把身体放在椅子等东西上。"}, {"text": "醉", "is_correct": false, "explanation": "zuì（第四声）与 zuò 韵母不同（ui 与 uo），意思是喝醉。"}, {"text": "嘴", "is_correct": false, "explanation": "zuǐ（第三声）与 zuò 韵母不同（ui 与 uo），且声调不同，意思是嘴巴。"}, {"text": "奏", "is_correct": false, "explanation": "zòu（第四声）与 zuò 韵母不同（ou 与 uo），意思是演奏。"}], "explanations": {"坐": "正确：zuò（第四声）即“坐”，意思是把身体放在椅子等东西上。", "醉": "zuì（第四声）与 zuò 韵母不同（ui 与 uo），意思是喝醉。", "嘴": "zuǐ（第三声）与 zuò 韵母不同（ui 与 uo），且声调不同，意思是嘴巴。", "奏": "zòu（第四声）与 zuò 韵母不同（ou 与 uo），意思是演奏。"}, "sentence_index": null, "correct_answer": "坐"}, "level_3": {"options": [{"text": "坐", "is_correct": true, "explanation": "正确：“坐在门口”描述人在门口的坐姿，与晒太阳的场景相符。"}, {"text": "跳", "is_correct": false, "explanation": "语义：“跳”是腾空的动作，不能说长时间待在门口晒太阳。"}, {"text": "飞", "is_correct": false, "explanation": "语义：人不会飞，“飞在门口”与场景矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "配价：“唱”不带“在＋处所”作补充，“唱在门口”不成立。"}], "explanations": {"坐": "正确：“坐在门口”描述人在门口的坐姿，与晒太阳的场景相符。", "跳": "语义：“跳”是腾空的动作，不能说长时间待在门口晒太阳。", "飞": "语义：人不会飞，“飞在门口”与场景矛盾。", "唱": "配价：“唱”不带“在＋处所”作补充，“唱在门口”不成立。"}, "sentence_index": 6, "correct_answer": "坐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐了三年牢，出来后变了很多。", "explanation": "“坐”用的是“坐牢”义，指被关押，不是把身体放在椅子等东西上，与目标义项不符。"}, {"text": "我们坐了三个小时的车，很累。", "explanation": "“坐”用的是“乘坐”义，指搭乘交通工具，不是把身体放在椅子等东西上。"}, {"text": "这座房子坐北朝南，采光很好。", "explanation": "“坐”用的是“坐向”义，指房屋朝向，不是把身体放在椅子等东西上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23188, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他坐了看书，没有说话。", "corrected_sentence": "他坐着看书，没有说话。", "error_description": "“坐了看书”错误：表示坐的状态持续要用“坐着”，“了”表示动作完成，不能接“看书”这样的持续动作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23188, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐下了去北京的火车。", "corrected_sentence": "他坐上了去北京的火车。", "error_description": "“坐下”错误：登上交通工具要用“坐上”，应为“坐上了去北京的火车”。“坐下”表示身体放在椅子等上，不能表示登车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a8872be9-c801-4bb0-b205-2f8a454cec2d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
