INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23192, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公交车是大家坐的、在路上跑的大车。", "primary_collocate": null, "pronunciation": "gōng jiāo chē", "ipa": "kʊŋ˥ tɕjɑʊ˥ ʈʂʰɤ˥", "syllable_count": 3, "sentences": [{"text": "我每天坐公交车上班。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车来了，我们快上车吧。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆公交车去火车站吗？", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的公交车上人很多。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家门口有一辆公交车。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在公交车上给老人让座。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我等了二十分钟公交车。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车比出租车便宜。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，公交车开得很慢。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在公交车上睡着了。", "target_word": "公交车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "辆", "label": "量词"}, {"form": "公交車", "label": "繁体"}, {"form": "公交车站", "label": "复合词"}], "register": "中性", "sense_fingerprint": "城市里供大家乘坐的公共汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bf9dc599-3173-4820-a892-52e831b34649') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公交车", "is_correct": true, "explanation": "公交车：是上班族常用的交通工具，符合“每天坐……上班”的句意。"}, {"text": "摩天轮", "is_correct": false, "explanation": "语义：摩天轮是游乐设施，不是上班的交通工具，与“上班”矛盾。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“坐”可以接“沙发”，但“坐沙发上班”不成立，“坐”后面接的是交通工具。"}, {"text": "游轮", "is_correct": false, "explanation": "语义：游轮用于旅游，不用于每天上班。"}], "explanations": {"公交车": "公交车：是上班族常用的交通工具，符合“每天坐……上班”的句意。", "摩天轮": "语义：摩天轮是游乐设施，不是上班的交通工具，与“上班”矛盾。", "沙发": "搭配：“坐”可以接“沙发”，但“坐沙发上班”不成立，“坐”后面接的是交通工具。", "游轮": "语义：游轮用于旅游，不用于每天上班。"}, "sentence_index": 0, "correct_answer": "公交车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家门口停着一只公交车。", "explanation": "量词错误：公交车应该用〈辆〉。“只”多用于动物，不用来数车。"}, {"text": "我家门口停着一本公交车。", "explanation": "量词错误：公交车应该用〈辆〉。“本”用于书册，不用来数车。"}, {"text": "我家门口停着一条公交车。", "explanation": "量词错误：公交车应该用〈辆〉。“条”多用于细长的东西，不用来数车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公交车", "is_correct": true, "explanation": "公交车：可以等待、乘坐的交通工具，符合“等了二十分钟”的句意。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不是可以等待的对象，句意不通。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是人们等待乘坐的东西，与“等”的意思不合。"}, {"text": "数字", "is_correct": false, "explanation": "搭配：“等”后面接的是人、车或事件，一般不接“数字”。"}], "explanations": {"公交车": "公交车：可以等待、乘坐的交通工具，符合“等了二十分钟”的句意。", "空气": "语义：空气不是可以等待的对象，句意不通。", "阳光": "语义：阳光不是人们等待乘坐的东西，与“等”的意思不合。", "数字": "搭配：“等”后面接的是人、车或事件，一般不接“数字”。"}, "sentence_index": 6, "correct_answer": "公交车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天骑公交车上班，很方便。", "explanation": "这里应该用〈自行车〉。“骑”用于自行车、摩托车等，不能用于公交车；乘坐公交车要用“坐”。"}, {"text": "我每天打公交车上班，很方便。", "explanation": "这里应该用〈出租车〉。“打”用于出租车（打车），公交车不能说“打”；乘坐公交车要用“坐”。"}, {"text": "他每天骑公交车送货，很辛苦。", "explanation": "这里应该用〈摩托车〉。“骑”用于摩托车、自行车，公交车要用“坐”或“开”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "下班的时候，一本公交车总是很挤。", "corrected_sentence": "下班的时候，一辆公交车总是很挤。", "error_description": "错误：“本”用于书册，不能用来数车。正确：公交车的量词是“辆”，应写作“一辆公交车”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "等了很久，一条公交车终于来了。", "corrected_sentence": "等了很久，一辆公交车终于来了。", "error_description": "错误：“条”多用于细长的东西，不能用来数公交车。正确：公交车的量词是“辆”，应写作“一辆公交车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8790e4c8-b8b8-4a42-8c87-e897bb8be11a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
