INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23194, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人和大自然在一起。", "primary_collocate": null, "pronunciation": "rén yǔ zì rán", "ipa": "ɻən˧˥ y˨˩˦ tsɨ˥˩ ɻan˧˥", "syllable_count": 4, "sentences": [{"text": "周末我们去山里，感受人与自然。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍的是人与自然。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的画里有人与自然在一起的美。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "住在森林边，人与自然离得很近。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园让人与自然靠得更近。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春天来了，人与自然都很快乐。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她最喜欢人与自然合在一起的画面。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在草原上，人与自然是一家人。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的故事发生在山里，人与自然在一起。", "target_word": "人与自然", "complexity_tier": "T3", "furigana": "zhè běn shū de gù shi fā shēng zài shān lǐ, rén yǔ zì rán zài yì qǐ.", "sentence_source": "generated"}, {"text": "孩子们喜欢人与自然的活动。", "target_word": "人与自然", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "通用", "sense_fingerprint": "人与自然|名词|人和大自然在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fbc18688-d601-46ef-99b3-ee748b978efe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23194, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "人与自然", "is_correct": true, "explanation": "正确。“去山里感受”指人与大自然在一起的体验，与句子的语境相符。"}, {"text": "人与网络", "is_correct": false, "explanation": "语义：去山里感受的是大自然，“人与网络”与这一语境不符。"}, {"text": "人与金钱", "is_correct": false, "explanation": "搭配：“感受”通常搭配自然景象或情感，不说“感受人与金钱”。"}, {"text": "人与手机", "is_correct": false, "explanation": "语义：句子描写的是去山里的体验，“人与手机”与这一语境相悖。"}], "explanations": {"人与自然": "正确。“去山里感受”指人与大自然在一起的体验，与句子的语境相符。", "人与网络": "语义：去山里感受的是大自然，“人与网络”与这一语境不符。", "人与金钱": "搭配：“感受”通常搭配自然景象或情感，不说“感受人与金钱”。", "人与手机": "语义：句子描写的是去山里的体验，“人与手机”与这一语境相悖。"}, "sentence_index": 0, "correct_answer": "人与自然"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "朋友住在同一层楼，人与自然离得很近。", "explanation": "这里应该用〈人与人〉。人与自然指人和大自然在一起，住在同一层楼的朋友之间不能这样说。"}, {"text": "工厂里，人与自然配合得很默契。", "explanation": "这里应该用〈人与机器〉。人与自然指人和大自然在一起，工厂里的配合是人与机器之间的。"}, {"text": "这家饭店很热闹，人与自然都很开心。", "explanation": "这里误把〈人与自然〉当成了“人们”的意思。人与自然指人和大自然在一起，饭店里的顾客应说“人们”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23194, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人与自然", "is_correct": true, "explanation": "正确。“人与自然合在一起的画面”指人和大自然在一起的景象，符合“画面”的描绘对象。"}, {"text": "人与合同", "is_correct": false, "explanation": "语义：「合同」是法律文书，不是常见的入画景象，与「喜欢合在一起的画面」不搭。"}, {"text": "人与税收", "is_correct": false, "explanation": "语义：“税收”是经济制度，不是可以入画的景象，与句意不符。"}, {"text": "人与账单", "is_correct": false, "explanation": "语义：“账单”与画面、喜欢的场景没有关系，句子不通。"}], "explanations": {"人与自然": "正确。“人与自然合在一起的画面”指人和大自然在一起的景象，符合“画面”的描绘对象。", "人与合同": "语义：「合同」是法律文书，不是常见的入画景象，与「喜欢合在一起的画面」不搭。", "人与税收": "语义：“税收”是经济制度，不是可以入画的景象，与句意不符。", "人与账单": "语义：“账单”与画面、喜欢的场景没有关系，句子不通。"}, "sentence_index": 6, "correct_answer": "人与自然"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "多年的朋友，我们的人与自然很深厚。", "explanation": "这里应该用〈友谊〉。人与自然指人和大自然在一起，朋友之间的情谊应说“友谊”。"}, {"text": "这台电脑的运行速度很快，人与自然也很流畅。", "explanation": "这里误把〈人与自然〉用成了“系统”的意思。人与自然指人和大自然在一起，电脑的流畅程度应说“系统”。"}, {"text": "这次聚会的人与自然很多，大家都很开心。", "explanation": "这里应该用〈人数〉。人与自然指人和大自然在一起，不能用来指聚会的人数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天的夜晚，人与自然地在一起，很安静。", "corrected_sentence": "夏天的夜晚，人与自然在一起，很安静。", "error_description": "错误：多加了“地”。“地”用在动词或形容词前表示状态，“人与自然”后不应加“地”。应说“人与自然在一起”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次旅行让我们感受到人与自然们的和谐。", "corrected_sentence": "这次旅行让我们感受到人与自然的和谐。", "error_description": "错误：“们”加在“自然”后面表示复数，但“自然”是不可数的概念。应说“人与自然的和谐”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b3d35fa5-2436-4b09-bda3-a99836b12fc7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
