INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "表示事情的基础或最重要的部分。", "primary_collocate": null, "pronunciation": "gēn běn", "ipa": "kən˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "信任是朋友之间的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公司把客人放在第一位，这是它的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只有找到事情的根本，才能把它做好。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "读书是提高自己的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "家庭是社会的根本，家人要互相照顾。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把安全当成工作的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "土地是农民生活的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意要守住诚信这个根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的习惯是成长的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡好觉是保持健康的根本。", "target_word": "根本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "根本性", "label": "复合"}], "register": "中性", "sense_fingerprint": "根本：名词，事情的基础或最重要的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b6593ee-69dd-4702-a75a-133640aee710') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "根本", "is_correct": true, "explanation": "正确：“根本”指事情的基础，用在“朋友之间的”语境中意思通顺。"}, {"text": "香蕉", "is_correct": false, "explanation": "语义：“香蕉”是水果，不能作为朋友之间的基础。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”多用于买卖，不说“朋友之间的价格”。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：“地毯”是铺在地上的物品，与朋友之间的关系无关。"}], "explanations": {"根本": "正确：“根本”指事情的基础，用在“朋友之间的”语境中意思通顺。", "香蕉": "语义：“香蕉”是水果，不能作为朋友之间的基础。", "价格": "搭配：“价格”多用于买卖，不说“朋友之间的价格”。", "地毯": "语义：“地毯”是铺在地上的物品，与朋友之间的关系无关。"}, "sentence_index": 0, "correct_answer": "根本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路的根本是一座山。", "explanation": "这里应该用〈尽头〉。“根本”指事情的基础或最重要的部分，不指路的终点位置。"}, {"text": "我找到了这个计划的一颗根本。", "explanation": "这里应该用〈个〉。“颗”用于圆形、小粒状的东西，抽象名词“根本”应用“个”。"}, {"text": "这个人的根本很漂亮。", "explanation": "这里应该用〈外表〉。“根本”指事物的基础或最重要部分，不指人的外貌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "根本", "is_correct": true, "explanation": "正确：“农民生活的根本”指生活的基础，与句中语境吻合。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“电影”是娱乐作品，不能作为农民生活的基础。"}, {"text": "口号", "is_correct": false, "explanation": "语义：“口号”是标语，不能作为农民生活的基础。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”是消遣，与土地对农民生活的作用不相符。"}], "explanations": {"根本": "正确：“农民生活的根本”指生活的基础，与句中语境吻合。", "电影": "语义：“电影”是娱乐作品，不能作为农民生活的基础。", "口号": "语义：“口号”是标语，不能作为农民生活的基础。", "游戏": "语义：“游戏”是消遣，与土地对农民生活的作用不相符。"}, "sentence_index": 6, "correct_answer": "根本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的根本很结实，经得起地震。", "explanation": "这里应该用〈地基〉。“根本”不指建筑的地基，房屋的地基应说“地基”。"}, {"text": "竹子的根本很长，能固定土壤。", "explanation": "这里应该用〈根〉。“根本”指基础或最重要的部分，不指植物的根。"}, {"text": "他是这支乐队的根本成员。", "explanation": "这里应该用〈核心〉。“根本”指抽象的基础，不用来指人，应说“核心成员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
