INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23196, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "规律作息是保持健康的一把根本。", "corrected_sentence": "规律作息是保持健康的根本。", "error_description": "错误形式“一把根本”，正确形式“根本”。“把”用于有柄的东西，抽象名词“根本”前不用“把”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4daadcca-6ec3-4c74-90a5-e38ffe8cd7bd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
