INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23200, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "空气污染就是脏脏的空气，会让我们咳嗽。", "primary_collocate": null, "pronunciation": "kōng qì wū rǎn", "ipa": "kʰʊŋ˥ tɕʰi˥˩ u˥ ɻan˨˩˦", "syllable_count": 4, "sentences": [{"text": "空气污染太重，我一直咳嗽。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子咳嗽，可能是因为空气污染。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气污染的日子，我们不出门玩。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说空气污染会让人咳嗽。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "路上车太多，空气污染很严重。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "空气污染让天空变得灰灰的。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "出门遇到空气污染，最好戴口罩。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这里空气污染厉害，我喉咙不舒服。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近空气污染少，孩子很少咳嗽。", "target_word": "空气污染", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为空气污染，学校今天没有上体育课。", "target_word": "空气污染", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "空气污染指数", "label": "复合"}], "register": "口语", "sense_fingerprint": "空气污染：脏脏的空气，让人咳嗽、不舒服", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24849d55-0b5a-4d61-b13f-ff8d3ff3a864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "空气污染", "is_correct": true, "explanation": "空气污染：空气被污染，污染太重会让人咳嗽，与句意一致。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业太重说的是学习负担，与咳嗽无关，句意不通。"}, {"text": "噪音", "is_correct": false, "explanation": "语义：噪音太重与一直咳嗽无关，句意不通。"}, {"text": "行李", "is_correct": false, "explanation": "语义：行李太重不会让人一直咳嗽，句意不通。"}], "explanations": {"空气污染": "空气污染：空气被污染，污染太重会让人咳嗽，与句意一致。", "作业": "语义：作业太重说的是学习负担，与咳嗽无关，句意不通。", "噪音": "语义：噪音太重与一直咳嗽无关，句意不通。", "行李": "语义：行李太重不会让人一直咳嗽，句意不通。"}, "sentence_index": 0, "correct_answer": "空气污染"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这里的空气污染很差，我们不想住。", "explanation": "这里应该用〈空气质量〉。评价空气好坏用“空气质量”，“空气污染”指污染现象，不说“很差”。"}, {"text": "他每天早上去公园，深深地吸了一口空气污染，觉得很清爽。", "explanation": "这里应该用〈清新的空气〉。“吸”的是空气本身，“空气污染”指污染现象，不能像空气一样吸入。"}, {"text": "山上的空气污染很新鲜，我们去呼吸吧。", "explanation": "这里应该用〈清新的空气〉。“新鲜”形容的是清新的空气，“空气污染”指污染现象，不能说新鲜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "空气污染", "is_correct": true, "explanation": "空气污染：出门可能遇到的脏空气，戴口罩可以防护。"}, {"text": "交通", "is_correct": false, "explanation": "语义：遇到交通不需要戴口罩，与“最好戴口罩”不符。"}, {"text": "烈日", "is_correct": false, "explanation": "语义：烈日需要遮阳，不需要口罩，与句意冲突。"}, {"text": "疲劳", "is_correct": false, "explanation": "搭配：“遇到”后接具体事物，“疲劳”是状态，应说“感到疲劳”，且与戴口罩无关。"}], "explanations": {"空气污染": "空气污染：出门可能遇到的脏空气，戴口罩可以防护。", "交通": "语义：遇到交通不需要戴口罩，与“最好戴口罩”不符。", "烈日": "语义：烈日需要遮阳，不需要口罩，与句意冲突。", "疲劳": "搭配：“遇到”后接具体事物，“疲劳”是状态，应说“感到疲劳”，且与戴口罩无关。"}, "sentence_index": 6, "correct_answer": "空气污染"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天早上喝了一杯空气污染。", "explanation": "这里应该用〈牛奶〉。“喝”的是饮品，“空气污染”指污染现象，不能喝。"}, {"text": "这条河的空气污染很严重，鱼都死了。", "explanation": "这里应该用〈水污染〉。“空气污染”只指大气中的污染，河水被污染应说“水污染”。"}, {"text": "他得了空气污染，要住院治疗。", "explanation": "这里应该用〈肺炎〉。“得了”后接疾病，“空气污染”是环境问题，不是疾病。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一台很严重的空气污染。", "corrected_sentence": "这是一种很严重的空气污染。", "error_description": "量词错误：“空气污染”前应用量词“种”，“台”只用于机器、电器，应说“一种很严重的空气污染”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这里一台空气污染很重。", "corrected_sentence": "这里空气污染很重。", "error_description": "量词错误：“空气污染”前不能加量词“台”（“台”用于机器、电器），此处不加量词，应说“这里空气污染很重”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
