INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23202, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "公交车是大家坐的车，在路上跑，带人去想去的地方。", "primary_collocate": null, "pronunciation": "gōng jiāo", "ipa": "kʊŋ˥ tɕjɑʊ˥", "syllable_count": 2, "sentences": [{"text": "我每天坐公交去上班。", "target_word": "公交", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我家门口有公交，去学校很方便。", "target_word": "公交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雨天，公交上的人特别多。", "target_word": "公交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公交到站了，大家一个一个上车。", "target_word": "公交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他没赶上公交，只好走路回家。", "target_word": "公交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "早上的公交很挤，我常常站着。", "target_word": "公交", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐公交去机场要一个半小时。", "target_word": "公交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在公交上看见了一位老朋友。", "target_word": "公交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈不会开车，出门都坐公交。", "target_word": "公交", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生坐公交可以便宜两块钱。", "target_word": "公交", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "公交车", "label": "复合"}, {"form": "公交站", "label": "复合"}], "register": "中性", "sense_fingerprint": "城市里大家乘坐的公共汽车", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5b76edc4-0981-45f9-b40b-13826adb3d03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23202, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "公交", "is_correct": true, "explanation": "正确：“公交”是城市里大家乘坐的公共汽车，可以坐着去上班。"}, {"text": "公园", "is_correct": false, "explanation": "语义：“公园”是地点，不是可以乘坐的车辆，句子不通。"}, {"text": "桌子", "is_correct": false, "explanation": "搭配：“坐”后面要接可以乘坐的东西，不能说“坐桌子去上班”。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“坐沙发”是坐在沙发上，不能说“坐沙发去上班”。"}], "explanations": {"公交": "正确：“公交”是城市里大家乘坐的公共汽车，可以坐着去上班。", "公园": "语义：“公园”是地点，不是可以乘坐的车辆，句子不通。", "桌子": "搭配：“坐”后面要接可以乘坐的东西，不能说“坐桌子去上班”。", "沙发": "搭配：“坐沙发”是坐在沙发上，不能说“坐沙发去上班”。"}, "sentence_index": 0, "correct_answer": "公交"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我打了一辆公交去机场。", "explanation": "这里应该用〈出租车〉。“打车”说的是乘出租车，公交车要说“坐”或“乘”，不能用“打”。"}, {"text": "我坐了一只公交去医院。", "explanation": "这里应该用〈辆〉。“只”多用于动物或成对的东西，公交车是车辆，量词要用〈辆〉。"}, {"text": "车站门口停着一条公交。", "explanation": "这里应该用〈辆〉。〈条〉用于细长的东西，不用于车辆，公交车要用〈辆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23202, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公交", "is_correct": true, "explanation": "正确：“公交”是可以乘坐的公共汽车，能坐着去机场。"}, {"text": "椅子", "is_correct": false, "explanation": "搭配：“坐”后面接椅子是坐在椅子上，不能说“坐椅子去机场”。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能用来乘坐，“坐手机去机场”句子不通。"}, {"text": "花园", "is_correct": false, "explanation": "语义：“花园”是地点，不能乘坐去机场，整句不通。"}], "explanations": {"公交": "正确：“公交”是可以乘坐的公共汽车，能坐着去机场。", "椅子": "搭配：“坐”后面接椅子是坐在椅子上，不能说“坐椅子去机场”。", "手机": "语义：手机不能用来乘坐，“坐手机去机场”句子不通。", "花园": "语义：“花园”是地点，不能乘坐去机场，整句不通。"}, "sentence_index": 6, "correct_answer": "公交"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天骑公交去学校。", "explanation": "这里应该用〈自行车〉。“骑”用于自行车、摩托车等，公交车是要乘坐的，不能说“骑公交”。"}, {"text": "路边有一座公交。", "explanation": "这里应该用〈辆〉。〈座〉用于山、桥、楼房等大型固定的东西，公交车要用〈辆〉。"}, {"text": "车站门口停着一块公交。", "explanation": "这里应该用〈辆〉。〈块〉用于块状的东西，不用于车辆，公交车要用〈辆〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23202, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈每天坐了公交去菜市场。", "corrected_sentence": "妈妈每天坐公交去菜市场。", "error_description": "体标错误：“每天”表示习惯性动作，不能与“了”搭配，应说“每天坐公交”，去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23202, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车站里停着一本公交。", "corrected_sentence": "车站里停着一辆公交。", "error_description": "量词错误：公交车是车辆，应该用“辆”，“本”是书册的量词，不能用来说公交车。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7df9bc8-1bcf-43c8-be31-eb6336a223a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
