INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23204, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很脏的东西。", "primary_collocate": null, "pronunciation": "zāng dōng xi", "ipa": "tsɑŋ˥ tʊŋ˥ ɕi", "syllable_count": 3, "sentences": [{"text": "地上有很多脏东西，快扫一扫。", "target_word": "脏东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "手上有脏东西，吃饭前要洗手。", "target_word": "脏东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把桌子上的脏东西擦掉了。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的眼睛里进了脏东西，一直流眼泪。", "target_word": "脏东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "鞋底有很多脏东西，别踩到干净的地毯上。", "target_word": "脏东西", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水里有脏东西，鱼都不见了。", "target_word": "脏东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰箱角落里有一堆脏东西，黏糊糊的，快扔掉吧。", "target_word": "脏东西", "complexity_tier": "T3", "furigana": "bīng xiāng jiǎo luò lǐ yǒu yī duī zāng dōng xi, nián hū hū de, kuài rēng diào ba.", "sentence_source": "generated"}, {"text": "妈妈用湿布擦掉窗户上的脏东西。", "target_word": "脏东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些脏东西不能放进嘴里。", "target_word": "脏东西", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "洗衣机能洗掉衣服上的脏东西。", "target_word": "脏东西", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一堆脏东西", "label": "量词"}], "register": "口语", "sense_fingerprint": "脏东西：又脏又不干净的东西，如灰尘、污物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24849d55-0b5a-4d61-b13f-ff8d3ff3a864') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23204, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脏东西", "is_correct": true, "explanation": "正确：地上又脏又不干净的东西，正是要扫的“脏东西”。"}, {"text": "硬币", "is_correct": false, "explanation": "搭配：“扫”用于碎屑、垃圾，不用于散落的硬币，硬币应该捡起来。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：钞票有价值，不会被当作要扫掉的东西，与句意不合。"}, {"text": "宝石", "is_correct": false, "explanation": "语义：宝石是贵重物品，不是要扫掉的污物，与“快扫一扫”矛盾。"}], "explanations": {"脏东西": "正确：地上又脏又不干净的东西，正是要扫的“脏东西”。", "硬币": "搭配：“扫”用于碎屑、垃圾，不用于散落的硬币，硬币应该捡起来。", "钞票": "语义：钞票有价值，不会被当作要扫掉的东西，与句意不合。", "宝石": "语义：宝石是贵重物品，不是要扫掉的污物，与“快扫一扫”矛盾。"}, "sentence_index": 0, "correct_answer": "脏东西"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把刚消过毒的碗碟说成了脏东西。", "explanation": "这里应该用〈餐具〉。脏东西指很脏的东西，刚消过毒的碗碟不脏，不能这样说。"}, {"text": "爸爸在桌上放了一堆脏东西，还说是给我的生日礼物。", "explanation": "这里应该用〈礼品〉。脏东西指很脏的东西，生日礼品不脏，不能说成脏东西。"}, {"text": "他把脏东西小心地放进盒子里，那是一条刚洗过的珍珠项链。", "explanation": "这里应该用〈饰品〉。脏东西指很脏的东西，刚洗过的珍珠项链是干净的饰品，不能说成脏东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23204, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "脏东西", "is_correct": true, "explanation": "正确：黏糊糊、要扔掉的一堆污物，正是“脏东西”。"}, {"text": "金子", "is_correct": false, "explanation": "语义：金子是贵重的，不会黏糊糊的要扔掉，与句意矛盾。"}, {"text": "积木", "is_correct": false, "explanation": "体貌：“黏糊糊”是污物的质地，积木没有这种质地。"}, {"text": "书本", "is_correct": false, "explanation": "语义：书本不是黏糊糊的污物，与“快扔掉吧”的语境不合。"}], "explanations": {"脏东西": "正确：黏糊糊、要扔掉的一堆污物，正是“脏东西”。", "金子": "语义：金子是贵重的，不会黏糊糊的要扔掉，与句意矛盾。", "积木": "体貌：“黏糊糊”是污物的质地，积木没有这种质地。", "书本": "语义：书本不是黏糊糊的污物，与“快扔掉吧”的语境不合。"}, "sentence_index": 6, "correct_answer": "脏东西"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这盆绿植浇过水，叶子油亮，全家都觉得它是脏东西。", "explanation": "这里应该用〈花草〉。脏东西指很脏的东西，浇过水、叶子油亮的绿植不脏，不能说成脏东西。"}, {"text": "爸爸在桌上摆着一盘刚煮好的饺子，我却说它是脏东西。", "explanation": "这里应该用〈美食〉。脏东西指很脏的东西，刚煮好的饺子是干净的食物，不能说成脏东西。"}, {"text": "他把擦得亮晶晶的脏东西放回抽屉，那是一枚金戒指。", "explanation": "这里应该用〈首饰〉。脏东西指很脏的东西，擦得亮晶晶的金戒指是干净的首饰，不能说成脏东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23204, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌上有很多脏东西们，快去擦干净。", "corrected_sentence": "桌上有很多脏东西，快去擦干净。", "error_description": "错误：“脏东西们”；正确：“脏东西”。“们”只用于指人的名词，“脏东西”是物品，不能加“们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (23204, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "床底下有一根脏东西，快去清理。", "corrected_sentence": "床底下有一堆脏东西，快去清理。", "error_description": "错误：“一根脏东西”；正确：“一堆脏东西”。“根”只用于细长条状的东西，“脏东西”应用“一堆”来量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd54a3515-a146-4d6a-8e13-4b3933f44b1c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
